class GitaVerse {
  final int chapter;
  final int verse;
  final String sanskrit;
  final String transliteration;
  final String meaning;
  final String inShort;
  const GitaVerse({required this.chapter, required this.verse, required this.sanskrit, required this.transliteration, required this.meaning, required this.inShort});
}

const gitaVerses = <GitaVerse>[
  GitaVerse(chapter: 1, verse: 1, sanskrit: 'धृतराष्ट्र उवाच |\nधर्मक्षेत्रे कुरुक्षेत्रे समवेता युयुत्सवः |\nमामकाः पाण्डवाश्चैव किमकुर्वत सञ्जय', transliteration: 'dhṛtarāṣṭra uvāca .\ndharmakṣetre kurukṣetre samavetā yuyutsavaḥ .\nmāmakāḥ pāṇḍavāścaiva kimakurvata sañjaya', meaning: 'Dhritarashtra said: On the field of dharma, at Kurukshetra, gathered and eager to fight, what did my people and the sons of Pandu do, O Sanjaya?', inShort: 'Dhritarashtra asks what happened on the battlefield.'),
  GitaVerse(chapter: 1, verse: 2, sanskrit: 'सञ्जय उवाच |\nदृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा |\nआचार्यमुपसंगम्य राजा वचनमब्रवीत्', transliteration: 'sañjaya uvāca .\ndṛṣṭvā tu pāṇḍavānīkaṃ vyūḍhaṃ duryodhanastadā .\nācāryamupasaṃgamya rājā vacanamabravīt', meaning: 'Sanjaya said: Seeing the Pandava army arrayed for battle, King Duryodhana approached his teacher Drona and spoke these words.', inShort: 'Duryodhana goes to his teacher Drona.'),
  GitaVerse(chapter: 1, verse: 3, sanskrit: 'पश्यैतां पाण्डुपुत्राणामाचार्य महतीं चमूम् |\nव्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता', transliteration: 'paśyaitāṃ pāṇḍuputrāṇāmācārya mahatīṃ camūm .\nvyūḍhāṃ drupadaputreṇa tava śiṣyeṇa dhīmatā', meaning: 'Behold, O teacher, this mighty army of the sons of Pandu, arrayed by your gifted pupil, the son of Drupada.', inShort: 'Duryodhana points out the Pandava army.'),
  GitaVerse(chapter: 1, verse: 4, sanskrit: 'अत्र शूरा महेष्वासा भीमार्जुनसमा युधि |\nयुयुधानो विराटश्च द्रुपदश्च महारथः', transliteration: 'atra śūrā maheṣvāsā bhīmārjunasamā yudhi .\nyuyudhāno virāṭaśca drupadaśca mahārathaḥ', meaning: 'Here are heroes and mighty archers, equal in battle to Bhima and Arjuna: Yuyudhana, Virata, and Drupada, the great warrior.', inShort: 'He names great warriors on the enemy side.'),
  GitaVerse(chapter: 1, verse: 5, sanskrit: 'धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान् |\nपुरुजित्कुन्तिभोजश्च शैब्यश्च नरपुंगवः', transliteration: 'dhṛṣṭaketuścekitānaḥ kāśirājaśca vīryavān .\npurujitkuntibhojaśca śaibyaśca narapuṃgavaḥ', meaning: 'Dhrishtaketu, Chekitana, and the valiant king of Kashi; Purujit, Kuntibhoja, and Shaibya, the best of men.', inShort: 'More mighty warriors are named.'),
  GitaVerse(chapter: 1, verse: 6, sanskrit: 'युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान् |\nसौभद्रो द्रौपदेयाश्च सर्व एव महारथाः', transliteration: 'yudhāmanyuśca vikrānta uttamaujāśca vīryavān .\nsaubhadro draupadeyāśca sarva eva mahārathāḥ', meaning: 'The heroic Yudhamanyu and the brave Uttamaujas; the son of Subhadra and the sons of Draupadi, all great warriors.', inShort: 'Still more great fighters are listed.'),
  GitaVerse(chapter: 1, verse: 7, sanskrit: 'अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम |\nनायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते', transliteration: 'asmākaṃ tu viśiṣṭā ye tānnibodha dvijottama .\nnāyakā mama sainyasya saṃjñārthaṃ tānbravīmi te', meaning: 'Know also, O best of the twice-born, the most distinguished among us, the leaders of my army; I name them for you.', inShort: 'Duryodhana turns to his own commanders.'),
  GitaVerse(chapter: 1, verse: 8, sanskrit: 'भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः |\nअश्वत्थामा विकर्णश्च सौमदत्तिस्तथैव च', transliteration: 'bhavānbhīṣmaśca karṇaśca kṛpaśca samitiñjayaḥ .\naśvatthāmā vikarṇaśca saumadattistathaiva ca', meaning: 'Yourself and Bhishma, and Karna, and Kripa, ever victorious in battle; Ashvatthama, Vikarna, and the son of Somadatta.', inShort: 'He names his own great warriors.'),
  GitaVerse(chapter: 1, verse: 9, sanskrit: 'अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः |\nनानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः', transliteration: 'anye ca bahavaḥ śūrā madarthe tyaktajīvitāḥ .\nnānāśastrapraharaṇāḥ sarve yuddhaviśāradāḥ', meaning: 'And many other heroes, ready to give their lives for me, armed with various weapons, all skilled in war.', inShort: 'Many heroes stand ready to die for him.'),
  GitaVerse(chapter: 1, verse: 10, sanskrit: 'अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम् |\nपर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम्', transliteration: 'aparyāptaṃ tadasmākaṃ balaṃ bhīṣmābhirakṣitam .\nparyāptaṃ tvidameteṣāṃ balaṃ bhīmābhirakṣitam', meaning: 'Our army, guarded by Bhishma, is unlimited; but their army, guarded by Bhima, is limited.', inShort: 'Duryodhana weighs the two armies.'),
  GitaVerse(chapter: 1, verse: 11, sanskrit: 'अयनेषु च सर्वेषु यथाभागमवस्थिताः |\nभीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि', transliteration: 'ayaneṣu ca sarveṣu yathābhāgamavasthitāḥ .\nbhīṣmamevābhirakṣantu bhavantaḥ sarva eva hi', meaning: 'Therefore all of you, holding your positions on every front, protect Bhishma above all.', inShort: 'He tells everyone to protect Bhishma.'),
  GitaVerse(chapter: 1, verse: 12, sanskrit: 'तस्य सञ्जनयन्हर्षं कुरुवृद्धः पितामहः |\nसिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान्', transliteration: 'tasya sañjanayanharṣaṃ kuruvṛddhaḥ pitāmahaḥ .\nsiṃhanādaṃ vinadyoccaiḥ śaṅkhaṃ dadhmau pratāpavān', meaning: 'Then, cheering him, the aged grandsire of the Kurus, the mighty Bhishma, roared like a lion and loudly blew his conch.', inShort: 'Bhishma blows his conch like a lion\'s roar.'),
  GitaVerse(chapter: 1, verse: 13, sanskrit: 'ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः |\nसहसैवाभ्यहन्यन्त स शब्दस्तुमुलोऽभवत्', transliteration: 'tataḥ śaṅkhāśca bheryaśca paṇavānakagomukhāḥ .\nsahasaivābhyahanyanta sa śabdastumulo.abhavat', meaning: 'Then conches, kettledrums, cymbals, drums, and trumpets suddenly blared forth, and the sound was tremendous.', inShort: 'A great blast of war instruments erupts.'),
  GitaVerse(chapter: 1, verse: 14, sanskrit: 'ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ |\nमाधवः पाण्डवश्चैव दिव्यौ शङ्खौ प्रदध्मतुः', transliteration: 'tataḥ śvetairhayairyukte mahati syandane sthitau .\nmādhavaḥ pāṇḍavaścaiva divyau śaṅkhau pradadhmatuḥ', meaning: 'Then, seated in their great chariot yoked with white horses, Krishna and Arjuna blew their divine conches.', inShort: 'Krishna and Arjuna sound their divine conches.'),
  GitaVerse(chapter: 1, verse: 15, sanskrit: 'पाञ्चजन्यं हृषीकेशो देवदत्तं धनञ्जयः |\nपौण्ड्रं दध्मौ महाशङ्खं भीमकर्मा वृकोदरः', transliteration: 'pāñcajanyaṃ hṛṣīkeśo devadattaṃ dhanañjayaḥ .\npauṇḍraṃ dadhmau mahāśaṅkhaṃ bhīmakarmā vṛkodaraḥ', meaning: 'Krishna blew the Panchajanya and Arjuna the Devadatta; Bhima of terrible deeds blew his great conch, Paundra.', inShort: 'Krishna, Arjuna, and Bhima blow their conches.'),
  GitaVerse(chapter: 1, verse: 16, sanskrit: 'अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः |\nनकुलः सहदेवश्च सुघोषमणिपुष्पकौ', transliteration: 'anantavijayaṃ rājā kuntīputro yudhiṣṭhiraḥ .\nnakulaḥ sahadevaśca sughoṣamaṇipuṣpakau', meaning: 'King Yudhishthira blew the Anantavijaya; Nakula and Sahadeva blew the Sughosha and the Manipushpaka.', inShort: 'The other Pandava brothers sound their conches.'),
  GitaVerse(chapter: 1, verse: 17, sanskrit: 'काश्यश्च परमेष्वासः शिखण्डी च महारथः |\nधृष्टद्युम्नो विराटश्च सात्यकिश्चापराजितः', transliteration: 'kāśyaśca parameṣvāsaḥ śikhaṇḍī ca mahārathaḥ .\ndhṛṣṭadyumno virāṭaśca sātyakiścāparājitaḥ', meaning: 'The great archer king of Kashi, and Shikhandi the mighty warrior; Dhrishtadyumna, Virata, and the unconquered Satyaki;', inShort: 'More Pandava allies join the sounding.'),
  GitaVerse(chapter: 1, verse: 18, sanskrit: 'द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते |\nसौभद्रश्च महाबाहुः शङ्खान्दध्मुः पृथक्पृथक्', transliteration: 'drupado draupadeyāśca sarvaśaḥ pṛthivīpate .\nsaubhadraśca mahābāhuḥ śaṅkhāndadhmuḥ pṛthakpṛthak', meaning: 'Drupada and the sons of Draupadi, O lord of the earth, and the strong-armed son of Subhadra, all blew their conches.', inShort: 'All the allies blow their conches together.'),
  GitaVerse(chapter: 1, verse: 19, sanskrit: 'स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत् |\nनभश्च पृथिवीं चैव तुमुलोऽभ्यनुनादयन् (or लोव्यनु)', transliteration: 'sa ghoṣo dhārtarāṣṭrāṇāṃ hṛdayāni vyadārayat .\nnabhaśca pṛthivīṃ caiva tumulo.abhyanunādayan (lo vyanu)', meaning: 'That tumultuous sound, echoing through heaven and earth, tore apart the hearts of Dhritarashtra\'s sons.', inShort: 'The roar shakes the hearts of the enemy.'),
  GitaVerse(chapter: 1, verse: 20, sanskrit: 'अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान् कपिध्वजः |\nप्रवृत्ते शस्त्रसम्पाते धनुरुद्यम्य पाण्डवः |\nहृषीकेशं तदा वाक्यमिदमाह महीपते', transliteration: 'atha vyavasthitāndṛṣṭvā dhārtarāṣṭrān kapidhvajaḥ .\npravṛtte śastrasampāte dhanurudyamya pāṇḍavaḥ', meaning: 'Then, O king, seeing Dhritarashtra\'s men arrayed and the fighting about to begin, Arjuna, whose banner bore Hanuman, raised his bow.', inShort: 'Arjuna, banner of Hanuman, lifts his bow.'),
  GitaVerse(chapter: 1, verse: 21, sanskrit: 'अर्जुन उवाच |\nसेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत', transliteration: 'hṛṣīkeśaṃ tadā vākyamidamāha mahīpate .\narjuna uvāca .\nsenayorubhayormadhye rathaṃ sthāpaya me.acyuta', meaning: 'And he said to Krishna: O changeless one, draw up my chariot between the two armies,', inShort: 'Arjuna asks Krishna to drive between the armies.'),
  GitaVerse(chapter: 1, verse: 22, sanskrit: 'यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान् |\nकैर्मया सह योद्धव्यमस्मिन् रणसमुद्यमे', transliteration: 'yāvadetānnirikṣe.ahaṃ yoddhukāmānavasthitān .\nkairmayā saha yoddhavyamasmin raṇasamudyame', meaning: 'so that I may see those arrayed here, eager to fight, and know with whom I must contend in this coming battle.', inShort: 'He wants to see whom he must fight.'),
  GitaVerse(chapter: 1, verse: 23, sanskrit: 'योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः |\nधार्तराष्ट्रस्य दुर्बुद्धेर्युद्धे प्रियचिकीर्षवः', transliteration: 'yotsyamānānavekṣe.ahaṃ ya ete.atra samāgatāḥ .\ndhārtarāṣṭrasya durbuddheryuddhe priyacikīrṣavaḥ', meaning: 'Let me look upon those gathered here to fight, wishing to please the evil-minded son of Dhritarashtra.', inShort: 'He looks at those come to please Duryodhana.'),
  GitaVerse(chapter: 1, verse: 24, sanskrit: 'सञ्जय उवाच |\nएवमुक्तो हृषीकेशो गुडाकेशेन भारत |\nसेनयोरुभयोर्मध्ये स्थापयित्वा रथोत्तमम्', transliteration: 'sañjaya uvāca .\nevamukto hṛṣīkeśo guḍākeśena bhārata .\nsenayorubhayormadhye sthāpayitvā rathottamam', meaning: 'Sanjaya said: Thus addressed by Arjuna, O Bharata, Krishna drew up the great chariot between the two armies.', inShort: 'Krishna halts the chariot between the armies.'),
  GitaVerse(chapter: 1, verse: 25, sanskrit: 'भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम् |\nउवाच पार्थ पश्यैतान्समवेतान्कुरूनिति', transliteration: 'bhīṣmadroṇapramukhataḥ sarveṣāṃ ca mahīkṣitām .\nuvāca pārtha paśyaitānsamavetānkurūniti', meaning: 'In front of Bhishma, Drona, and all the kings, he said: O Partha, behold these Kurus gathered here.', inShort: 'Krishna: behold your kinsmen, the Kurus.'),
  GitaVerse(chapter: 1, verse: 26, sanskrit: 'तत्रापश्यत्स्थितान्पार्थः पितॄनथ पितामहान् |\nआचार्यान्मातुलान्भ्रातॄन्पुत्रान्पौत्रान्सखींस्तथा', transliteration: 'tatrāpaśyatsthitānpārthaḥ pitṝnatha pitāmahān .\nācāryānmātulānbhrātṛnputrānpautrānsakhīṃstathā', meaning: 'There Arjuna saw, standing in both armies, fathers and grandfathers, teachers, uncles, brothers, sons, grandsons, and friends,', inShort: 'Arjuna sees his own family in both armies.'),
  GitaVerse(chapter: 1, verse: 27, sanskrit: 'श्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि |\nतान्समीक्ष्य स कौन्तेयः सर्वान्बन्धूनवस्थितान्', transliteration: 'śvaśurānsuhṛdaścaiva senayorubhayorapi .\ntānsamīkṣya sa kaunteyaḥ sarvānbandhūnavasthitān', meaning: 'fathers-in-law and companions as well. Seeing all these kinsmen arrayed before him, the son of Kunti', inShort: 'He sees relatives and friends on every side.'),
  GitaVerse(chapter: 1, verse: 28, sanskrit: 'कृपया परयाविष्टो विषीदन्निदमब्रवीत् |\nअर्जुन उवाच |\nदृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम्', transliteration: 'kṛpayā parayāviṣṭo viṣīdannidamabravīt .\narjuna uvāca .\ndṛṣṭvemaṃ svajanaṃ kṛṣṇa yuyutsuṃ samupasthitam', meaning: 'was overcome with deep pity, and said sorrowfully: O Krishna, seeing my own people arrayed and eager to fight,', inShort: 'Overcome with pity, Arjuna begins to grieve.'),
  GitaVerse(chapter: 1, verse: 29, sanskrit: 'सीदन्ति मम गात्राणि मुखं च परिशुष्यति |\nवेपथुश्च शरीरे मे रोमहर्षश्च जायते', transliteration: 'sīdanti mama gātrāṇi mukhaṃ ca pariśuṣyati .\nvepathuśca śarīre me romaharṣaśca jāyate', meaning: 'my limbs give way and my mouth goes dry; my body trembles and my hair stands on end.', inShort: 'His body shakes; his mouth goes dry.'),
  GitaVerse(chapter: 1, verse: 30, sanskrit: 'गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते |\nन च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः', transliteration: 'gāṇḍīvaṃ sraṃsate hastāttvakcaiva paridahyate .\nna ca śaknomyavasthātuṃ bhramatīva ca me manaḥ', meaning: 'The bow Gandiva slips from my hand and my whole skin burns; I cannot stand steady, and my mind seems to reel.', inShort: 'His bow slips; his mind reels.'),
  GitaVerse(chapter: 1, verse: 31, sanskrit: 'निमित्तानि च पश्यामि विपरीतानि केशव |\nन च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे', transliteration: 'nimittāni ca paśyāmi viparītāni keśava .\nna ca śreyo.anupaśyāmi hatvā svajanamāhave', meaning: 'I see evil omens, O Krishna, and I foresee no good in killing my own people in battle.', inShort: 'He sees ill omens and no good in this war.'),
  GitaVerse(chapter: 1, verse: 32, sanskrit: 'न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च |\nकिं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा', transliteration: 'na kāṅkṣe vijayaṃ kṛṣṇa na ca rājyaṃ sukhāni ca .\nkiṃ no rājyena govinda kiṃ bhogairjīvitena vā', meaning: 'I long for neither victory, O Krishna, nor kingdom nor pleasures. What use is a kingdom to us, or enjoyment, or even life?', inShort: 'He wants no victory, kingdom, or pleasure.'),
  GitaVerse(chapter: 1, verse: 33, sanskrit: 'येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च |\nत इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च', transliteration: 'yeṣāmarthe kāṅkṣitaṃ no rājyaṃ bhogāḥ sukhāni ca .\nta ime.avasthitā yuddhe prāṇāṃstyaktvā dhanāni ca', meaning: 'Those for whose sake we desire kingdom, enjoyment, and pleasures stand here in battle, giving up their lives and wealth,', inShort: 'The very people he\'d rule for stand ready to die.'),
  GitaVerse(chapter: 1, verse: 34, sanskrit: 'आचार्याः पितरः पुत्रास्तथैव च पितामहाः |\nमातुलाः श्वशुराः पौत्राः श्यालाः सम्बन्धिनस्तथा', transliteration: 'ācāryāḥ pitaraḥ putrāstathaiva ca pitāmahāḥ .\nmātulāḥ śvaśurāḥ pautrāḥ śyālāḥ sambandhinastathā', meaning: 'teachers, fathers, sons, and grandfathers, uncles, fathers-in-law, grandsons, brothers-in-law, and other kinsmen.', inShort: 'They are his teachers, elders, and kin.'),
  GitaVerse(chapter: 1, verse: 35, sanskrit: 'एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन |\nअपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते', transliteration: 'etānna hantumicchāmi ghnato.api madhusūdana .\napi trailokyarājyasya hetoḥ kiṃ nu mahīkṛte', meaning: 'I would not wish to kill these, O Krishna, even if I were killed myself, not even for the sovereignty of the three worlds, how much less for this earth.', inShort: 'He would not kill them even to rule the worlds.'),
  GitaVerse(chapter: 1, verse: 36, sanskrit: 'निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन |\nपापमेवाश्रयेदस्मान्हत्वैतानाततायिनः', transliteration: 'nihatya dhārtarāṣṭrānnaḥ kā prītiḥ syājjanārdana .\npāpamevāśrayedasmānhatvaitānātatāyinaḥ', meaning: 'What joy could be ours in slaying Dhritarashtra\'s sons, O Krishna? Only sin would cling to us if we killed these aggressors.', inShort: 'Killing them would bring only sin, not joy.'),
  GitaVerse(chapter: 1, verse: 37, sanskrit: 'तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान् |\nस्वजनं हि कथं हत्वा सुखिनः स्याम माधव', transliteration: 'tasmānnārhā vayaṃ hantuṃ dhārtarāṣṭrānsvabāndhavān .\nsvajanaṃ hi kathaṃ hatvā sukhinaḥ syāma mādhava', meaning: 'Therefore we ought not to kill our own kinsmen, the sons of Dhritarashtra; for how could we be happy after slaying our own people?', inShort: 'How could we be happy after killing our own?'),
  GitaVerse(chapter: 1, verse: 38, sanskrit: 'यद्यप्येते न पश्यन्ति लोभोपहतचेतसः |\nकुलक्षयकृतं दोषं मित्रद्रोहे च पातकम्', transliteration: 'yadyapyete na paśyanti lobhopahatacetasaḥ .\nkulakṣayakṛtaṃ doṣaṃ mitradrohe ca pātakam', meaning: 'Even if these, their minds overpowered by greed, see no fault in destroying a family or in betraying friends,', inShort: 'Though greed blinds them to the wrong of it,'),
  GitaVerse(chapter: 1, verse: 39, sanskrit: 'कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम् |\nकुलक्षयकृतं दोषं प्रपश्यद्भिर्जनार्दन', transliteration: 'kathaṃ na jñeyamasmābhiḥ pāpādasmānnivartitum .\nkulakṣayakṛtaṃ doṣaṃ prapaśyadbhirjanārdana', meaning: 'why should we not have the sense to turn away from this sin, O Krishna, we who clearly see the fault in destroying a family?', inShort: 'We who see the wrong should turn away from it.'),
  GitaVerse(chapter: 1, verse: 40, sanskrit: 'कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः |\nधर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत', transliteration: 'kulakṣaye praṇaśyanti kuladharmāḥ sanātanāḥ .\ndharme naṣṭe kulaṃ kṛtsnamadharmo.abhibhavatyuta', meaning: 'When a family is destroyed, its ancient laws perish; and when law perishes, lawlessness overtakes the whole family.', inShort: 'When a family falls, its ancient values die.'),
  GitaVerse(chapter: 1, verse: 41, sanskrit: 'अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः |\nस्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः', transliteration: 'adharmābhibhavātkṛṣṇa praduṣyanti kulastriyaḥ .\nstrīṣu duṣṭāsu vārṣṇeya jāyate varṇasaṅkaraḥ', meaning: 'When lawlessness prevails, O Krishna, the women of the family are corrupted; and when women are corrupted, the mixing of order arises.', inShort: 'Ruin of the family leads to social disorder.'),
  GitaVerse(chapter: 1, verse: 42, sanskrit: 'सङ्करो नरकायैव कुलघ्नानां कुलस्य च |\nपतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः', transliteration: 'saṅkaro narakāyaiva kulaghnānāṃ kulasya ca .\npatanti pitaro hyeṣāṃ luptapiṇḍodakakriyāḥ', meaning: 'This confusion drags the family and its destroyers into ruin; and their ancestors fall, deprived of the offerings of rice and water.', inShort: 'Such disorder pulls the whole family down.'),
  GitaVerse(chapter: 1, verse: 43, sanskrit: 'दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः |\nउत्साद्यन्ते जातिधर्माः कुलधर्माश्च शाश्वताः', transliteration: 'doṣairetaiḥ kulaghnānāṃ varṇasaṅkarakārakaiḥ .\nutsādyante jātidharmāḥ kuladharmāśca śāśvatāḥ', meaning: 'By these misdeeds of the family-destroyers, which cause such confusion, the timeless laws of community and family are undone.', inShort: 'These wrongs undo age-old family duties.'),
  GitaVerse(chapter: 1, verse: 44, sanskrit: 'उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन |\nनरके नियतं वासो भवतीत्यनुशुश्रुम (or नरकेऽनियतं)', transliteration: 'utsannakuladharmāṇāṃ manuṣyāṇāṃ janārdana .\nnarake niyataṃ vāso bhavatītyanuśuśruma', meaning: 'And people whose family laws are destroyed, O Krishna, are said to dwell in ruin for a long, unknown time.', inShort: 'Those who wreck their family\'s laws are lost.'),
  GitaVerse(chapter: 1, verse: 45, sanskrit: 'अहो बत महत्पापं कर्तुं व्यवसिता वयम् |\nयद्राज्यसुखलोभेन हन्तुं स्वजनमुद्यताः', transliteration: 'aho bata mahatpāpaṃ kartuṃ vyavasitā vayam .\nyadrājyasukhalobhena hantuṃ svajanamudyatāḥ', meaning: 'Alas, we are set on committing a great sin, prepared to kill our own kinsmen out of greed for the pleasures of a kingdom.', inShort: 'We are about to sin greatly out of greed.'),
  GitaVerse(chapter: 1, verse: 46, sanskrit: 'यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः |\nधार्तराष्ट्रा रणे हन्युस्तन्मे क्षेमतरं भवेत्', transliteration: 'yadi māmapratīkāramaśastraṃ śastrapāṇayaḥ .\ndhārtarāṣṭrā raṇe hanyustanme kṣemataraṃ bhavet', meaning: 'Far better for me if Dhritarashtra\'s sons, weapons in hand, should kill me, unarmed and unresisting, in battle.', inShort: 'Better that they kill me unresisting.'),
  GitaVerse(chapter: 1, verse: 47, sanskrit: 'सञ्जय उवाच |\nएवमुक्त्वार्जुनः सङ्ख्ये रथोपस्थ उपाविशत् |\nविसृज्य सशरं चापं शोकसंविग्नमानसः', transliteration: 'sañjaya uvāca .\nevamuktvārjunaḥ saṅkhye rathopastha upāviśat .\nvisṛjya saśaraṃ cāpaṃ śokasaṃvignamānasaḥ', meaning: 'Sanjaya said: Having spoken thus on the battlefield, Arjuna sank down upon the seat of his chariot, casting aside his bow and arrows, his heart overwhelmed with grief.', inShort: 'Arjuna sinks down, casting aside his bow.'),
  GitaVerse(chapter: 2, verse: 1, sanskrit: 'सञ्जय उवाच |\nतं तथा कृपयाविष्टमश्रुपूर्णाकुलेक्षणम् |\nविषीदन्तमिदं वाक्यमुवाच मधुसूदनः', transliteration: 'sañjaya uvāca .\ntaṃ tathā kṛpayāviṣṭamaśrupūrṇākulekṣaṇam .\nviṣīdantamidaṃ vākyamuvāca madhusūdanaḥ', meaning: 'Sanjaya said: To Arjuna, thus overcome with pity, his eyes filled with tears and despairing, Madhusudana (Krishna) spoke these words.', inShort: 'Seeing Arjuna break down, Krishna begins to speak.'),
  GitaVerse(chapter: 2, verse: 2, sanskrit: 'श्रीभगवानुवाच |\nकुतस्त्वा कश्मलमिदं विषमे समुपस्थितम् |\nअनार्यजुष्टमस्वर्ग्यमकीर्तिकरमर्जुन', transliteration: 'śrībhagavānuvāca .\nkutastvā kaśmalamidaṃ viṣame samupasthitam .\nanāryajuṣṭamasvargyamakīrtikaramarjuna', meaning: 'The Blessed Lord said: Whence has this weakness come upon you at this crisis? It is unworthy of you, closes the door to heaven, and brings only disgrace, O Arjuna.', inShort: 'Krishna: this despair is unworthy of you.'),
  GitaVerse(chapter: 2, verse: 3, sanskrit: 'क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते |\nक्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप', transliteration: 'klaibyaṃ mā sma gamaḥ pārtha naitattvayyupapadyate .\nkṣudraṃ hṛdayadaurbalyaṃ tyaktvottiṣṭha parantapa', meaning: 'Do not yield to this unmanliness, O Partha; it does not befit you. Cast off this petty weakness of heart and arise, O scorcher of foes.', inShort: 'Shake off the weakness and rise.'),
  GitaVerse(chapter: 2, verse: 4, sanskrit: 'अर्जुन उवाच |\nकथं भीष्ममहं सङ्ख्ये द्रोणं च मधुसूदन |\nइषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन', transliteration: 'arjuna uvāca .\nkathaṃ bhīṣmamahaṃ saṅkhye droṇaṃ ca madhusūdana .\niṣubhiḥ pratiyotsyāmi pūjārhāvarisūdana', meaning: 'Arjuna said: How shall I strike Bhishma and Drona with arrows in battle, O Madhusudana, men who are worthy of my worship, O slayer of foes?', inShort: 'How can I fight my own revered elders?'),
  GitaVerse(chapter: 2, verse: 5, sanskrit: 'गुरूनहत्वा हि महानुभावान्\nश्रेयो भोक्तुं भैक्ष्यमपीह लोके |\nहत्वार्थकामांस्तु गुरूनिहैव\nभुञ्जीय भोगान् रुधिरप्रदिग्धान्', transliteration: 'gurūnahatvā hi mahānubhāvān śreyo bhoktuṃ bhaikṣyamapīha loke .\nhatvārthakāmāṃstu gurūnihaiva bhuñjīya bhogān rudhirapradigdhān', meaning: 'Better to live in this world on a beggar\'s alms than to slay these noble teachers. If I kill them, even here every joy would be stained with their blood.', inShort: 'I would rather beg than kill my teachers.'),
  GitaVerse(chapter: 2, verse: 6, sanskrit: 'न चैतद्विद्मः कतरन्नो गरीयो\nयद्वा जयेम यदि वा नो जयेयुः |\nयानेव हत्वा न जिजीविषामस्-\nतेऽवस्थिताः प्रमुखे धार्तराष्ट्राः', transliteration: 'na caitadvidmaḥ kataranno garīyo yadvā jayema yadi vā no jayeyuḥ .\nyāneva hatvā na jijīviṣāmaḥ te.avasthitāḥ pramukhe dhārtarāṣṭrāḥ', meaning: 'We hardly know which is better: that we conquer them, or they conquer us. The sons of Dhritarashtra, whom having killed we would not wish to live, stand arrayed against us.', inShort: 'I do not even know what victory is worth.'),
  GitaVerse(chapter: 2, verse: 7, sanskrit: 'कार्पण्यदोषोपहतस्वभावः\nपृच्छामि त्वां धर्मसम्मूढचेताः |\nयच्छ्रेयः स्यान्निश्चितं ब्रूहि तन्मे\nशिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम्', transliteration: 'kārpaṇyadoṣopahatasvabhāvaḥ pṛcchāmi tvāṃ dharmasammūḍhacetāḥ .\nyacchreyaḥ syānniścitaṃ brūhi tanme śiṣyaste.ahaṃ śādhi māṃ tvāṃ prapannam', meaning: 'My very being is stricken with the weakness of pity, my mind confused about my duty. I ask you: tell me clearly what is best. I am your pupil; teach me, for I take refuge in you.', inShort: 'Confused, Arjuna surrenders as a student.'),
  GitaVerse(chapter: 2, verse: 8, sanskrit: 'न हि प्रपश्यामि ममापनुद्याद्\nयच्छोकमुच्छोषणमिन्द्रियाणाम् |\nअवाप्य भूमावसपत्नमृद्धं\nराज्यं सुराणामपि चाधिपत्यम्', transliteration: 'na hi prapaśyāmi mamāpanudyād yacchokamucchoṣaṇamindriyāṇām .\navāpya bhūmāvasapatnamṛddhaṃ rājyaṃ surāṇāmapi cādhipatyam', meaning: 'I see nothing that could drive away this grief withering my senses, not even unrivalled kingship over the earth, nor lordship over the gods.', inShort: 'Nothing can lift this sorrow from me.'),
  GitaVerse(chapter: 2, verse: 9, sanskrit: 'सञ्जय उवाच |\nएवमुक्त्वा हृषीकेशं गुडाकेशः परन्तप |\nन योत्स्य इति गोविन्दमुक्त्वा तूष्णीं बभूव ह', transliteration: 'sañjaya uvāca .\nevamuktvā hṛṣīkeśaṃ guḍākeśaḥ parantapaḥ .\nna yotsya iti govindamuktvā tūṣṇīṃ babhūva ha', meaning: 'Sanjaya said: Having spoken thus to Krishna, Arjuna, the conqueror of foes, said, I will not fight, and fell silent.', inShort: 'Arjuna refuses to fight and goes silent.'),
  GitaVerse(chapter: 2, verse: 10, sanskrit: 'तमुवाच हृषीकेशः प्रहसन्निव भारत |\nसेनयोरुभयोर्मध्ये विषीदन्तमिदं वचः', transliteration: 'tamuvāca hṛṣīkeśaḥ prahasanniva bhārata .\nsenayorubhayormadhye viṣīdantamidaṃ vacaḥ', meaning: 'To him despairing between the two armies, O Bharata, Krishna, as if smiling, spoke these words.', inShort: 'Krishna, gently smiling, begins to teach.'),
  GitaVerse(chapter: 2, verse: 11, sanskrit: 'श्रीभगवानुवाच |\nअशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे |\nगतासूनगतासूंश्च नानुशोचन्ति पण्डिताः', transliteration: 'śrībhagavānuvāca .\naśocyānanvaśocastvaṃ prajñāvādāṃśca bhāṣase .\ngatāsūnagatāsūṃśca nānuśocanti paṇḍitāḥ', meaning: 'The Blessed Lord said: You grieve for those who should not be grieved for, yet you speak words of wisdom. The wise mourn neither for the living nor for the dead.', inShort: 'The wise grieve for neither the living nor the dead.'),
  GitaVerse(chapter: 2, verse: 12, sanskrit: 'न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः |\nन चैव न भविष्यामः सर्वे वयमतः परम्', transliteration: 'na tvevāhaṃ jātu nāsaṃ na tvaṃ neme janādhipāḥ .\nna caiva na bhaviṣyāmaḥ sarve vayamataḥ param', meaning: 'Never was there a time when I did not exist, nor you, nor these kings; nor will any of us ever cease to be hereafter.', inShort: 'You, I, and all beings have always existed and always will.'),
  GitaVerse(chapter: 2, verse: 13, sanskrit: 'देहिनोऽस्मिन्यथा देहे कौमारं यौवनं जरा |\nतथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति', transliteration: 'dehino.asminyathā dehe kaumāraṃ yauvanaṃ jarā .\ntathā dehāntaraprāptirdhīrastatra na muhyati', meaning: 'As the embodied soul passes in this body through childhood, youth, and old age, so it passes into another body. The wise are not deluded by this.', inShort: 'Changing bodies is like passing from youth to age.'),
  GitaVerse(chapter: 2, verse: 14, sanskrit: 'मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः |\nआगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत', transliteration: 'mātrāsparśāstu kaunteya śītoṣṇasukhaduḥkhadāḥ .\nāgamāpāyino.anityāstāṃstitikṣasva bhārata', meaning: 'The contacts of the senses with their objects give rise to cold and heat, pleasure and pain. They come and go, impermanent. Learn to endure them, O Arjuna.', inShort: 'Pleasure and pain come and go; endure them calmly.'),
  GitaVerse(chapter: 2, verse: 15, sanskrit: 'यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ |\nसमदुःखसुखं धीरं सोऽमृतत्वाय कल्पते', transliteration: 'yaṃ hi na vyathayantyete puruṣaṃ puruṣarṣabha .\nsamaduḥkhasukhaṃ dhīraṃ so.amṛtatvāya kalpate', meaning: 'The person whom these do not disturb, to whom pain and pleasure are alike, that steadfast one is fit for immortality.', inShort: 'The unshaken soul is fit for immortality.'),
  GitaVerse(chapter: 2, verse: 16, sanskrit: 'नासतो विद्यते भावो नाभावो विद्यते सतः |\nउभयोरपि दृष्टोऽन्तस्त्वनयोस्तत्त्वदर्शिभिः', transliteration: 'nāsato vidyate bhāvo nābhāvo vidyate sataḥ .\nubhayorapi dṛṣṭo.antastvanayostattvadarśibhiḥ', meaning: 'The unreal never comes to be; the real never ceases to be. The truth of both has been seen by the seers of reality.', inShort: 'The unreal has no true being; the real never ends.'),
  GitaVerse(chapter: 2, verse: 17, sanskrit: 'अविनाशि तु तद्विद्धि येन सर्वमिदं ततम् |\nविनाशमव्ययस्यास्य न कश्चित्कर्तुमर्हति', transliteration: 'avināśi tu tadviddhi yena sarvamidaṃ tatam .\nvināśamavyayasyāsya na kaścitkartumarhati', meaning: 'Know that to be indestructible by which all this is pervaded. No one can bring about the destruction of the imperishable.', inShort: 'That which pervades all can never be destroyed.'),
  GitaVerse(chapter: 2, verse: 18, sanskrit: 'अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः |\nअनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत', transliteration: 'antavanta ime dehā nityasyoktāḥ śarīriṇaḥ .\nanāśino.aprameyasya tasmādyudhyasva bhārata', meaning: 'These bodies of the eternal, indestructible, immeasurable embodied soul are said to come to an end. Therefore fight, O Bharata.', inShort: 'Only the body perishes, so do your duty.'),
  GitaVerse(chapter: 2, verse: 19, sanskrit: 'य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम् |\nउभौ तौ न विजानीतो नायं हन्ति न हन्यते', transliteration: 'ya enaṃ vetti hantāraṃ yaścainaṃ manyate hatam ubhau tau na vijānīto nāyaṃ hanti na hanyate', meaning: 'He who thinks the soul a slayer, and he who thinks it slain, are both mistaken. It neither slays nor is slain.', inShort: 'The soul neither kills nor is killed.'),
  GitaVerse(chapter: 2, verse: 20, sanskrit: 'न जायते म्रियते वा कदाचिन्\nनायं भूत्वा भविता वा न भूयः |\nअजो नित्यः शाश्वतोऽयं पुराणो\nन हन्यते हन्यमाने शरीरे', transliteration: 'na jāyate mriyate vā kadācin nāyaṃ bhūtvā bhavitā vā na bhūyaḥ .\najo nityaḥ śāśvato.ayaṃ purāṇo na hanyate hanyamāne śarīre', meaning: 'It is never born and never dies; having been, it never ceases to be. Unborn, eternal, everlasting, and ancient, it is not slain when the body is slain.', inShort: 'The soul is unborn and undying.'),
  GitaVerse(chapter: 2, verse: 21, sanskrit: 'वेदाविनाशिनं नित्यं य एनमजमव्ययम् |\nकथं स पुरुषः पार्थ कं घातयति हन्ति कम्', transliteration: 'vedāvināśinaṃ nityaṃ ya enamajamavyayam .\nkathaṃ sa puruṣaḥ pārtha kaṃ ghātayati hanti kam', meaning: 'He who knows the soul to be indestructible, eternal, unborn, and unchanging, how and whom can such a person cause to slay or be slain, O Partha?', inShort: 'Knowing the soul is deathless, whom do you truly harm?'),
  GitaVerse(chapter: 2, verse: 22, sanskrit: 'वासांसि जीर्णानि यथा विहाय\nनवानि गृह्णाति नरोऽपराणि |\nतथा शरीराणि विहाय जीर्णा-\nन्यन्यानि संयाति नवानि देही', transliteration: 'vāsāṃsi jīrṇāni yathā vihāya navāni gṛhṇāti naro.aparāṇi .\ntathā śarīrāṇi vihāya jīrṇāni anyāni saṃyāti navāni dehī', meaning: 'As a person casts off worn-out clothes and puts on new ones, so the embodied soul casts off worn-out bodies and enters others that are new.', inShort: 'Death is only changing worn-out clothes.'),
  GitaVerse(chapter: 2, verse: 23, sanskrit: 'नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः |\nन चैनं क्लेदयन्त्यापो न शोषयति मारुतः', transliteration: 'nainaṃ chindanti śastrāṇi nainaṃ dahati pāvakaḥ .\nna cainaṃ kledayantyāpo na śoṣayati mārutaḥ', meaning: 'Weapons cannot cut it, fire cannot burn it, water cannot wet it, and wind cannot dry it.', inShort: 'No weapon, fire, water, or wind can touch the soul.'),
  GitaVerse(chapter: 2, verse: 24, sanskrit: 'अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च |\nनित्यः सर्वगतः स्थाणुरचलोऽयं सनातनः', transliteration: 'acchedyo.ayamadāhyo.ayamakledyo.aśoṣya eva ca .\nnityaḥ sarvagataḥ sthāṇuracalo.ayaṃ sanātanaḥ', meaning: 'It cannot be cut, burned, wetted, or dried. It is eternal, all-pervading, stable, unmoving, and ever the same.', inShort: 'The soul is eternal and unchanging.'),
  GitaVerse(chapter: 2, verse: 25, sanskrit: 'अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते |\nतस्मादेवं विदित्वैनं नानुशोचितुमर्हसि', transliteration: 'avyakto.ayamacintyo.ayamavikāryo.ayamucyate .\ntasmādevaṃ viditvainaṃ nānuśocitumarhasi', meaning: 'It is said to be unmanifest, unthinkable, and unchanging. Knowing it to be so, you ought not to grieve.', inShort: 'Knowing this, do not grieve.'),
  GitaVerse(chapter: 2, verse: 26, sanskrit: 'अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम् |\nतथापि त्वं महाबाहो नैवं शोचितुमर्हसि', transliteration: 'atha cainaṃ nityajātaṃ nityaṃ vā manyase mṛtam .\ntathāpi tvaṃ mahābāho naivaṃ śocitumarhasi', meaning: 'Even if you think the soul is constantly born and constantly dies, O mighty-armed, even then you ought not to grieve.', inShort: 'Even then, grief would be pointless.'),
  GitaVerse(chapter: 2, verse: 27, sanskrit: 'जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च |\nतस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि', transliteration: 'jātasya hi dhruvo mṛtyurdhruvaṃ janma mṛtasya ca .\ntasmādaparihārye.arthe na tvaṃ śocitumarhasi', meaning: 'For the born, death is certain; for the dead, birth is certain. Over the unavoidable, therefore, you should not grieve.', inShort: 'Death follows birth as surely as birth follows death.'),
  GitaVerse(chapter: 2, verse: 28, sanskrit: 'अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत |\nअव्यक्तनिधनान्येव तत्र का परिदेवना', transliteration: 'avyaktādīni bhūtāni vyaktamadhyāni bhārata .\navyaktanidhanānyeva tatra kā paridevanā', meaning: 'Beings are unmanifest in their beginning, manifest in the middle, and unmanifest again at the end. Why grieve over this, O Bharata?', inShort: 'We come from the unseen and return to it.'),
  GitaVerse(chapter: 2, verse: 29, sanskrit: 'आश्चर्यवत्पश्यति कश्चिदेन-\nमाश्चर्यवद्वदति तथैव चान्यः |\nआश्चर्यवच्चैनमन्यः शृणोति\nश्रुत्वाप्येनं वेद न चैव कश्चित्', transliteration: 'āścaryavatpaśyati kaścidenam āścaryavadvadati tathaiva cānyaḥ .\nāścaryavaccainamanyaḥ śṛṇoti śrutvāpyenaṃ veda na caiva kaścit', meaning: 'One sees the soul as a wonder, another speaks of it as a wonder, another hears of it as a wonder; yet even having heard, no one truly knows it.', inShort: 'The soul is a wonder few truly grasp.'),
  GitaVerse(chapter: 2, verse: 30, sanskrit: 'देही नित्यमवध्योऽयं देहे सर्वस्य भारत |\nतस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि', transliteration: 'dehī nityamavadhyo.ayaṃ dehe sarvasya bhārata .\ntasmātsarvāṇi bhūtāni na tvaṃ śocitumarhasi', meaning: 'The soul dwelling in the body of everyone is ever indestructible. Therefore you should not grieve for any being.', inShort: 'The soul within all is deathless; grieve for none.'),
  GitaVerse(chapter: 2, verse: 31, sanskrit: 'स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि |\nधर्म्याद्धि युद्धाच्छ्रेयोऽन्यत्क्षत्रियस्य न विद्यते', transliteration: 'svadharmamapi cāvekṣya na vikampitumarhasi .\ndharmyāddhi yuddhācchreyo.anyatkṣatriyasya na vidyate', meaning: 'Considering your own duty as well, you should not waver; for a warrior there is nothing higher than a righteous battle.', inShort: 'For a warrior, a righteous battle is the highest duty.'),
  GitaVerse(chapter: 2, verse: 32, sanskrit: 'यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम् |\nसुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम्', transliteration: 'yadṛcchayā copapannaṃ svargadvāramapāvṛtam .\nsukhinaḥ kṣatriyāḥ pārtha labhante yuddhamīdṛśam', meaning: 'Happy are the warriors, O Partha, who are granted such a battle, coming unsought like an open door to heaven.', inShort: 'Such a righteous fight is a rare blessing.'),
  GitaVerse(chapter: 2, verse: 33, sanskrit: 'अथ चेत्त्वमिमं धर्म्यं संग्रामं न करिष्यसि |\nततः स्वधर्मं कीर्तिं च हित्वा पापमवाप्स्यसि', transliteration: 'atha cettvamimaṃ dharmyaṃ saṃgrāmaṃ na kariṣyasi .\ntataḥ svadharmaṃ kīrtiṃ ca hitvā pāpamavāpsyasi', meaning: 'But if you will not fight this righteous war, then, forsaking your duty and your honour, you will only incur sin.', inShort: 'To flee your duty is itself a wrong.'),
  GitaVerse(chapter: 2, verse: 34, sanskrit: 'अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम् |\nसम्भावितस्य चाकीर्तिर्मरणादतिरिच्यते', transliteration: 'akīrtiṃ cāpi bhūtāni kathayiṣyanti te.avyayām .\nsambhāvitasya cākīrtirmaraṇādatiricyate', meaning: 'People will forever speak of your disgrace; and for one who has been honoured, dishonour is worse than death.', inShort: 'Lasting dishonour is worse than death.'),
  GitaVerse(chapter: 2, verse: 35, sanskrit: 'भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः |\nयेषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम्', transliteration: 'bhayādraṇāduparataṃ maṃsyante tvāṃ mahārathāḥ .\nyeṣāṃ ca tvaṃ bahumato bhūtvā yāsyasi lāghavam', meaning: 'The great warriors will think you fled the battle out of fear; and those who once esteemed you highly will hold you lightly.', inShort: 'They will believe you fled in fear.'),
  GitaVerse(chapter: 2, verse: 36, sanskrit: 'अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः |\nनिन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम्', transliteration: 'avācyavādāṃśca bahūnvadiṣyanti tavāhitāḥ .\nnindantastava sāmarthyaṃ tato duḥkhataraṃ nu kim', meaning: 'Your enemies will mock your strength with many cruel words. What could be more painful than that?', inShort: 'Your foes will mock you; what could hurt more?'),
  GitaVerse(chapter: 2, verse: 37, sanskrit: 'हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम् |\nतस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः', transliteration: 'hato vā prāpsyasi svargaṃ jitvā vā bhokṣyase mahīm .\ntasmāduttiṣṭha kaunteya yuddhāya kṛtaniścayaḥ', meaning: 'If slain, you will gain heaven; if victorious, you will enjoy the earth. Therefore arise, O Arjuna, resolved to fight.', inShort: 'Win or fall, rise and act; either way you gain.'),
  GitaVerse(chapter: 2, verse: 38, sanskrit: 'सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ |\nततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि', transliteration: 'sukhaduḥkhe same kṛtvā lābhālābhau jayājayau .\ntato yuddhāya yujyasva naivaṃ pāpamavāpsyasi', meaning: 'Treating alike pleasure and pain, gain and loss, victory and defeat, gird yourself for battle. Thus you shall incur no sin.', inShort: 'Fight even-minded, and no sin can touch you.'),
  GitaVerse(chapter: 2, verse: 39, sanskrit: 'एषा तेऽभिहिता साङ्ख्ये बुद्धिर्योगे त्विमां शृणु |\nबुद्ध्या युक्तो यया पार्थ कर्मबन्धं प्रहास्यसि', transliteration: 'eṣā te.abhihitā sāṅkhye buddhiryoge tvimāṃ śṛṇu .\nbuddhyā yukto yayā pārtha karmabandhaṃ prahāsyasi', meaning: 'This wisdom of Sankhya has been declared to you; now hear the wisdom of Yoga, endowed with which you will cast off the bondage of action.', inShort: 'Now hear how action itself can set you free.'),
  GitaVerse(chapter: 2, verse: 40, sanskrit: 'नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते |\nस्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात्', transliteration: 'nehābhikramanāśo.asti pratyavāyo na vidyate .\nsvalpamapyasya dharmasya trāyate mahato bhayāt', meaning: 'On this path no effort is ever lost and no harm comes. Even a little of this practice protects one from great fear.', inShort: 'Even a little of this path saves from great fear.'),
  GitaVerse(chapter: 2, verse: 41, sanskrit: 'व्यवसायात्मिका बुद्धिरेकेह कुरुनन्दन |\nबहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम्', transliteration: 'vyavasāyātmikā buddhirekeha kurunandana .\nbahuśākhā hyanantāśca buddhayo.avyavasāyinām', meaning: 'Here, O joy of the Kurus, the resolute mind is single and one-pointed; but the minds of the irresolute are many-branched and endless.', inShort: 'A steady mind is single; a restless mind scatters.'),
  GitaVerse(chapter: 2, verse: 42, sanskrit: 'यामिमां पुष्पितां वाचं प्रवदन्त्यविपश्चितः |\nवेदवादरताः पार्थ नान्यदस्तीति वादिनः', transliteration: 'yāmimāṃ puṣpitāṃ vācaṃ pravadantyavipaścitaḥ .\nvedavādaratāḥ pārtha nānyadastīti vādinaḥ', meaning: 'The unwise delight in the flowery words of the Vedas, O Partha, declaring that there is nothing else.', inShort: 'Some cling to ritual words, thinking that is all there is.'),
  GitaVerse(chapter: 2, verse: 43, sanskrit: 'कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम् |\nक्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति', transliteration: 'kāmātmānaḥ svargaparā janmakarmaphalapradām .\nkriyāviśeṣabahulāṃ bhogaiśvaryagatiṃ prati', meaning: 'Full of desire, intent on heaven, they offer showy rites promising pleasure, power, and rebirth as their reward.', inShort: 'They chase heaven, pleasure, and power through rituals.'),
  GitaVerse(chapter: 2, verse: 44, sanskrit: 'भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम् |\nव्यवसायात्मिका बुद्धिः समाधौ न विधीयते', transliteration: 'bhogaiśvaryaprasaktānāṃ tayāpahṛtacetasām .\nvyavasāyātmikā buddhiḥ samādhau na vidhīyate', meaning: 'For those attached to pleasure and power, whose minds are carried away by such words, no steady, concentrated insight arises in meditation.', inShort: 'Craving pleasure and power, the mind cannot settle.'),
  GitaVerse(chapter: 2, verse: 45, sanskrit: 'त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन |\nनिर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान्', transliteration: 'traiguṇyaviṣayā vedā nistraiguṇyo bhavārjuna .\nnirdvandvo nityasattvastho niryogakṣema ātmavān', meaning: 'The Vedas deal with the three qualities of nature; rise above them, O Arjuna. Be free from the pairs of opposites, ever poised in truth, unconcerned with getting and keeping, established in the Self.', inShort: 'Rise above the three gunas and rest in the Self.'),
  GitaVerse(chapter: 2, verse: 46, sanskrit: 'यावानर्थ उदपाने सर्वतः सम्प्लुतोदके |\nतावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः', transliteration: 'yāvānartha udapāne sarvataḥ samplutodake .\ntāvānsarveṣu vedeṣu brāhmaṇasya vijānataḥ', meaning: 'As much use as a small well when there is a flood of water everywhere, so much is all the Vedas to a wise knower of Brahman.', inShort: 'To the awakened, scattered rites matter little.'),
  GitaVerse(chapter: 2, verse: 47, sanskrit: 'कर्मण्येवाधिकारस्ते मा फलेषु कदाचन |\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि', transliteration: 'karmaṇyevādhikāraste mā phaleṣu kadācana .\nmā karmaphalaheturbhūrmā te saṅgo.astvakarmaṇi', meaning: 'You have a right to your actions alone, never to their fruits. Let not the fruit of action be your motive, nor let attachment draw you to inaction.', inShort: 'Do your work; let go of its results.'),
  GitaVerse(chapter: 2, verse: 48, sanskrit: 'योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय |\nसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते', transliteration: 'yogasthaḥ kuru karmāṇi saṅgaṃ tyaktvā dhanañjaya .\nsiddhyasiddhyoḥ samo bhūtvā samatvaṃ yoga ucyate', meaning: 'Established in yoga, perform your actions abandoning attachment, O Arjuna, even-minded in success and failure. Evenness of mind is called yoga.', inShort: 'Act with an even mind; that balance is yoga.'),
  GitaVerse(chapter: 2, verse: 49, sanskrit: 'दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय |\nबुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः', transliteration: 'dūreṇa hyavaraṃ karma buddhiyogāddhanañjaya .\nbuddhau śaraṇamanviccha kṛpaṇāḥ phalahetavaḥ', meaning: 'Action done for reward is far inferior to action done with even-minded wisdom, O Arjuna. Take refuge in wisdom; wretched are those who act only for results.', inShort: 'Acting for reward is poorer than acting with wisdom.'),
  GitaVerse(chapter: 2, verse: 50, sanskrit: 'बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते |\nतस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम्', transliteration: 'buddhiyukto jahātīha ubhe sukṛtaduṣkṛte .\ntasmādyogāya yujyasva yogaḥ karmasu kauśalam', meaning: 'One united in wisdom casts off here both good and evil deeds. Therefore devote yourself to yoga; yoga is skill in action.', inShort: 'Yoga is skill in action, rising above good and bad.'),
  GitaVerse(chapter: 2, verse: 51, sanskrit: 'कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः |\nजन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम्', transliteration: 'karmajaṃ buddhiyuktā hi phalaṃ tyaktvā manīṣiṇaḥ .\njanmabandhavinirmuktāḥ padaṃ gacchantyanāmayam', meaning: 'The wise, united in even-minded wisdom, renounce the fruits of their actions; freed from the bondage of birth, they reach the state beyond all sorrow.', inShort: 'Releasing results, the wise reach the sorrowless state.'),
  GitaVerse(chapter: 2, verse: 52, sanskrit: 'यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति |\nतदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च', transliteration: 'yadā te mohakalilaṃ buddhirvyatitariṣyati .\ntadā gantāsi nirvedaṃ śrotavyasya śrutasya ca', meaning: 'When your intellect crosses beyond the tangle of delusion, you will grow indifferent to all that has been heard and all that is yet to be heard.', inShort: 'Beyond delusion, hollow words lose their pull.'),
  GitaVerse(chapter: 2, verse: 53, sanskrit: 'श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला |\nसमाधावचला बुद्धिस्तदा योगमवाप्स्यसि', transliteration: 'śrutivipratipannā te yadā sthāsyati niścalā .\nsamādhāvacalā buddhistadā yogamavāpsyasi', meaning: 'When your mind, once bewildered by scripture, stands unmoved and steady in meditation, then you will attain yoga, the state of union.', inShort: 'When the mind stands still, union is reached.'),
  GitaVerse(chapter: 2, verse: 54, sanskrit: 'अर्जुन उवाच |\nस्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव |\nस्थितधीः किं प्रभाषेत किमासीत व्रजेत किम्', transliteration: 'arjuna uvāca .\nsthitaprajñasya kā bhāṣā samādhisthasya keśava .\nsthitadhīḥ kiṃ prabhāṣeta kimāsīta vrajeta kim', meaning: 'Arjuna said: What is the mark of one of steady wisdom, settled in meditation, O Krishna? How does the steady-minded speak, sit, and walk?', inShort: 'Arjuna asks: what is a person of steady wisdom like?'),
  GitaVerse(chapter: 2, verse: 55, sanskrit: 'श्रीभगवानुवाच |\nप्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान् |\nआत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते', transliteration: 'śrībhagavānuvāca .\nprajahāti yadā kāmānsarvānpārtha manogatān .\nātmanyevātmanā tuṣṭaḥ sthitaprajñastadocyate', meaning: 'The Blessed Lord said: When one gives up all the desires of the mind, O Partha, and is satisfied in the Self by the Self alone, then one is called steady in wisdom.', inShort: 'Content in the Self, free of cravings; that is steady wisdom.'),
  GitaVerse(chapter: 2, verse: 56, sanskrit: 'दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः |\nवीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते', transliteration: 'duḥkheṣvanudvignamanāḥ sukheṣu vigataspṛhaḥ .\nvītarāgabhayakrodhaḥ sthitadhīrmunirucyate', meaning: 'Unshaken in sorrow, without craving amid pleasures, free from attachment, fear, and anger, such a sage is called steady-minded.', inShort: 'Undisturbed by pain, desire, fear, or anger.'),
  GitaVerse(chapter: 2, verse: 57, sanskrit: 'यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम् |\nनाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता', transliteration: 'yaḥ sarvatrānabhisnehastattatprāpya śubhāśubham .\nnābhinandati na dveṣṭi tasya prajñā pratiṣṭhitā', meaning: 'He who is unattached everywhere, who neither rejoices at good fortune nor recoils at bad, his wisdom is firmly set.', inShort: 'Neither elated nor cast down; wisdom held firm.'),
  GitaVerse(chapter: 2, verse: 58, sanskrit: 'यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः |\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता', transliteration: 'yadā saṃharate cāyaṃ kūrmo.aṅgānīva sarvaśaḥ .\nindriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā', meaning: 'When, like a tortoise drawing in its limbs, one withdraws the senses from their objects, then his wisdom is firmly set.', inShort: 'Withdraw the senses like a tortoise draws in its limbs.'),
  GitaVerse(chapter: 2, verse: 59, sanskrit: 'विषया विनिवर्तन्ते निराहारस्य देहिनः |\nरसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते', transliteration: 'viṣayā vinivartante nirāhārasya dehinaḥ .\nrasavarjaṃ raso.apyasya paraṃ dṛṣṭvā nivartate', meaning: 'Objects fall away from one who abstains from them, but the taste for them remains; even that taste falls away on seeing the Supreme.', inShort: 'The craving truly ends only on seeing the Highest.'),
  GitaVerse(chapter: 2, verse: 60, sanskrit: 'यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः |\nइन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः', transliteration: 'yatato hyapi kaunteya puruṣasya vipaścitaḥ .\nindriyāṇi pramāthīni haranti prasabhaṃ manaḥ', meaning: 'The turbulent senses, O Arjuna, forcibly carry away the mind even of a wise person striving for perfection.', inShort: 'The restless senses can sweep away even the wise.'),
  GitaVerse(chapter: 2, verse: 61, sanskrit: 'तानि सर्वाणि संयम्य युक्त आसीत मत्परः |\nवशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता', transliteration: 'tāni sarvāṇi saṃyamya yukta āsīta matparaḥ .\nvaśe hi yasyendriyāṇi tasya prajñā pratiṣṭhitā', meaning: 'Restraining them all, one should sit intent on Me; for one whose senses are mastered, wisdom is firmly set.', inShort: 'Master the senses, held steady on the Divine.'),
  GitaVerse(chapter: 2, verse: 62, sanskrit: 'ध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते |\nसङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते', transliteration: 'dhyāyato viṣayānpuṃsaḥ saṅgasteṣūpajāyate .\nsaṅgātsañjāyate kāmaḥ kāmātkrodho.abhijāyate', meaning: 'Dwelling on the objects of sense breeds attachment to them; from attachment springs desire; and from desire arises anger.', inShort: 'Brooding on things breeds desire, then anger.'),
  GitaVerse(chapter: 2, verse: 63, sanskrit: 'क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः |\nस्मृतिभ्रंशाद् बुद्धिनाशो बुद्धिनाशात्प्रणश्यति', transliteration: 'krodhādbhavati sammohaḥ sammohātsmṛtivibhramaḥ .\nsmṛtibhraṃśād buddhināśo buddhināśātpraṇaśyati', meaning: 'From anger comes delusion; from delusion, loss of memory; from loss of memory, the ruin of reason; and when reason is ruined, one is lost.', inShort: 'Anger clouds the mind and destroys judgment.'),
  GitaVerse(chapter: 2, verse: 64, sanskrit: 'रागद्वेषविमुक्तैस्तु विषयानिन्द्रियैश्चरन् | (or वियुक्तैस्तु)\nआत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति', transliteration: 'rāgadveṣavimuktaistu viṣayānindriyaiścaran .\norviyuktaistu ātmavaśyairvidheyātmā prasādamadhigacchati', meaning: 'But one who moves among objects with senses controlled, free from attachment and aversion, mastered by the Self, attains serenity.', inShort: 'With senses reined in, one finds peace.'),
  GitaVerse(chapter: 2, verse: 65, sanskrit: 'प्रसादे सर्वदुःखानां हानिरस्योपजायते |\nप्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते', transliteration: 'prasāde sarvaduḥkhānāṃ hānirasyopajāyate .\nprasannacetaso hyāśu buddhiḥ paryavatiṣṭhate', meaning: 'In that serenity all sorrows come to an end, for the intellect of the tranquil-minded soon becomes steady.', inShort: 'In serenity, sorrow ends and reason steadies.'),
  GitaVerse(chapter: 2, verse: 66, sanskrit: 'नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना |\nन चाभावयतः शान्तिरशान्तस्य कुतः सुखम्', transliteration: 'nāsti buddhirayuktasya na cāyuktasya bhāvanā .\nna cābhāvayataḥ śāntiraśāntasya kutaḥ sukham', meaning: 'There is no wisdom for the unsteady, and no meditation; without meditation there is no peace; and without peace, how can there be happiness?', inShort: 'No peace without a steady mind; no joy without peace.'),
  GitaVerse(chapter: 2, verse: 67, sanskrit: 'इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते |\nतदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि', transliteration: 'indriyāṇāṃ hi caratāṃ yanmano.anuvidhīyate .\ntadasya harati prajñāṃ vāyurnāvamivāmbhasi', meaning: 'When the mind runs after the wandering senses, it carries away one\'s wisdom, as the wind carries away a ship upon the waters.', inShort: 'A mind chasing the senses is blown off course.'),
  GitaVerse(chapter: 2, verse: 68, sanskrit: 'तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः |\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता', transliteration: 'tasmādyasya mahābāho nigṛhītāni sarvaśaḥ .\nindriyāṇīndriyārthebhyastasya prajñā pratiṣṭhitā', meaning: 'Therefore, O mighty-armed, one whose senses are wholly withdrawn from their objects, his wisdom is firmly set.', inShort: 'Withdraw the senses fully, and wisdom holds.'),
  GitaVerse(chapter: 2, verse: 69, sanskrit: 'या निशा सर्वभूतानां तस्यां जागर्ति संयमी |\nयस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः', transliteration: 'yā niśā sarvabhūtānāṃ tasyāṃ jāgarti saṃyamī .\nyasyāṃ jāgrati bhūtāni sā niśā paśyato muneḥ', meaning: 'What is night for all beings is the waking hour for the disciplined soul; and what is waking for all beings is night for the seer.', inShort: 'The sage is awake to what others sleep through.'),
  GitaVerse(chapter: 2, verse: 70, sanskrit: 'आपूर्यमाणमचलप्रतिष्ठं\nसमुद्रमापः प्रविशन्ति यद्वत् |\nतद्वत्कामा यं प्रविशन्ति सर्वे\nस शान्तिमाप्नोति न कामकामी', transliteration: 'āpūryamāṇamacalapratiṣṭhaṃ samudramāpaḥ praviśanti yadvat .\ntadvatkāmā yaṃ praviśanti sarve sa śāntimāpnoti na kāmakāmī', meaning: 'As the waters flow into the ocean, which is ever full yet unmoved, so desires enter the one who is at peace, not the one who runs after desires.', inShort: 'Desires enter the peaceful like rivers the calm sea.'),
  GitaVerse(chapter: 2, verse: 71, sanskrit: 'विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः |\nनिर्ममो निरहङ्कारः स शान्तिमधिगच्छति', transliteration: 'vihāya kāmānyaḥ sarvānpumāṃścarati niḥspṛhaḥ .\nnirmamo nirahaṅkāraḥ sa śāntimadhigacchati', meaning: 'The one who gives up all desires and moves through life free from longing, without the sense of mine and without ego, attains peace.', inShort: 'Free of craving and ego, one finds peace.'),
  GitaVerse(chapter: 2, verse: 72, sanskrit: 'एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति |\nस्थित्वास्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति', transliteration: 'eṣā brāhmī sthitiḥ pārtha naināṃ prāpya vimuhyati .\nsthitvāsyāmantakāle.api brahmanirvāṇamṛcchati', meaning: 'This is the state of Brahman, O Partha; attaining it, one is no longer deluded. Established in it even at the hour of death, one reaches oneness with Brahman.', inShort: 'This is the divine state; reaching it, none is deluded.'),
  GitaVerse(chapter: 3, verse: 1, sanskrit: 'अर्जुन उवाच |\nज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन |\nतत्किं कर्मणि घोरे मां नियोजयसि केशव', transliteration: 'arjuna uvāca .\njyāyasī cetkarmaṇaste matā buddhirjanārdana .\ntatkiṃ karmaṇi ghore māṃ niyojayasi keśava', meaning: 'Arjuna said: If you hold that wisdom is superior to action, O Krishna, why then do you urge me to this terrible deed?', inShort: 'Arjuna: if wisdom is higher, why must I fight?'),
  GitaVerse(chapter: 3, verse: 2, sanskrit: 'व्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे |\nतदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम्', transliteration: 'vyāmiśreṇeva vākyena buddhiṃ mohayasīva me .\ntadekaṃ vada niścitya yena śreyo.ahamāpnuyām', meaning: 'With these seemingly conflicting words you confuse my mind. Tell me decisively the one path by which I may reach the highest good.', inShort: 'Your mixed words confuse me; tell me one clear path.'),
  GitaVerse(chapter: 3, verse: 3, sanskrit: 'श्रीभगवानुवाच |\nलोकेऽस्मिन् द्विविधा निष्ठा पुरा प्रोक्ता मयानघ |\nज्ञानयोगेन साङ्ख्यानां कर्मयोगेन योगिनाम्', transliteration: 'śrībhagavānuvāca .\nloke.asmina dvividhā niṣṭhā purā proktā mayānagha .\njñānayogena sāṅkhyānāṃ karmayogena yoginām', meaning: 'The Blessed Lord said: In this world there are two paths, as I taught long ago, O sinless one: the path of knowledge for the contemplative, and the path of action for the active.', inShort: 'There are two paths: knowledge and action.'),
  GitaVerse(chapter: 3, verse: 4, sanskrit: 'न कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते |\nन च संन्यसनादेव सिद्धिं समधिगच्छति', transliteration: 'na karmaṇāmanārambhānnaiṣkarmyaṃ puruṣo.aśnute .\nna ca saṃnyasanādeva siddhiṃ samadhigacchati', meaning: 'Not by abstaining from action does one become free from action, nor by mere renunciation does one reach perfection.', inShort: 'Merely avoiding action brings no freedom.'),
  GitaVerse(chapter: 3, verse: 5, sanskrit: 'न हि कश्चित्क्षणमपि जातु तिष्ठत्यकर्मकृत् |\nकार्यते ह्यवशः कर्म सर्वः प्रकृतिजैर्गुणैः', transliteration: 'na hi kaścitkṣaṇamapi jātu tiṣṭhatyakarmakṛt .\nkāryate hyavaśaḥ karma sarvaḥ prakṛtijairguṇaiḥ', meaning: 'No one can remain even for a moment without acting; everyone is driven to act, helplessly, by the qualities born of nature.', inShort: 'No one can stay without acting, even a moment.'),
  GitaVerse(chapter: 3, verse: 6, sanskrit: 'कर्मेन्द्रियाणि संयम्य य आस्ते मनसा स्मरन् |\nइन्द्रियार्थान्विमूढात्मा मिथ्याचारः स उच्यते', transliteration: 'karmendriyāṇi saṃyamya ya āste manasā smaran .\nindriyārthānvimūḍhātmā mithyācāraḥ sa ucyate', meaning: 'One who restrains the organs of action but sits dwelling in his mind on objects of sense is a self-deceiving hypocrite.', inShort: 'Faking stillness while the mind wanders is hypocrisy.'),
  GitaVerse(chapter: 3, verse: 7, sanskrit: 'यस्त्विन्द्रियाणि मनसा नियम्यारभतेऽर्जुन |\nकर्मेन्द्रियैः कर्मयोगमसक्तः स विशिष्यते', transliteration: 'yastvindriyāṇi manasā niyamyārabhate.arjuna .\nkarmendriyaiḥ karmayogamasaktaḥ sa viśiṣyate', meaning: 'But he who controls the senses with the mind, O Arjuna, and engages the organs of action in yoga, without attachment, excels.', inShort: 'Better to act with senses controlled and unattached.'),
  GitaVerse(chapter: 3, verse: 8, sanskrit: 'नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः |\nशरीरयात्रापि च ते न प्रसिद्ध्येदकर्मणः', transliteration: 'niyataṃ kuru karma tvaṃ karma jyāyo hyakarmaṇaḥ .\nśarīrayātrāpi ca te na prasiddhyedakarmaṇaḥ', meaning: 'Do your allotted duty, for action is better than inaction; even the mere upkeep of your body could not happen without action.', inShort: 'Do your duty; even living requires action.'),
  GitaVerse(chapter: 3, verse: 9, sanskrit: 'यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः |\nतदर्थं कर्म कौन्तेय मुक्तसङ्गः समाचर', transliteration: 'yajñārthātkarmaṇo.anyatra loko.ayaṃ karmabandhanaḥ .\ntadarthaṃ karma kaunteya muktasaṅgaḥ samācara', meaning: 'This world is bound by action, except when action is done as sacrifice. Therefore, O Arjuna, perform your action for that sake, free from attachment.', inShort: 'Act as an offering, free from attachment.'),
  GitaVerse(chapter: 3, verse: 10, sanskrit: 'सहयज्ञाः प्रजाः सृष्ट्वा पुरोवाच प्रजापतिः |\nअनेन प्रसविष्यध्वमेष वोऽस्त्विष्टकामधुक्', transliteration: 'sahayajñāḥ prajāḥ sṛṣṭvā purovāca prajāpatiḥ .\nanena prasaviṣyadhvameṣa vo.astviṣṭakāmadhuk', meaning: 'In the beginning the Creator brought forth beings together with sacrifice, and said: by this shall you flourish; let it grant your every wish.', inShort: 'Creation and sacrifice were born together.'),
  GitaVerse(chapter: 3, verse: 11, sanskrit: 'देवान्भावयतानेन ते देवा भावयन्तु वः |\nपरस्परं भावयन्तः श्रेयः परमवाप्स्यथ', transliteration: 'devānbhāvayatānena te devā bhāvayantu vaḥ .\nparasparaṃ bhāvayantaḥ śreyaḥ paramavāpsyatha', meaning: 'With this may you nourish the gods, and may the gods nourish you; nourishing one another, you shall attain the highest good.', inShort: 'Give and receive; mutual nourishing brings good.'),
  GitaVerse(chapter: 3, verse: 12, sanskrit: 'इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः |\nतैर्दत्तानप्रदायैभ्यो यो भुङ्क्ते स्तेन एव सः', transliteration: 'iṣṭānbhogānhi vo devā dāsyante yajñabhāvitāḥ .\ntairdattānapradāyaibhyo yo bhuṅkte stena eva saḥ', meaning: 'Nourished by sacrifice, the gods will grant the enjoyments you desire. But he who enjoys their gifts without giving in return is a thief.', inShort: 'To take without giving back is theft.'),
  GitaVerse(chapter: 3, verse: 13, sanskrit: 'यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः |\nभुञ्जते ते त्वघं पापा ये पचन्त्यात्मकारणात्', transliteration: 'yajñaśiṣṭāśinaḥ santo mucyante sarvakilbiṣaiḥ .\nbhuñjate te tvaghaṃ pāpā ye pacantyātmakāraṇāt', meaning: 'The good, who eat what remains after sacrifice, are freed from all faults; but the selfish, who cook only for themselves, feed on wrong.', inShort: 'Living for others purifies; living only for self does not.'),
  GitaVerse(chapter: 3, verse: 14, sanskrit: 'अन्नाद्भवन्ति भूतानि पर्जन्यादन्नसम्भवः |\nयज्ञाद्भवति पर्जन्यो यज्ञः कर्मसमुद्भवः', transliteration: 'annādbhavanti bhūtāni parjanyādannasambhavaḥ .\nyajñādbhavati parjanyo yajñaḥ karmasamudbhavaḥ', meaning: 'From food beings come to be; from rain comes food; from sacrifice comes rain; and sacrifice is born of action.', inShort: 'All life turns on a cycle of giving.'),
  GitaVerse(chapter: 3, verse: 15, sanskrit: 'कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम् |\nतस्मात्सर्वगतं ब्रह्म नित्यं यज्ञे प्रतिष्ठितम्', transliteration: 'karma brahmodbhavaṃ viddhi brahmākṣarasamudbhavam .\ntasmātsarvagataṃ brahma nityaṃ yajñe pratiṣṭhitam', meaning: 'Know that action springs from Brahman, and Brahman from the Imperishable; therefore the all-pervading Brahman is ever present in sacrifice.', inShort: 'Action itself is rooted in the divine.'),
  GitaVerse(chapter: 3, verse: 16, sanskrit: 'एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः |\nअघायुरिन्द्रियारामो मोघं पार्थ स जीवति', transliteration: 'evaṃ pravartitaṃ cakraṃ nānuvartayatīha yaḥ .\naghāyurindriyārāmo moghaṃ pārtha sa jīvati', meaning: 'He who does not keep turning the wheel thus set in motion, living in sin and delighting only in the senses, lives in vain, O Partha.', inShort: 'To take from the wheel and give nothing is to live in vain.'),
  GitaVerse(chapter: 3, verse: 17, sanskrit: 'यस्त्वात्मरतिरेव स्यादात्मतृप्तश्च मानवः |\nआत्मन्येव च सन्तुष्टस्तस्य कार्यं न विद्यते', transliteration: 'yastvātmaratireva syādātmatṛptaśca mānavaḥ .\nātmanyeva ca santuṣṭastasya kāryaṃ na vidyate', meaning: 'But the person who delights only in the Self, is content in the Self, and satisfied in the Self alone, has nothing he must do.', inShort: 'One full in the Self has nothing left to gain by action.'),
  GitaVerse(chapter: 3, verse: 18, sanskrit: 'नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन |\nन चास्य सर्वभूतेषु कश्चिदर्थव्यपाश्रयः', transliteration: 'naiva tasya kṛtenārtho nākṛteneha kaścana .\nna cāsya sarvabhūteṣu kaścidarthavyapāśrayaḥ', meaning: 'For him there is nothing to gain by acting here, nor anything lost by not acting; he depends on no one for any purpose.', inShort: 'Such a one needs nothing from acting or not acting.'),
  GitaVerse(chapter: 3, verse: 19, sanskrit: 'तस्मादसक्तः सततं कार्यं कर्म समाचर |\nअसक्तो ह्याचरन्कर्म परमाप्नोति पूरुषः', transliteration: 'tasmādasaktaḥ satataṃ kāryaṃ karma samācara .\nasakto hyācarankarma paramāpnoti pūruṣaḥ', meaning: 'Therefore, always do the work that must be done, without attachment; for by working without attachment one attains the Supreme.', inShort: 'Do your duty unattached, and you reach the highest.'),
  GitaVerse(chapter: 3, verse: 20, sanskrit: 'कर्मणैव हि संसिद्धिमास्थिता जनकादयः |\nलोकसंग्रहमेवापि सम्पश्यन्कर्तुमर्हसि', transliteration: 'karmaṇaiva hi saṃsiddhimāsthitā janakādayaḥ .\nlokasaṃgrahamevāpi sampaśyankartumarhasi', meaning: 'It was by action alone that Janaka and others attained perfection. You too should act, if only for the guidance of the world.', inShort: 'Even the wise acted, for the world\'s sake.'),
  GitaVerse(chapter: 3, verse: 21, sanskrit: 'यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः |\nस यत्प्रमाणं कुरुते लोकस्तदनुवर्तते', transliteration: 'yadyadācarati śreṣṭhastattadevetaro janaḥ .\nsa yatpramāṇaṃ kurute lokastadanuvartate', meaning: 'Whatever a great person does, others follow; whatever standard he sets, the world imitates.', inShort: 'People follow the example of the great.'),
  GitaVerse(chapter: 3, verse: 22, sanskrit: 'न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किञ्चन |\nनानवाप्तमवाप्तव्यं वर्त एव च कर्मणि', transliteration: 'na me pārthāsti kartavyaṃ triṣu lokeṣu kiñcana .\nnānavāptamavāptavyaṃ varta eva ca karmaṇi', meaning: 'For me, O Partha, there is nothing in the three worlds that I must do, nothing unattained that I need to gain, yet I still engage in action.', inShort: 'Even I, needing nothing, keep acting.'),
  GitaVerse(chapter: 3, verse: 23, sanskrit: 'यदि ह्यहं न वर्तेयं जातु कर्मण्यतन्द्रितः |\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः', transliteration: 'yadi hyahaṃ na varteyaṃ jātu karmaṇyatandritaḥ .\nmama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ', meaning: 'For if I did not tirelessly engage in action, O Partha, people everywhere would follow My example.', inShort: 'If I stopped acting, all would follow suit.'),
  GitaVerse(chapter: 3, verse: 24, sanskrit: 'उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम् |\nसङ्करस्य च कर्ता स्यामुपहन्यामिमाः प्रजाः', transliteration: 'utsīdeyurime lokā na kuryāṃ karma cedaham .\nsaṅkarasya ca kartā syāmupahanyāmimāḥ prajāḥ', meaning: 'If I did not act, these worlds would fall into ruin; I would be the author of confusion and would destroy these people.', inShort: 'My inaction would bring the world to ruin.'),
  GitaVerse(chapter: 3, verse: 25, sanskrit: 'सक्ताः कर्मण्यविद्वांसो यथा कुर्वन्ति भारत |\nकुर्याद्विद्वांस्तथासक्तश्चिकीर्षुर्लोकसंग्रहम्', transliteration: 'saktāḥ karmaṇyavidvāṃso yathā kurvanti bhārata .\nkuryādvidvāṃstathāsaktaścikīrṣurlokasaṃgraham', meaning: 'As the ignorant act with attachment to their work, O Bharata, so should the wise act, but without attachment, for the welfare of the world.', inShort: 'The wise act unattached, for the world\'s good.'),
  GitaVerse(chapter: 3, verse: 26, sanskrit: 'न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम् |\nजोषयेत्सर्वकर्माणि विद्वान्युक्तः समाचरन्', transliteration: 'na buddhibhedaṃ janayedajñānāṃ karmasaṅginām .\njoṣayetsarvakarmāṇi vidvānyuktaḥ samācaran', meaning: 'Let the wise not unsettle the minds of the ignorant attached to action; rather, acting devotedly, let him inspire them to do all their duties well.', inShort: 'Don\'t unsettle others; inspire them by doing well.'),
  GitaVerse(chapter: 3, verse: 27, sanskrit: 'प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः |\nअहङ्कारविमूढात्मा कर्ताहमिति मन्यते', transliteration: 'prakṛteḥ kriyamāṇāni guṇaiḥ karmāṇi sarvaśaḥ .\nahaṅkāravimūḍhātmā kartāhamiti manyate', meaning: 'All actions are performed by the qualities of nature; but one deluded by ego imagines that he himself is the doer.', inShort: 'Nature does the work; ego claims to be the doer.'),
  GitaVerse(chapter: 3, verse: 28, sanskrit: 'तत्त्ववित्तु महाबाहो गुणकर्मविभागयोः |\nगुणा गुणेषु वर्तन्त इति मत्वा न सज्जते', transliteration: 'tattvavittu mahābāho guṇakarmavibhāgayoḥ .\nguṇā guṇeṣu vartanta iti matvā na sajjate', meaning: 'But he who knows the truth about the roles of the qualities and of action, O mighty-armed, sees that the qualities merely act upon the qualities, and stays unattached.', inShort: 'The wise see the qualities at play and stay free.'),
  GitaVerse(chapter: 3, verse: 29, sanskrit: 'प्रकृतेर्गुणसम्मूढाः सज्जन्ते गुणकर्मसु |\nतानकृत्स्नविदो मन्दान्कृत्स्नविन्न विचालयेत्', transliteration: 'prakṛterguṇasammūḍhāḥ sajjante guṇakarmasu .\ntānakṛtsnavido mandānkṛtsnavinna vicālayet', meaning: 'Those deluded by the qualities of nature cling to its workings; let the one who knows the whole not unsettle the dull who know only a part.', inShort: 'Don\'t disturb those still caught in nature\'s grip.'),
  GitaVerse(chapter: 3, verse: 30, sanskrit: 'मयि सर्वाणि कर्माणि संन्यस्याध्यात्मचेतसा |\nनिराशीर्निर्ममो भूत्वा युध्यस्व विगतज्वरः', transliteration: 'mayi sarvāṇi karmāṇi saṃnyasyādhyātmacetasā .\nnirāśīrnirmamo bhūtvā yudhyasva vigatajvaraḥ', meaning: 'Surrendering all actions to Me, with your mind fixed on the Self, free from craving and selfishness, and rid of feverish anxiety, fight.', inShort: 'Offer all you do to Me, and act free of fever.'),
  GitaVerse(chapter: 3, verse: 31, sanskrit: 'ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः |\nश्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः', transliteration: 'ye me matamidaṃ nityamanutiṣṭhanti mānavāḥ .\nśraddhāvanto.anasūyanto mucyante te.api karmabhiḥ', meaning: 'Those who ever practice this teaching of Mine with faith, and without finding fault, are freed from the bondage of action.', inShort: 'Practice this with faith and be freed from bondage.'),
  GitaVerse(chapter: 3, verse: 32, sanskrit: 'ये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम् |\nसर्वज्ञानविमूढांस्तान्विद्धि नष्टानचेतसः', transliteration: 'ye tvetadabhyasūyanto nānutiṣṭhanti me matam .\nsarvajñānavimūḍhāṃstānviddhi naṣṭānacetasaḥ', meaning: 'But those who find fault with My teaching and do not practice it, deluded in all knowledge and without sense, know them to be lost.', inShort: 'Those who scorn and ignore it are lost.'),
  GitaVerse(chapter: 3, verse: 33, sanskrit: 'सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि |\nप्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति', transliteration: 'sadṛśaṃ ceṣṭate svasyāḥ prakṛterjñānavānapi .\nprakṛtiṃ yānti bhūtāni nigrahaḥ kiṃ kariṣyati', meaning: 'Even a wise person acts according to his own nature; all beings follow their nature. What can forced restraint accomplish?', inShort: 'Even the wise follow their nature; forcing helps little.'),
  GitaVerse(chapter: 3, verse: 34, sanskrit: 'इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ |\nतयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ', transliteration: 'indriyasyendriyasyārthe rāgadveṣau vyavasthitau .\ntayorna vaśamāgacchettau hyasya paripanthinau', meaning: 'Attraction and aversion abide in the senses toward their objects; let no one fall under their sway, for they are one\'s enemies.', inShort: 'Beware likes and dislikes; they are your foes.'),
  GitaVerse(chapter: 3, verse: 35, sanskrit: 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् |\nस्वधर्मे निधनं श्रेयः परधर्मो भयावहः', transliteration: 'śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt .\nsvadharme nidhanaṃ śreyaḥ paradharmo bhayāvahaḥ', meaning: 'Better one\'s own duty, though imperfect, than another\'s duty well performed. Better to die in one\'s own duty; another\'s duty brings danger.', inShort: 'Better your own duty done poorly than another\'s done well.'),
  GitaVerse(chapter: 3, verse: 36, sanskrit: 'अर्जुन उवाच |\nअथ केन प्रयुक्तोऽयं पापं चरति पूरुषः |\nअनिच्छन्नपि वार्ष्णेय बलादिव नियोजितः', transliteration: 'arjuna uvāca .\natha kena prayukto.ayaṃ pāpaṃ carati pūruṣaḥ .\nanicchannapi vārṣṇeya balādiva niyojitaḥ', meaning: 'Arjuna said: But what impels a person to commit wrong, O Krishna, even against his will, as if driven by force?', inShort: 'Arjuna: what drives us to sin against our will?'),
  GitaVerse(chapter: 3, verse: 37, sanskrit: 'श्रीभगवानुवाच |\nकाम एष क्रोध एष रजोगुणसमुद्भवः |\nमहाशनो महापाप्मा विद्ध्येनमिह वैरिणम्', transliteration: 'śrībhagavānuvāca .\nkāma eṣa krodha eṣa rajoguṇasamudbhavaḥ .\nmahāśano mahāpāpmā viddhyenamiha vairiṇam', meaning: 'The Blessed Lord said: It is desire, it is anger, born of the quality of passion, all-devouring and most harmful. Know this to be the enemy here.', inShort: 'Krishna: desire and anger are the enemy.'),
  GitaVerse(chapter: 3, verse: 38, sanskrit: 'धूमेनाव्रियते वह्निर्यथादर्शो मलेन च |\nयथोल्बेनावृतो गर्भस्तथा तेनेदमावृतम्', transliteration: 'dhūmenāvriyate vahniryathādarśo malena ca .\nyatholbenāvṛto garbhastathā tenedamāvṛtam', meaning: 'As fire is veiled by smoke, a mirror by dust, and an embryo by the womb, so is wisdom veiled by desire.', inShort: 'Desire clouds wisdom like smoke over fire.'),
  GitaVerse(chapter: 3, verse: 39, sanskrit: 'आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा |\nकामरूपेण कौन्तेय दुष्पूरेणानलेन च', transliteration: 'āvṛtaṃ jñānametena jñānino nityavairiṇā .\nkāmarūpeṇa kaunteya duṣpūreṇānalena ca', meaning: 'Wisdom is veiled, O Arjuna, by this constant enemy of the wise: desire, an ever-hungry fire.', inShort: 'Desire is an unquenchable fire hiding wisdom.'),
  GitaVerse(chapter: 3, verse: 40, sanskrit: 'इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते |\nएतैर्विमोहयत्येष ज्ञानमावृत्य देहिनम्', transliteration: 'indriyāṇi mano buddhirasyādhiṣṭhānamucyate .\netairvimohayatyeṣa jñānamāvṛtya dehinam', meaning: 'The senses, the mind, and the intellect are said to be its seat; through these it veils wisdom and deludes the embodied soul.', inShort: 'Desire hides in the senses, mind, and reason.'),
  GitaVerse(chapter: 3, verse: 41, sanskrit: 'तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ |\nपाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम्', transliteration: 'tasmāttvamindriyāṇyādau niyamya bharatarṣabha .\npāpmānaṃ prajahi hyenaṃ jñānavijñānanāśanam', meaning: 'Therefore, O best of the Bharatas, first master the senses, and then slay this destroyer of knowledge and wisdom.', inShort: 'Master the senses, then destroy desire.'),
  GitaVerse(chapter: 3, verse: 42, sanskrit: 'इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः |\nमनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः', transliteration: 'indriyāṇi parāṇyāhurindriyebhyaḥ paraṃ manaḥ .\nmanasastu parā buddhiryo buddheḥ paratastu saḥ', meaning: 'The senses are said to be great; greater than the senses is the mind; greater than the mind is the intellect; and greater even than the intellect is the Self.', inShort: 'Beyond senses, mind, and reason lies the Self.'),
  GitaVerse(chapter: 3, verse: 43, sanskrit: 'एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना |\nजहि शत्रुं महाबाहो कामरूपं दुरासदम्', transliteration: 'evaṃ buddheḥ paraṃ buddhvā saṃstabhyātmānamātmanā .\njahi śatruṃ mahābāho kāmarūpaṃ durāsadam', meaning: 'Knowing the Self, which is beyond the intellect, steady the lower self by the higher Self, and slay this enemy in the form of desire, so hard to conquer, O mighty-armed.', inShort: 'Know the Self, and conquer desire at last.'),
  GitaVerse(chapter: 4, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nइमं विवस्वते योगं प्रोक्तवानहमव्ययम् |\nविवस्वान्मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत्', transliteration: 'śrībhagavānuvāca .\nimaṃ vivasvate yogaṃ proktavānahamavyayam .\nvivasvānmanave prāha manurikṣvākave.abravīt', meaning: 'The Blessed Lord said: I taught this imperishable yoga to Vivasvan, the sun; Vivasvan told it to Manu, and Manu to Ikshvaku.', inShort: 'Krishna: I taught this ancient yoga long ago.'),
  GitaVerse(chapter: 4, verse: 2, sanskrit: 'एवं परम्पराप्राप्तमिमं राजर्षयो विदुः |\nस कालेनेह महता योगो नष्टः परन्तप', transliteration: 'evaṃ paramparāprāptamimaṃ rājarṣayo viduḥ .\nsa kāleneha mahatā yogo naṣṭaḥ parantapa', meaning: 'Handed down thus in succession, the royal sages knew it; but over long ages, O scorcher of foes, this yoga was lost.', inShort: 'Passed down by sages, it was lost over time.'),
  GitaVerse(chapter: 4, verse: 3, sanskrit: 'स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः |\nभक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम्', transliteration: 'sa evāyaṃ mayā te.adya yogaḥ proktaḥ purātanaḥ .\nbhakto.asi me sakhā ceti rahasyaṃ hyetaduttamam', meaning: 'That same ancient yoga I have taught you today, for you are My devotee and My friend; this is the supreme secret.', inShort: 'I now teach you this same supreme secret.'),
  GitaVerse(chapter: 4, verse: 4, sanskrit: 'अर्जुन उवाच |\nअपरं भवतो जन्म परं जन्म विवस्वतः |\nकथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति', transliteration: 'arjuna uvāca .\naparaṃ bhavato janma paraṃ janma vivasvataḥ .\nkathametadvijānīyāṃ tvamādau proktavāniti', meaning: 'Arjuna said: Your birth was later, and Vivasvan\'s was long ago; how am I to understand that you taught it in the beginning?', inShort: 'Arjuna: how could you have taught it so long ago?'),
  GitaVerse(chapter: 4, verse: 5, sanskrit: 'श्रीभगवानुवाच |\nबहूनि मे व्यतीतानि जन्मानि तव चार्जुन |\nतान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप', transliteration: 'śrībhagavānuvāca .\nbahūni me vyatītāni janmāni tava cārjuna .\ntānyahaṃ veda sarvāṇi na tvaṃ vettha parantapa', meaning: 'The Blessed Lord said: Many are the births that you and I have passed through, O Arjuna; I remember them all, but you do not.', inShort: 'We have both lived many lives; I remember them all.'),
  GitaVerse(chapter: 4, verse: 6, sanskrit: 'अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन् |\nप्रकृतिं स्वामधिष्ठाय सम्भवाम्यात्ममायया', transliteration: 'ajo.api sannavyayātmā bhūtānāmīśvaro.api san .\nprakṛtiṃ svāmadhiṣṭhāya sambhavāmyātmamāyayā', meaning: 'Though I am unborn and imperishable, the Lord of all beings, yet ruling over My own nature, I come into being through My own power.', inShort: 'Though unborn, I take birth by My own power.'),
  GitaVerse(chapter: 4, verse: 7, sanskrit: 'यदा यदा हि धर्मस्य ग्लानिर्भवति भारत |\nअभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम्', transliteration: 'yadā yadā hi dharmasya glānirbhavati bhārata .\nabhyutthānamadharmasya tadātmānaṃ sṛjāmyaham', meaning: 'Whenever righteousness declines and unrighteousness rises, O Bharata, then I bring Myself forth.', inShort: 'Whenever dharma fades, I appear.'),
  GitaVerse(chapter: 4, verse: 8, sanskrit: 'परित्राणाय साधूनां विनाशाय च दुष्कृताम् |\nधर्मसंस्थापनार्थाय सम्भवामि युगे युगे', transliteration: 'paritrāṇāya sādhūnāṃ vināśāya ca duṣkṛtām .\ndharmasaṃsthāpanārthāya sambhavāmi yuge yuge', meaning: 'To protect the good, to destroy the wicked, and to firmly establish righteousness, I am born in age after age.', inShort: 'I come, age after age, to restore what is right.'),
  GitaVerse(chapter: 4, verse: 9, sanskrit: 'जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः |\nत्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन', transliteration: 'janma karma ca me divyamevaṃ yo vetti tattvataḥ .\ntyaktvā dehaṃ punarjanma naiti māmeti so.arjuna', meaning: 'He who truly knows My divine birth and action, on leaving the body, is not born again but comes to Me, O Arjuna.', inShort: 'Knowing My divine birth truly, one comes to Me.'),
  GitaVerse(chapter: 4, verse: 10, sanskrit: 'वीतरागभयक्रोधा मन्मया मामुपाश्रिताः |\nबहवो ज्ञानतपसा पूता मद्भावमागताः', transliteration: 'vītarāgabhayakrodhā manmayā māmupāśritāḥ .\nbahavo jñānatapasā pūtā madbhāvamāgatāḥ', meaning: 'Freed from attachment, fear, and anger, absorbed in Me, taking refuge in Me, purified by the fire of knowledge, many have attained My being.', inShort: 'Purified by knowledge, many have reached Me.'),
  GitaVerse(chapter: 4, verse: 11, sanskrit: 'ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम् |\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः', transliteration: 'ye yathā māṃ prapadyante tāṃstathaiva bhajāmyaham .\nmama vartmānuvartante manuṣyāḥ pārtha sarvaśaḥ', meaning: 'In whatever way people approach Me, so do I meet them; for the paths people follow from every side are Mine, O Partha.', inShort: 'However you seek Me, I meet you there.'),
  GitaVerse(chapter: 4, verse: 12, sanskrit: 'काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः |\nक्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा', transliteration: 'kāṅkṣantaḥ karmaṇāṃ siddhiṃ yajanta iha devatāḥ .\nkṣipraṃ hi mānuṣe loke siddhirbhavati karmajā', meaning: 'Desiring success in their actions, people worship the gods here; for in this human world, success from action comes quickly.', inShort: 'People worship for quick worldly success.'),
  GitaVerse(chapter: 4, verse: 13, sanskrit: 'चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः |\nतस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम्', transliteration: 'cāturvarṇyaṃ mayā sṛṣṭaṃ guṇakarmavibhāgaśaḥ .\ntasya kartāramapi māṃ viddhyakartāramavyayam', meaning: 'The four orders of society were brought forth by Me, according to the distribution of qualities and actions. Though I am their author, know Me to be the changeless non-doer.', inShort: 'I made the social order, yet remain the changeless non-doer.'),
  GitaVerse(chapter: 4, verse: 14, sanskrit: 'न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा |\nइति मां योऽभिजानाति कर्मभिर्न स बध्यते', transliteration: 'na māṃ karmāṇi limpanti na me karmaphale spṛhā .\niti māṃ yo.abhijānāti karmabhirna sa badhyate', meaning: 'Actions do not taint Me, nor do I long for their fruits. He who knows Me thus is not bound by actions.', inShort: 'Action does not bind Me; knowing this frees you too.'),
  GitaVerse(chapter: 4, verse: 15, sanskrit: 'एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः |\nकुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम्', transliteration: 'evaṃ jñātvā kṛtaṃ karma pūrvairapi mumukṣubhiḥ .\nkuru karmaiva tasmāttvaṃ pūrvaiḥ pūrvataraṃ kṛtam', meaning: 'Knowing this, the ancient seekers of liberation also performed action. Therefore do your action as the ancients did in olden times.', inShort: 'The ancients acted knowing this; so should you.'),
  GitaVerse(chapter: 4, verse: 16, sanskrit: 'किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः |\nतत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात्', transliteration: 'kiṃ karma kimakarmeti kavayo.apyatra mohitāḥ .\ntatte karma pravakṣyāmi yajjñātvā mokṣyase.aśubhāt', meaning: 'What is action and what is inaction? Even the wise are confused about this. So I shall teach you the action by which you will be freed from ill.', inShort: 'Even the wise are puzzled by action and inaction.'),
  GitaVerse(chapter: 4, verse: 17, sanskrit: 'कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः |\nअकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः', transliteration: 'karmaṇo hyapi boddhavyaṃ boddhavyaṃ ca vikarmaṇaḥ .\nakarmaṇaśca boddhavyaṃ gahanā karmaṇo gatiḥ', meaning: 'One must understand action, wrong action, and inaction; the true nature of action is deep and hard to grasp.', inShort: 'The nature of action is subtle and hard to grasp.'),
  GitaVerse(chapter: 4, verse: 18, sanskrit: 'कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः |\nस बुद्धिमान्मनुष्येषु स युक्तः कृत्स्नकर्मकृत्', transliteration: 'karmaṇyakarma yaḥ paśyedakarmaṇi ca karma yaḥ .\nsa buddhimānmanuṣyeṣu sa yuktaḥ kṛtsnakarmakṛt', meaning: 'He who sees inaction in action, and action in inaction, is wise among people; he is a yogi who has done all he needs to do.', inShort: 'See stillness within action, and action within stillness.'),
  GitaVerse(chapter: 4, verse: 19, sanskrit: 'यस्य सर्वे समारम्भाः कामसङ्कल्पवर्जिताः |\nज्ञानाग्निदग्धकर्माणं तमाहुः पण्डितं बुधाः', transliteration: 'yasya sarve samārambhāḥ kāmasaṅkalpavarjitāḥ .\njñānāgnidagdhakarmāṇaṃ tamāhuḥ paṇḍitaṃ budhāḥ', meaning: 'He whose every undertaking is free of desire and selfish motive, whose actions are burned up in the fire of knowledge, him the wise call learned.', inShort: 'The wise burn selfish motive in the fire of knowledge.'),
  GitaVerse(chapter: 4, verse: 20, sanskrit: 'त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः |\nकर्मण्यभिप्रवृत्तोऽपि नैव किञ्चित्करोति सः', transliteration: 'tyaktvā karmaphalāsaṅgaṃ nityatṛpto nirāśrayaḥ .\nkarmaṇyabhipravṛtto.api naiva kiñcitkaroti saḥ', meaning: 'Having given up attachment to the fruits of action, ever content, depending on nothing, he does nothing at all, even while fully engaged in action.', inShort: 'Content and unattached, he acts yet does nothing.'),
  GitaVerse(chapter: 4, verse: 21, sanskrit: 'निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः |\nशारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम्', transliteration: 'nirāśīryatacittātmā tyaktasarvaparigrahaḥ .\nśārīraṃ kevalaṃ karma kurvannāpnoti kilbiṣam', meaning: 'Desiring nothing, his mind and self controlled, giving up all sense of possession, performing action with the body alone, he incurs no fault.', inShort: 'Acting with body alone, free of grasping, he stays blameless.'),
  GitaVerse(chapter: 4, verse: 22, sanskrit: 'यदृच्छालाभसन्तुष्टो द्वन्द्वातीतो विमत्सरः |\nसमः सिद्धावसिद्धौ च कृत्वापि न निबध्यते', transliteration: 'yadṛcchālābhasantuṣṭo dvandvātīto vimatsaraḥ .\nsamaḥ siddhāvasiddhau ca kṛtvāpi na nibadhyate', meaning: 'Content with whatever comes unsought, beyond the pairs of opposites, free from envy, even-minded in success and failure, he is not bound even when he acts.', inShort: 'Content with what comes, even-minded, he stays free.'),
  GitaVerse(chapter: 4, verse: 23, sanskrit: 'गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः |\nयज्ञायाचरतः कर्म समग्रं प्रविलीयते', transliteration: 'gatasaṅgasya muktasya jñānāvasthitacetasaḥ .\nyajñāyācarataḥ karma samagraṃ pravilīyate', meaning: 'For one who is free from attachment, liberated, his mind established in knowledge, acting only as sacrifice, all his action dissolves away.', inShort: 'For the free soul acting as sacrifice, all action dissolves.'),
  GitaVerse(chapter: 4, verse: 24, sanskrit: 'ब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम् |\nब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना', transliteration: 'brahmārpaṇaṃ brahma havirbrahmāgnau brahmaṇā hutam .\nbrahmaiva tena gantavyaṃ brahmakarmasamādhinā', meaning: 'The offering is the divine, the oblation is the divine, offered by the divine into the fire of the divine; the divine alone is reached by one absorbed in divine action.', inShort: 'For the awakened, all of action is the divine itself.'),
  GitaVerse(chapter: 4, verse: 25, sanskrit: 'दैवमेवापरे यज्ञं योगिनः पर्युपासते |\nब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति', transliteration: 'daivamevāpare yajñaṃ yoginaḥ paryupāsate .\nbrahmāgnāvapare yajñaṃ yajñenaivopajuhvati', meaning: 'Some yogis offer sacrifice to the gods; others offer the self as sacrifice into the fire of the divine.', inShort: 'People offer in many ways, outwardly and inwardly.'),
  GitaVerse(chapter: 4, verse: 26, sanskrit: 'श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति |\nशब्दादीन्विषयानन्य इन्द्रियाग्निषु जुह्वति', transliteration: 'śrotrādīnīndriyāṇyanye saṃyamāgniṣu juhvati .\nśabdādīnviṣayānanya indriyāgniṣu juhvati', meaning: 'Some offer hearing and the other senses into the fires of restraint; others offer sound and the other objects into the fires of the senses.', inShort: 'Some sacrifice the senses; some, sense-objects.'),
  GitaVerse(chapter: 4, verse: 27, sanskrit: 'सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे |\nआत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते', transliteration: 'sarvāṇīndriyakarmāṇi prāṇakarmāṇi cāpare .\nātmasaṃyamayogāgnau juhvati jñānadīpite', meaning: 'Others offer all the actions of the senses and the workings of the vital breath into the fire of self-control, kindled by knowledge.', inShort: 'Some offer all sense-activity into self-control.'),
  GitaVerse(chapter: 4, verse: 28, sanskrit: 'द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे |\nस्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः', transliteration: 'dravyayajñāstapoyajñā yogayajñāstathāpare .\nsvādhyāyajñānayajñāśca yatayaḥ saṃśitavratāḥ', meaning: 'Some offer their wealth, some austerity, some the practice of yoga; and some, of firm vows, offer knowledge through the study of scripture.', inShort: 'People offer wealth, austerity, yoga, or study.'),
  GitaVerse(chapter: 4, verse: 29, sanskrit: 'अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे |\nप्राणापानगती रुद्ध्वा प्राणायामपरायणाः', transliteration: 'apāne juhvati prāṇaṃ prāṇe.apānaṃ tathāpare .\nprāṇāpānagatī ruddhvā prāṇāyāmaparāyaṇāḥ', meaning: 'Others, devoted to breath-control, offer the outgoing breath into the incoming, and the incoming into the outgoing, restraining their flow.', inShort: 'Some offer breath into breath, mastering it.'),
  GitaVerse(chapter: 4, verse: 30, sanskrit: 'अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति |\nसर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः', transliteration: 'apare niyatāhārāḥ prāṇānprāṇeṣu juhvati .\nsarve.apyete yajñavido yajñakṣapitakalmaṣāḥ', meaning: 'Others, eating in measure, offer their life-breaths into the life-breaths. All these know sacrifice, and by sacrifice their impurities are destroyed.', inShort: 'All these truly know sacrifice and are cleansed by it.'),
  GitaVerse(chapter: 4, verse: 31, sanskrit: 'यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम् |\nनायं लोकोऽस्त्ययज्ञस्य कुतोऽन्यः कुरुसत्तम', transliteration: 'yajñaśiṣṭāmṛtabhujo yānti brahma sanātanam .\nnāyaṃ loko.astyayajñasya kuto.anyaḥ kurusattama', meaning: 'Those who partake of the sacred remnant of sacrifice reach the eternal. This world is not for the one who offers nothing; how then the next, O best of the Kurus?', inShort: 'Without any offering, neither world is won.'),
  GitaVerse(chapter: 4, verse: 32, sanskrit: 'एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे |\nकर्मजान्विद्धि तान्सर्वानेवं ज्ञात्वा विमोक्ष्यसे', transliteration: 'evaṃ bahuvidhā yajñā vitatā brahmaṇo mukhe .\nkarmajānviddhi tānsarvānevaṃ jñātvā vimokṣyase', meaning: 'Thus many kinds of sacrifice are spread out before the divine. Know them all to be born of action; knowing this, you shall be free.', inShort: 'All these sacrifices are born of action; knowing this frees you.'),
  GitaVerse(chapter: 4, verse: 33, sanskrit: 'श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परन्तप |\nसर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते', transliteration: 'śreyāndravyamayādyajñājjñānayajñaḥ parantapa .\nsarvaṃ karmākhilaṃ pārtha jñāne parisamāpyate', meaning: 'The sacrifice of knowledge is greater than any sacrifice of things, O scorcher of foes; for all action, without exception, culminates in knowledge.', inShort: 'The offering of knowledge surpasses all others.'),
  GitaVerse(chapter: 4, verse: 34, sanskrit: 'तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया |\nउपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः', transliteration: 'tadviddhi praṇipātena paripraśnena sevayā .\nupadekṣyanti te jñānaṃ jñāninastattvadarśinaḥ', meaning: 'Learn this by humble reverence, by sincere inquiry, and by service; the wise who have seen the truth will teach you knowledge.', inShort: 'Seek truth with humility, questions, and service.'),
  GitaVerse(chapter: 4, verse: 35, sanskrit: 'यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव |\nयेन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि (var अशेषाणि)', transliteration: 'yajjñātvā na punarmohamevaṃ yāsyasi pāṇḍava .\nyena bhūtānyaśeṣāṇi drakṣyasyātmanyatho mayi', meaning: 'Knowing this, you will not fall again into delusion, O Arjuna; by it you will see all beings in yourself, and then in Me.', inShort: 'This knowledge ends delusion; you will see all in Me.'),
  GitaVerse(chapter: 4, verse: 36, sanskrit: 'अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः |\nसर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि', transliteration: 'api cedasi pāpebhyaḥ sarvebhyaḥ pāpakṛttamaḥ .\nsarvaṃ jñānaplavenaiva vṛjinaṃ santariṣyasi', meaning: 'Even if you were the most sinful of all sinners, you would cross over all wickedness by the raft of knowledge.', inShort: 'The raft of knowledge carries even the worst across.'),
  GitaVerse(chapter: 4, verse: 37, sanskrit: 'यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन |\nज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा', transliteration: 'yathaidhāṃsi samiddho.agnirbhasmasātkurute.arjuna .\njñānāgniḥ sarvakarmāṇi bhasmasātkurute tathā', meaning: 'As a kindled fire reduces firewood to ashes, O Arjuna, so does the fire of knowledge reduce all actions to ashes.', inShort: 'Knowledge burns all karma as fire burns wood.'),
  GitaVerse(chapter: 4, verse: 38, sanskrit: 'न हि ज्ञानेन सदृशं पवित्रमिह विद्यते |\nतत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति', transliteration: 'na hi jñānena sadṛśaṃ pavitramiha vidyate .\ntatsvayaṃ yogasaṃsiddhaḥ kālenātmani vindati', meaning: 'There is nothing in this world so purifying as knowledge; one perfected in yoga finds it in time within himself.', inShort: 'Nothing purifies like knowledge, found within in time.'),
  GitaVerse(chapter: 4, verse: 39, sanskrit: 'श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः |\nज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति', transliteration: 'śraddhāvāṃllabhate jñānaṃ tatparaḥ saṃyatendriyaḥ .\njñānaṃ labdhvā parāṃ śāntimacireṇādhigacchati', meaning: 'The person of faith, devoted, and mastering the senses, attains knowledge; and having attained it, he soon reaches supreme peace.', inShort: 'The faithful and self-controlled soon reach supreme peace.'),
  GitaVerse(chapter: 4, verse: 40, sanskrit: 'अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति |\nनायं लोकोऽस्ति न परो न सुखं संशयात्मनः', transliteration: 'ajñaścāśraddadhānaśca saṃśayātmā vinaśyati .\nnāyaṃ loko.asti na paro na sukhaṃ saṃśayātmanaḥ', meaning: 'But the ignorant, faithless, doubting soul perishes; for the doubter there is neither this world, nor the next, nor happiness.', inShort: 'The doubting soul finds no world and no peace.'),
  GitaVerse(chapter: 4, verse: 41, sanskrit: 'योगसंन्यस्तकर्माणं ज्ञानसञ्छिन्नसंशयम् |\nआत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय', transliteration: 'yogasaṃnyastakarmāṇaṃ jñānasañchinnasaṃśayam .\nātmavantaṃ na karmāṇi nibadhnanti dhanañjaya', meaning: 'Actions do not bind one who has renounced action through yoga, whose doubts are cut away by knowledge, and who is poised in the Self, O Arjuna.', inShort: 'Freed by knowledge and yoga, action cannot bind you.'),
  GitaVerse(chapter: 4, verse: 42, sanskrit: 'तस्मादज्ञानसम्भूतं हृत्स्थं ज्ञानासिनात्मनः |\nछित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत', transliteration: 'tasmādajñānasambhūtaṃ hṛtsthaṃ jñānāsinātmanaḥ .\nchittvainaṃ saṃśayaṃ yogamātiṣṭhottiṣṭha bhārata', meaning: 'Therefore, cutting with the sword of knowledge this doubt in your heart, born of ignorance, take refuge in yoga and arise, O Arjuna.', inShort: 'Cut your doubt with knowledge, take to yoga, and rise.'),
  GitaVerse(chapter: 5, verse: 1, sanskrit: 'अर्जुन उवाच |\nसंन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि |\nयच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्चितम्', transliteration: 'arjuna uvāca .\nsaṃnyāsaṃ karmaṇāṃ kṛṣṇa punaryogaṃ ca śaṃsasi .\nyacchreya etayorekaṃ tanme brūhi suniścitam', meaning: 'Arjuna said: You praise the renunciation of actions, O Krishna, and also their performance in yoga. Tell me decisively which of the two is the better.', inShort: 'Arjuna: which is better — renouncing action, or acting in yoga?'),
  GitaVerse(chapter: 5, verse: 2, sanskrit: 'श्रीभगवानुवाच |\nसंन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ |\nतयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते', transliteration: 'śrībhagavānuvāca .\nsaṃnyāsaḥ karmayogaśca niḥśreyasakarāvubhau .\ntayostu karmasaṃnyāsātkarmayogo viśiṣyate', meaning: 'The Blessed Lord said: Both renunciation and the yoga of action lead to the highest good; but of the two, the yoga of action is better than the renunciation of action.', inShort: 'Both free you, but selfless action is the better road.'),
  GitaVerse(chapter: 5, verse: 3, sanskrit: 'ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति |\nनिर्द्वन्द्वो हि महाबाहो सुखं बन्धात्प्रमुच्यते', transliteration: 'jñeyaḥ sa nityasaṃnyāsī yo na dveṣṭi na kāṅkṣati .\nnirdvandvo hi mahābāho sukhaṃ bandhātpramucyate', meaning: 'He who neither hates nor desires should be known as a true renunciate; free from the pairs of opposites, O mighty-armed, he is easily released from bondage.', inShort: 'The true renunciate is free of likes and dislikes.'),
  GitaVerse(chapter: 5, verse: 4, sanskrit: 'साङ्ख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः |\nएकमप्यास्थितः सम्यगुभयोर्विन्दते फलम्', transliteration: 'sāṅkhyayogau pṛthagbālāḥ pravadanti na paṇḍitāḥ .\nekamapyāsthitaḥ samyagubhayorvindate phalam', meaning: 'Children, not the wise, speak of knowledge and action as separate; one who is truly established in either gains the fruit of both.', inShort: 'Knowledge and action are not two roads but one.'),
  GitaVerse(chapter: 5, verse: 5, sanskrit: 'यत्साङ्ख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते |\nएकं साङ्ख्यं च योगं च यः पश्यति स पश्यति', transliteration: 'yatsāṅkhyaiḥ prāpyate sthānaṃ tadyogairapi gamyate .\nekaṃ sāṅkhyaṃ ca yogaṃ ca yaḥ paśyati sa paśyati', meaning: 'The state reached by the followers of knowledge is also reached by the followers of action. He who sees knowledge and action as one truly sees.', inShort: 'Both paths arrive at the same place.'),
  GitaVerse(chapter: 5, verse: 6, sanskrit: 'संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः |\nयोगयुक्तो मुनिर्ब्रह्म नचिरेणाधिगच्छति', transliteration: 'saṃnyāsastu mahābāho duḥkhamāptumayogataḥ .\nyogayukto munirbrahma nacireṇādhigacchati', meaning: 'But renunciation, O mighty-armed, is hard to attain without yoga; the sage established in yoga quickly reaches Brahman.', inShort: 'Renunciation is hard without the yoga of action.'),
  GitaVerse(chapter: 5, verse: 7, sanskrit: 'योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः |\nसर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते', transliteration: 'yogayukto viśuddhātmā vijitātmā jitendriyaḥ .\nsarvabhūtātmabhūtātmā kurvannapi na lipyate', meaning: 'He who is established in yoga, pure in heart, master of himself and his senses, whose Self is the Self of all beings, is not tainted though he acts.', inShort: 'Acting purely and selflessly, nothing can stain you.'),
  GitaVerse(chapter: 5, verse: 8, sanskrit: 'नैव किञ्चित्करोमीति युक्तो मन्येत तत्त्ववित् |\nपश्यञ्शृण्वन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपञ्श्वसन्', transliteration: 'naiva kiñcitkaromīti yukto manyeta tattvavit .\npaśyañśruṇvanspṛśañjighrannaśnangacchansvapañśvasan', meaning: 'The knower of truth, though seeing, hearing, touching, smelling, eating, moving, sleeping, and breathing, thinks: I do nothing at all —', inShort: 'The wise one feels I am not the doer, even while acting.'),
  GitaVerse(chapter: 5, verse: 9, sanskrit: 'प्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि |\nइन्द्रियाणीन्द्रियार्थेषु वर्तन्त इति धारयन्', transliteration: 'pralapanvisṛjangṛhṇannunmiṣannimiṣannapi .\nindriyāṇīndriyārtheṣu vartanta iti dhārayan', meaning: 'speaking, letting go, grasping, opening and closing the eyes — convinced that the senses merely move among the objects of sense.', inShort: 'He knows it is only the senses meeting their objects.'),
  GitaVerse(chapter: 5, verse: 10, sanskrit: 'ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः |\nलिप्यते न स पापेन पद्मपत्रमिवाम्भसा', transliteration: 'brahmaṇyādhāya karmāṇi saṅgaṃ tyaktvā karoti yaḥ .\nlipyate na sa pāpena padmapatramivāmbhasā', meaning: 'He who acts, offering his actions to Brahman and abandoning attachment, is untouched by sin, as a lotus leaf is untouched by water.', inShort: 'Offer your actions, and stay unstained like a lotus leaf.'),
  GitaVerse(chapter: 5, verse: 11, sanskrit: 'कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि |\nयोगिनः कर्म कुर्वन्ति सङ्गं त्यक्त्वात्मशुद्धये', transliteration: 'kāyena manasā buddhyā kevalairindriyairapi .\nyoginaḥ karma kurvanti saṅgaṃ tyaktvātmaśuddhaye', meaning: 'Yogis perform action with body, mind, intellect, and even the senses alone, giving up attachment, for the purification of the self.', inShort: 'The yogi acts only to purify himself, free of clinging.'),
  GitaVerse(chapter: 5, verse: 12, sanskrit: 'युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम् |\nअयुक्तः कामकारेण फले सक्तो निबध्यते', transliteration: 'yuktaḥ karmaphalaṃ tyaktvā śāntimāpnoti naiṣṭhikīm .\nayuktaḥ kāmakāreṇa phale sakto nibadhyate', meaning: 'The disciplined one, giving up the fruit of action, attains lasting peace; the undisciplined, driven by desire and attached to results, is bound.', inShort: 'Let go of results and find lasting peace.'),
  GitaVerse(chapter: 5, verse: 13, sanskrit: 'सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी |\nनवद्वारे पुरे देही नैव कुर्वन्न कारयन्', transliteration: 'sarvakarmāṇi manasā saṃnyasyāste sukhaṃ vaśī .\nnavadvāre pure dehī naiva kurvanna kārayan', meaning: 'Renouncing all actions by the mind, the embodied one rests happily in the city of nine gates, neither acting nor causing action.', inShort: 'Mentally free, the soul rests at ease within the body.'),
  GitaVerse(chapter: 5, verse: 14, sanskrit: 'न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः |\nन कर्मफलसंयोगं स्वभावस्तु प्रवर्तते', transliteration: 'na kartṛtvaṃ na karmāṇi lokasya sṛjati prabhuḥ .\nna karmaphalasaṃyogaṃ svabhāvastu pravartate', meaning: 'The Lord creates neither the sense of agency nor the actions of the world, nor the joining of action to its fruit; it is nature that unfolds.', inShort: 'It is nature, not the Self, that drives the world\'s doing.'),
  GitaVerse(chapter: 5, verse: 15, sanskrit: 'नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः |\nअज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः', transliteration: 'nādatte kasyacitpāpaṃ na caiva sukṛtaṃ vibhuḥ .\najñānenāvṛtaṃ jñānaṃ tena muhyanti jantavaḥ', meaning: 'The all-pervading Lord takes on neither the sin nor the merit of anyone. Knowledge is veiled by ignorance; thereby creatures are deluded.', inShort: 'The divine takes on no one\'s sin or merit; ignorance deludes us.'),
  GitaVerse(chapter: 5, verse: 16, sanskrit: 'ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः |\nतेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम्', transliteration: 'jñānena tu tadajñānaṃ yeṣāṃ nāśitamātmanaḥ .\nteṣāmādityavajjñānaṃ prakāśayati tatparam', meaning: 'But for those whose ignorance is destroyed by knowledge of the Self, that knowledge, like the sun, reveals the Supreme.', inShort: 'Knowledge rises like the sun and reveals the Highest.'),
  GitaVerse(chapter: 5, verse: 17, sanskrit: 'तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः |\nगच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः', transliteration: 'tadbuddhayastadātmānastanniṣṭhāstatparāyaṇāḥ .\ngacchantyapunarāvṛttiṃ jñānanirdhūtakalmaṣāḥ', meaning: 'With intellect absorbed in That, their very self That, steadfast in That, That their supreme goal, they go where there is no return, their sins washed away by knowledge.', inShort: 'Fixed wholly on the Supreme, they never fall back.'),
  GitaVerse(chapter: 5, verse: 18, sanskrit: 'विद्याविनयसम्पन्ने ब्राह्मणे गवि हस्तिनि |\nशुनि चैव श्वपाके च पण्डिताः समदर्शिनः', transliteration: 'vidyāvinayasampanne brāhmaṇe gavi hastini .\nśuni caiva śvapāke ca paṇḍitāḥ samadarśinaḥ', meaning: 'The wise see with an equal eye a learned and humble brahmin, a cow, an elephant, a dog, and an outcaste.', inShort: 'The wise see the same divine in all beings, high or low.'),
  GitaVerse(chapter: 5, verse: 19, sanskrit: 'इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः |\nनिर्दोषं हि समं ब्रह्म तस्माद् ब्रह्मणि ते स्थिताः', transliteration: 'ihaiva tairjitaḥ sargo yeṣāṃ sāmye sthitaṃ manaḥ .\nnirdoṣaṃ hi samaṃ brahma tasmād brahmaṇi te sthitāḥ', meaning: 'Even here, rebirth is conquered by those whose mind rests in equality; for Brahman is flawless and the same in all, and so they are established in Brahman.', inShort: 'An even mind, here and now, rests in the flawless divine.'),
  GitaVerse(chapter: 5, verse: 20, sanskrit: 'न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम् |\nस्थिरबुद्धिरसम्मूढो ब्रह्मविद् ब्रह्मणि स्थितः', transliteration: 'na prahṛṣyetpriyaṃ prāpya nodvijetprāpya cāpriyam .\nsthirabuddhirasammūḍho brahmavid brahmaṇi sthitaḥ', meaning: 'One should neither rejoice on getting the pleasant nor grieve on getting the unpleasant; with steady intellect, undeluded, such a knower of Brahman rests in Brahman.', inShort: 'Neither thrilled nor crushed, the steady soul rests in Brahman.'),
  GitaVerse(chapter: 5, verse: 21, sanskrit: 'बाह्यस्पर्शेष्वसक्तात्मा विन्दत्यात्मनि यत्सुखम् |\nस ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते', transliteration: 'bāhyasparśeṣvasaktātmā vindatyātmani yatsukham .\nsa brahmayogayuktātmā sukhamakṣayamaśnute', meaning: 'With the self unattached to outer contacts, one finds the joy that is in the Self; united with Brahman through yoga, one enjoys undying bliss.', inShort: 'Turn inward and find the joy that never fades.'),
  GitaVerse(chapter: 5, verse: 22, sanskrit: 'ये हि संस्पर्शजा भोगा दुःखयोनय एव ते |\nआद्यन्तवन्तः कौन्तेय न तेषु रमते बुधः', transliteration: 'ye hi saṃsparśajā bhogā duḥkhayonaya eva te .\nādyantavantaḥ kaunteya na teṣu ramate budhaḥ', meaning: 'The pleasures born of sense-contact are only wombs of pain; they have a beginning and an end, O Arjuna. The wise do not delight in them.', inShort: 'Sense-pleasures begin and end in pain; the wise don\'t cling.'),
  GitaVerse(chapter: 5, verse: 23, sanskrit: 'शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात् |\nकामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः', transliteration: 'śaknotīhaiva yaḥ soḍhuṃ prākśarīravimokṣaṇāt .\nkāmakrodhodbhavaṃ vegaṃ sa yuktaḥ sa sukhī naraḥ', meaning: 'He who can withstand, here on earth before death, the force of desire and anger — he is a yogi, and he is a happy person.', inShort: 'Master desire and anger while you live, and be truly happy.'),
  GitaVerse(chapter: 5, verse: 24, sanskrit: 'योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः |\nस योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति', transliteration: 'yo.antaḥsukho.antarārāmastathāntarjyotireva yaḥ .\nsa yogī brahmanirvāṇaṃ brahmabhūto.adhigacchati', meaning: 'He whose happiness is within, whose delight is within, whose light is within — that yogi, becoming one with Brahman, attains the peace of Brahman.', inShort: 'The one whose joy is within becomes the peace he seeks.'),
  GitaVerse(chapter: 5, verse: 25, sanskrit: 'लभन्ते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः |\nछिन्नद्वैधा यतात्मानः सर्वभूतहिते रताः', transliteration: 'labhante brahmanirvāṇamṛṣayaḥ kṣīṇakalmaṣāḥ .\nchinnadvaidhā yatātmānaḥ sarvabhūtahite ratāḥ', meaning: 'The seers whose sins are destroyed, whose doubts are cut away, who are self-controlled and delight in the welfare of all beings, attain the peace of Brahman.', inShort: 'Free of doubt and devoted to all beings\' good, they find peace.'),
  GitaVerse(chapter: 5, verse: 26, sanskrit: 'कामक्रोधवियुक्तानां यतीनां यतचेतसाम् |\nअभितो ब्रह्मनिर्वाणं वर्तते विदितात्मनाम्', transliteration: 'kāmakrodhaviyuktānāṃ yatīnāṃ yatacetasām .\nabhito brahmanirvāṇaṃ vartate viditātmanām', meaning: 'For those free from desire and anger, self-controlled, who have known the Self, the peace of Brahman is near, here and everywhere.', inShort: 'Free of craving and anger, peace is already near.'),
  GitaVerse(chapter: 5, verse: 27, sanskrit: 'स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवान्तरे भ्रुवोः |\nप्राणापानौ समौ कृत्वा नासाभ्यन्तरचारिणौ', transliteration: 'sparśānkṛtvā bahirbāhyāṃścakṣuścaivāntare bhruvoḥ .\nprāṇāpānau samau kṛtvā nāsābhyantaracāriṇau', meaning: 'Shutting out external contacts, fixing the gaze between the eyebrows, and equalizing the incoming and outgoing breath within the nostrils,', inShort: 'Still the senses, steady the gaze, and balance the breath,'),
  GitaVerse(chapter: 5, verse: 28, sanskrit: 'यतेन्द्रियमनोबुद्धिर्मुनिर्मोक्षपरायणः |\nविगतेच्छाभयक्रोधो यः सदा मुक्त एव सः', transliteration: 'yatendriyamanobuddhirmunirmokṣaparāyaṇaḥ .\nvigatecchābhayakrodho yaḥ sadā mukta eva saḥ', meaning: 'the sage who has mastered the senses, mind, and intellect, intent on liberation, free from desire, fear, and anger, is forever free.', inShort: 'Master of senses and free of fear, such a sage is ever free.'),
  GitaVerse(chapter: 5, verse: 29, sanskrit: 'भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम् |\nसुहृदं सर्वभूतानां ज्ञात्वा मां शान्तिमृच्छति', transliteration: 'bhoktāraṃ yajñatapasāṃ sarvalokamaheśvaram .\nsuhṛdaṃ sarvabhūtānāṃ jñātvā māṃ śāntimṛcchati', meaning: 'Knowing Me as the enjoyer of sacrifices and austerities, the great Lord of all the worlds, and the friend of all beings, one attains peace.', inShort: 'Know Me as the Lord and friend of all, and find peace.'),
  GitaVerse(chapter: 6, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nअनाश्रितः कर्मफलं कार्यं कर्म करोति यः |\nस संन्यासी च योगी च न निरग्निर्न चाक्रियः', transliteration: 'śrībhagavānuvāca .\nanāśritaḥ karmaphalaṃ kāryaṃ karma karoti yaḥ .\nsa saṃnyāsī ca yogī ca na niragnirna cākriyaḥ', meaning: 'The Blessed Lord said: He who does the work he ought to do without depending on its fruit is a renunciate and a yogi — not he who lights no sacred fire and does no work.', inShort: 'The true renunciate acts selflessly, not by doing nothing.'),
  GitaVerse(chapter: 6, verse: 2, sanskrit: 'यं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव |\nन ह्यसंन्यस्तसङ्कल्पो योगी भवति कश्चन', transliteration: 'yaṃ saṃnyāsamiti prāhuryogaṃ taṃ viddhi pāṇḍava .\nna hyasaṃnyastasaṅkalpo yogī bhavati kaścana', meaning: 'Know that what they call renunciation is the same as yoga, O Pandava; for no one becomes a yogi without giving up selfish intention.', inShort: 'Renunciation and yoga are one: give up selfish motive.'),
  GitaVerse(chapter: 6, verse: 3, sanskrit: 'आरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते |\nयोगारूढस्य तस्यैव शमः कारणमुच्यते', transliteration: 'ārurukṣormuneryogaṃ karma kāraṇamucyate .\nyogārūḍhasya tasyaiva śamaḥ kāraṇamucyate', meaning: 'For the sage who wishes to climb to yoga, action is said to be the means; for one who has already attained it, serenity is the means.', inShort: 'Action lifts you to yoga; stillness keeps you there.'),
  GitaVerse(chapter: 6, verse: 4, sanskrit: 'यदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते |\nसर्वसङ्कल्पसंन्यासी योगारूढस्तदोच्यते', transliteration: 'yadā hi nendriyārtheṣu na karmasvanuṣajjate .\nsarvasaṅkalpasaṃnyāsī yogārūḍhastadocyate', meaning: 'When one is attached neither to sense-objects nor to actions, having given up all selfish intention, then one is said to have attained yoga.', inShort: 'When you cling to nothing, you have reached yoga.'),
  GitaVerse(chapter: 6, verse: 5, sanskrit: 'उद्धरेदात्मनात्मानं नात्मानमवसादयेत् |\nआत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः', transliteration: 'uddharedātmanātmānaṃ nātmānamavasādayet .\nātmaiva hyātmano bandhurātmaiva ripurātmanaḥ', meaning: 'Lift yourself by yourself; do not let yourself sink. For the Self alone is the friend of the self, and the Self alone is its enemy.', inShort: 'Raise yourself by yourself; you are your own friend or foe.'),
  GitaVerse(chapter: 6, verse: 6, sanskrit: 'बन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः |\nअनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत्', transliteration: 'bandhurātmātmanastasya yenātmaivātmanā jitaḥ .\nanātmanastu śatrutve vartetātmaiva śatruvat', meaning: 'The Self is a friend to one who has mastered the self; but to the unmastered, the Self behaves like an enemy.', inShort: 'Master yourself and the Self befriends you; otherwise it opposes you.'),
  GitaVerse(chapter: 6, verse: 7, sanskrit: 'जितात्मनः प्रशान्तस्य परमात्मा समाहितः |\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः', transliteration: 'jitātmanaḥ praśāntasya paramātmā samāhitaḥ .\nśītoṣṇasukhaduḥkheṣu tathā mānāpamānayoḥ', meaning: 'The Self of one who is self-controlled and at peace is steady in cold and heat, pleasure and pain, honour and dishonour.', inShort: 'The calm, controlled soul stays steady through all extremes.'),
  GitaVerse(chapter: 6, verse: 8, sanskrit: 'ज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः |\nयुक्त इत्युच्यते योगी समलोष्टाश्मकाञ्चनः', transliteration: 'jñānavijñānatṛptātmā kūṭastho vijitendriyaḥ .\nyukta ityucyate yogī samaloṣṭāśmakāñcanaḥ', meaning: 'The yogi whose mind is content with knowledge and realization, unshaken, master of the senses, to whom clay, stone, and gold are the same, is said to be established.', inShort: 'To the fulfilled yogi, gold and stone are alike.'),
  GitaVerse(chapter: 6, verse: 9, sanskrit: 'सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु |\nसाधुष्वपि च पापेषु समबुद्धिर्विशिष्यते', transliteration: 'suhṛnmitrāryudāsīnamadhyasthadveṣyabandhuṣu .\nsādhuṣvapi ca pāpeṣu samabuddhirviśiṣyate', meaning: 'He who looks with an equal mind on friends, enemies, the indifferent, the neutral, the hateful, relatives, the good, and the sinful — he excels.', inShort: 'The one who sees all people with an equal heart excels.'),
  GitaVerse(chapter: 6, verse: 10, sanskrit: 'योगी युञ्जीत सततमात्मानं रहसि स्थितः |\nएकाकी यतचित्तात्मा निराशीरपरिग्रहः', transliteration: 'yogī yuñjīta satatamātmānaṃ rahasi sthitaḥ .\nekākī yatacittātmā nirāśīraparigrahaḥ', meaning: 'Let the yogi constantly steady the mind, staying alone in a secret place, self-controlled, free from longing and possessions.', inShort: 'Withdraw, sit alone, and quiet the mind, free of wanting.'),
  GitaVerse(chapter: 6, verse: 11, sanskrit: 'शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः |\nनात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम्', transliteration: 'śucau deśe pratiṣṭhāpya sthiramāsanamātmanaḥ .\nnātyucchritaṃ nātinīcaṃ cailājinakuśottaram', meaning: 'In a clean place, establishing a firm seat, neither too high nor too low, covered with cloth, deerskin, and kusha grass,', inShort: 'Prepare a clean, steady seat for meditation,'),
  GitaVerse(chapter: 6, verse: 12, sanskrit: 'तत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः |\nउपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये', transliteration: 'tatraikāgraṃ manaḥ kṛtvā yatacittendriyakriyaḥ .\nupaviśyāsane yuñjyādyogamātmaviśuddhaye', meaning: 'there, making the mind one-pointed and controlling the activity of mind and senses, seated, let him practice yoga for self-purification.', inShort: 'There, make the mind single and practice to purify yourself.'),
  GitaVerse(chapter: 6, verse: 13, sanskrit: 'समं कायशिरोग्रीवं धारयन्नचलं स्थिरः |\nसम्प्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन्', transliteration: 'samaṃ kāyaśirogrīvaṃ dhārayannacalaṃ sthiraḥ .\nsamprekṣya nāsikāgraṃ svaṃ diśaścānavalokayan', meaning: 'Holding the body, head, and neck erect, still and steady, gazing at the tip of the nose without looking around,', inShort: 'Sit erect and still, gaze gently, unmoving,'),
  GitaVerse(chapter: 6, verse: 14, sanskrit: 'प्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः |\nमनः संयम्य मच्चित्तो युक्त आसीत मत्परः', transliteration: 'praśāntātmā vigatabhīrbrahmacārivrate sthitaḥ .\nmanaḥ saṃyamya maccitto yukta āsīta matparaḥ', meaning: 'serene and fearless, firm in the vow of self-restraint, with the mind controlled and fixed on Me, let him sit, devoted to Me as the supreme goal.', inShort: 'Calm, fearless, and devoted, rest your mind on the Divine.'),
  GitaVerse(chapter: 6, verse: 15, sanskrit: 'युञ्जन्नेवं सदात्मानं योगी नियतमानसः |\nशान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति', transliteration: 'yuñjannevaṃ sadātmānaṃ yogī niyatamānasaḥ .\nśāntiṃ nirvāṇaparamāṃ matsaṃsthāmadhigacchati', meaning: 'Ever uniting the mind in this way, the yogi of controlled mind attains the peace that culminates in liberation and abides in Me.', inShort: 'Steadily united, the yogi reaches the peace that dwells in Me.'),
  GitaVerse(chapter: 6, verse: 16, sanskrit: 'नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः |\nन चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन', transliteration: 'nātyaśnatastu yogo.asti na caikāntamanaśnataḥ .\nna cātisvapnaśīlasya jāgrato naiva cārjuna', meaning: 'Yoga is not for one who eats too much, nor for one who eats nothing at all; not for one who sleeps too much, nor for one who stays always awake, O Arjuna.', inShort: 'Yoga asks for balance, not excess or starving.'),
  GitaVerse(chapter: 6, verse: 17, sanskrit: 'युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु |\nयुक्तस्वप्नावबोधस्य योगो भवति दुःखहा', transliteration: 'yuktāhāravihārasya yuktaceṣṭasya karmasu .\nyuktasvapnāvabodhasya yogo bhavati duḥkhahā', meaning: 'For the one moderate in food and recreation, moderate in action, moderate in sleep and waking, yoga becomes the destroyer of sorrow.', inShort: 'Moderation in all things makes yoga a cure for sorrow.'),
  GitaVerse(chapter: 6, verse: 18, sanskrit: 'यदा विनियतं चित्तमात्मन्येवावतिष्ठते |\nनिःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा', transliteration: 'yadā viniyataṃ cittamātmanyevāvatiṣṭhate .\nniḥspṛhaḥ sarvakāmebhyo yukta ityucyate tadā', meaning: 'When the controlled mind rests in the Self alone, free from longing for any desire, then one is said to be united in yoga.', inShort: 'When the mind rests in the Self alone, you are in yoga.'),
  GitaVerse(chapter: 6, verse: 19, sanskrit: 'यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता |\nयोगिनो यतचित्तस्य युञ्जतो योगमात्मनः', transliteration: 'yathā dīpo nivātastho neṅgate sopamā smṛtā .\nyogino yatacittasya yuñjato yogamātmanaḥ', meaning: 'As a lamp in a windless place does not flicker — that is the image given for the yogi of controlled mind, practicing union with the Self.', inShort: 'The steady mind is like a lamp flame in still air.'),
  GitaVerse(chapter: 6, verse: 20, sanskrit: 'यत्रोपरमते चित्तं निरुद्धं योगसेवया |\nयत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति', transliteration: 'yatroparamate cittaṃ niruddhaṃ yogasevayā .\nyatra caivātmanātmānaṃ paśyannātmani tuṣyati', meaning: 'Where the mind, restrained by the practice of yoga, comes to rest, and where, seeing the Self by the Self, one is content in the Self;', inShort: 'Where the quieted mind sees the Self and rests content,'),
  GitaVerse(chapter: 6, verse: 21, sanskrit: 'सुखमात्यन्तिकं यत्तद् बुद्धिग्राह्यमतीन्द्रियम् |\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः', transliteration: 'sukhamātyantikaṃ yattad buddhigrāhyamatīndriyam .\nvetti yatra na caivāyaṃ sthitaścalati tattvataḥ', meaning: 'where one knows that boundless joy grasped by the intellect beyond the senses, and, established there, never moves from the truth;', inShort: 'there one knows a boundless joy beyond the senses,'),
  GitaVerse(chapter: 6, verse: 22, sanskrit: 'यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः |\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते', transliteration: 'yaṃ labdhvā cāparaṃ lābhaṃ manyate nādhikaṃ tataḥ .\nyasminsthito na duḥkhena guruṇāpi vicālyate', meaning: 'and gaining which one counts no other gain greater, and where, once established, one is not shaken even by heavy sorrow —', inShort: 'a gain beyond all gains, unshaken by the deepest grief —'),
  GitaVerse(chapter: 6, verse: 23, sanskrit: 'तं विद्याद् दुःखसंयोगवियोगं योगसंज्ञितम् |\nस निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा', transliteration: 'taṃ vidyād duḥkhasaṃyogaviyogaṃ yogasaṃjñitam .\nsa niścayena yoktavyo yogo.anirviṇṇacetasā', meaning: 'know that state, free from all union with pain, to be what is called yoga. This yoga should be practiced with determination and an undespairing heart.', inShort: 'That freedom from all pain is yoga; practice it resolutely.'),
  GitaVerse(chapter: 6, verse: 24, sanskrit: 'सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः |\nमनसैवेन्द्रियग्रामं विनियम्य समन्ततः', transliteration: 'saṅkalpaprabhavānkāmāṃstyaktvā sarvānaśeṣataḥ .\nmanasaivendriyagrāmaṃ viniyamya samantataḥ', meaning: 'Giving up without exception all desires born of selfish will, and restraining the senses on every side with the mind,', inShort: 'Let go of every selfish desire and rein in the senses,'),
  GitaVerse(chapter: 6, verse: 25, sanskrit: 'शनैः शनैरुपरमेद् बुद्ध्या धृतिगृहीतया |\nआत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत्', transliteration: 'śanaiḥ śanairuparamed buddhyā dhṛtigṛhītayā .\nātmasaṃsthaṃ manaḥ kṛtvā na kiñcidapi cintayet', meaning: 'let him gradually grow still, with intellect held firm; fixing the mind on the Self, let him think of nothing at all.', inShort: 'Little by little, still the mind on the Self alone.'),
  GitaVerse(chapter: 6, verse: 26, sanskrit: 'यतो यतो निश्चरति मनश्चञ्चलमस्थिरम् |\nततस्ततो नियम्यैतदात्मन्येव वशं नयेत्', transliteration: 'yato yato niścarati manaścañcalamasthiram .\ntatastato niyamyaitadātmanyeva vaśaṃ nayet', meaning: 'Wherever the restless, unsteady mind wanders, let him draw it back again and again, under the control of the Self.', inShort: 'Each time the mind strays, gently bring it back.'),
  GitaVerse(chapter: 6, verse: 27, sanskrit: 'प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम् |\nउपैति शान्तरजसं ब्रह्मभूतमकल्मषम्', transliteration: 'praśāntamanasaṃ hyenaṃ yoginaṃ sukhamuttamam .\nupaiti śāntarajasaṃ brahmabhūtamakalmaṣam', meaning: 'For supreme joy comes to the yogi whose mind is at peace, whose passion is stilled, who is faultless and has become one with Brahman.', inShort: 'To the peaceful, passionless mind comes supreme joy.'),
  GitaVerse(chapter: 6, verse: 28, sanskrit: 'युञ्जन्नेवं सदात्मानं योगी विगतकल्मषः |\nसुखेन ब्रह्मसंस्पर्शमत्यन्तं सुखमश्नुते', transliteration: 'yuñjannevaṃ sadātmānaṃ yogī vigatakalmaṣaḥ .\nsukhena brahmasaṃsparśamatyantaṃ sukhamaśnute', meaning: 'Thus ever uniting the self, the yogi, freed from impurity, easily enjoys the boundless bliss of contact with Brahman.', inShort: 'Ever united and pure, the yogi tastes limitless bliss.'),
  GitaVerse(chapter: 6, verse: 29, sanskrit: 'सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि |\nईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः', transliteration: 'sarvabhūtasthamātmānaṃ sarvabhūtāni cātmani .\nīkṣate yogayuktātmā sarvatra samadarśanaḥ', meaning: 'His self united by yoga, seeing the same everywhere, he sees the Self in all beings and all beings in the Self.', inShort: 'He sees the Self in all, and all within the Self.'),
  GitaVerse(chapter: 6, verse: 30, sanskrit: 'यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति |\nतस्याहं न प्रणश्यामि स च मे न प्रणश्यति', transliteration: 'yo māṃ paśyati sarvatra sarvaṃ ca mayi paśyati .\ntasyāhaṃ na praṇaśyāmi sa ca me na praṇaśyati', meaning: 'He who sees Me everywhere and sees all things in Me — I am never lost to him, nor is he ever lost to Me.', inShort: 'See Me in everything, and I am never lost to you.'),
  GitaVerse(chapter: 6, verse: 31, sanskrit: 'सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः |\nसर्वथा वर्तमानोऽपि स योगी मयि वर्तते', transliteration: 'sarvabhūtasthitaṃ yo māṃ bhajatyekatvamāsthitaḥ .\nsarvathā vartamāno.api sa yogī mayi vartate', meaning: 'The yogi who, established in oneness, worships Me dwelling in all beings, lives in Me, whatever his way of life.', inShort: 'Worshipping Me in all beings, he lives in Me always.'),
  GitaVerse(chapter: 6, verse: 32, sanskrit: 'आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन |\nसुखं वा यदि वा दुःखं स योगी परमो मतः', transliteration: 'ātmaupamyena sarvatra samaṃ paśyati yo.arjuna .\nsukhaṃ vā yadi vā duḥkhaṃ sa yogī paramo mataḥ', meaning: 'He who, by comparison with himself, sees the same everywhere, O Arjuna, whether in pleasure or in pain, is deemed the highest yogi.', inShort: 'The best yogi feels others\' joy and pain as his own.'),
  GitaVerse(chapter: 6, verse: 33, sanskrit: 'अर्जुन उवाच |\nयोऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन |\nएतस्याहं न पश्यामि चञ्चलत्वात्स्थितिं स्थिराम्', transliteration: 'arjuna uvāca .\nyo.ayaṃ yogastvayā proktaḥ sāmyena madhusūdana .\netasyāhaṃ na paśyāmi cañcalatvātsthitiṃ sthirām', meaning: 'Arjuna said: This yoga of equanimity you have taught, O Krishna — I do not see how it can last, because the mind is so restless.', inShort: 'Arjuna: but the mind is so restless — how can this last?'),
  GitaVerse(chapter: 6, verse: 34, sanskrit: 'चञ्चलं हि मनः कृष्ण प्रमाथि बलवद् दृढम् |\nतस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम्', transliteration: 'cañcalaṃ hi manaḥ kṛṣṇa pramāthi balavad dṛḍham .\ntasyāhaṃ nigrahaṃ manye vāyoriva suduṣkaram', meaning: 'For the mind is truly restless, O Krishna, turbulent, powerful, and stubborn; to control it seems as hard as to control the wind.', inShort: 'The mind is as hard to tame as the wind.'),
  GitaVerse(chapter: 6, verse: 35, sanskrit: 'श्रीभगवानुवाच |\nअसंशयं महाबाहो मनो दुर्निग्रहं चलम् |\nअभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते', transliteration: 'śrībhagavānuvāca .\nasaṃśayaṃ mahābāho mano durnigrahaṃ calam .\nabhyāsena tu kaunteya vairāgyeṇa ca gṛhyate', meaning: 'The Blessed Lord said: Without doubt, O mighty-armed, the mind is restless and hard to restrain; but by practice and dispassion, O son of Kunti, it can be held.', inShort: 'By practice and non-attachment, even the mind is tamed.'),
  GitaVerse(chapter: 6, verse: 36, sanskrit: 'असंयतात्मना योगो दुष्प्राप इति मे मतिः |\nवश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः', transliteration: 'asaṃyatātmanā yogo duṣprāpa iti me matiḥ .\nvaśyātmanā tu yatatā śakyo.avāptumupāyataḥ', meaning: 'Yoga is hard to attain for one whose mind is unrestrained; but for one who strives, with mind controlled, it can be reached by the right means.', inShort: 'Yoga is hard for the unruly, but reachable through effort.'),
  GitaVerse(chapter: 6, verse: 37, sanskrit: 'अर्जुन उवाच |\nअयतिः श्रद्धयोपेतो योगाच्चलितमानसः |\nअप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति', transliteration: 'arjuna uvāca .\nayatiḥ śraddhayopeto yogāccalitamānasaḥ .\naprāpya yogasaṃsiddhiṃ kāṃ gatiṃ kṛṣṇa gacchati', meaning: 'Arjuna said: He who has faith but cannot control himself, whose mind wanders from yoga, and who fails to reach perfection — what path does he take, O Krishna?', inShort: 'Arjuna: what becomes of the sincere seeker who falls short?'),
  GitaVerse(chapter: 6, verse: 38, sanskrit: 'कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति |\nअप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि', transliteration: 'kaccinnobhayavibhraṣṭaśchinnābhramiva naśyati .\napratiṣṭho mahābāho vimūḍho brahmaṇaḥ pathi', meaning: 'Fallen from both, does he not perish like a scattered cloud, O mighty-armed, without support, deluded on the path to Brahman?', inShort: 'Does he just vanish, having lost both worlds?'),
  GitaVerse(chapter: 6, verse: 39, sanskrit: 'एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः |\nत्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते', transliteration: 'etanme saṃśayaṃ kṛṣṇa chettumarhasyaśeṣataḥ .\ntvadanyaḥ saṃśayasyāsya chettā na hyupapadyate', meaning: 'This doubt of mine, O Krishna, please dispel completely; for no one but you can remove it.', inShort: 'Only you, Krishna, can clear this doubt.'),
  GitaVerse(chapter: 6, verse: 40, sanskrit: 'श्रीभगवानुवाच |\nपार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते |\nन हि कल्याणकृत्कश्चिद् दुर्गतिं तात गच्छति', transliteration: 'śrībhagavānuvāca .\npārtha naiveha nāmutra vināśastasya vidyate .\nna hi kalyāṇakṛtkaścid durgatiṃ tāta gacchati', meaning: 'The Blessed Lord said: O Partha, neither here nor hereafter is there destruction for him; for no one who does good, dear friend, ever comes to a bad end.', inShort: 'No one who does good ever comes to ruin, here or beyond.'),
  GitaVerse(chapter: 6, verse: 41, sanskrit: 'प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः |\nशुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते', transliteration: 'prāpya puṇyakṛtāṃ lokānuṣitvā śāśvatīḥ samāḥ .\nśucīnāṃ śrīmatāṃ gehe yogabhraṣṭo.abhijāyate', meaning: 'Attaining the worlds of the righteous and dwelling there for countless years, the one who fell from yoga is reborn in the home of the pure and prosperous.', inShort: 'The fallen yogi is reborn into a good and holy home.'),
  GitaVerse(chapter: 6, verse: 42, sanskrit: 'अथवा योगिनामेव कुले भवति धीमताम् |\nएतद्धि दुर्लभतरं लोके जन्म यदीदृशम्', transliteration: 'athavā yogināmeva kule bhavati dhīmatām .\netaddhi durlabhataraṃ loke janma yadīdṛśam', meaning: 'Or he is born into a family of wise yogis; but such a birth is very hard to gain in this world.', inShort: 'Or into a family of yogis — a rare and precious birth.'),
  GitaVerse(chapter: 6, verse: 43, sanskrit: 'तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम् |\nयतते च ततो भूयः संसिद्धौ कुरुनन्दन', transliteration: 'tatra taṃ buddhisaṃyogaṃ labhate paurvadehikam .\nyatate ca tato bhūyaḥ saṃsiddhau kurunandana', meaning: 'There he regains the understanding won in his former body, and strives again, O joy of the Kurus, toward perfection.', inShort: 'There he recovers his past progress and strives anew.'),
  GitaVerse(chapter: 6, verse: 44, sanskrit: 'पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः |\nजिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते', transliteration: 'pūrvābhyāsena tenaiva hriyate hyavaśo.api saḥ .\njijñāsurapi yogasya śabdabrahmātivartate', meaning: 'By that very former practice he is carried onward, even against his will; and even one who merely wishes to know of yoga goes beyond the mere words of scripture.', inShort: 'His past effort carries him forward, almost on its own.'),
  GitaVerse(chapter: 6, verse: 45, sanskrit: 'प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः |\nअनेकजन्मसंसिद्धस्ततो याति परां गतिम्', transliteration: 'prayatnādyatamānastu yogī saṃśuddhakilbiṣaḥ .\nanekajanmasaṃsiddhastato yāti parāṃ gatim', meaning: 'But the yogi, striving with sustained effort, purified of sins, and perfected over many births, then reaches the supreme goal.', inShort: 'Through steady effort over many lives, he reaches the highest.'),
  GitaVerse(chapter: 6, verse: 46, sanskrit: 'तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः |\nकर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन', transliteration: 'tapasvibhyo.adhiko yogī jñānibhyo.api mato.adhikaḥ .\nkarmibhyaścādhiko yogī tasmādyogī bhavārjuna', meaning: 'The yogi is greater than the ascetics, greater even than the learned, and greater than those devoted to ritual action. Therefore, O Arjuna, be a yogi.', inShort: 'The yogi surpasses ascetics, scholars, and ritualists — so be one.'),
  GitaVerse(chapter: 6, verse: 47, sanskrit: 'योगिनामपि सर्वेषां मद्गतेनान्तरात्मना |\nश्रद्धावान्भजते यो मां स मे युक्ततमो मतः', transliteration: 'yogināmapi sarveṣāṃ madgatenāntarātmanā .\nśraddhāvānbhajate yo māṃ sa me yuktatamo mataḥ', meaning: 'And of all yogis, the one who, full of faith, worships Me with his inner self absorbed in Me — him I hold to be the most deeply united.', inShort: 'Dearest to Me is the yogi who loves Me with all his heart.'),
  GitaVerse(chapter: 7, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nमय्यासक्तमनाः पार्थ योगं युञ्जन्मदाश्रयः |\nअसंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु', transliteration: 'śrībhagavānuvāca .\nmayyāsaktamanāḥ pārtha yogaṃ yuñjanmadāśrayaḥ .\nasaṃśayaṃ samagraṃ māṃ yathā jñāsyasi tacchṛṇu', meaning: 'The Blessed Lord said: With mind absorbed in Me, taking refuge in Me, and practicing yoga, hear how you shall know Me fully, free of all doubt, O Partha.', inShort: 'Hold your mind on Me, and you will know Me completely.'),
  GitaVerse(chapter: 7, verse: 2, sanskrit: 'ज्ञानं तेऽहं सविज्ञानमिदं वक्ष्याम्यशेषतः |\nयज्ज्ञात्वा नेह भूयोऽन्यज्ज्ञातव्यमवशिष्यते', transliteration: 'jñānaṃ te.ahaṃ savijñānamidaṃ vakṣyāmyaśeṣataḥ .\nyajjñātvā neha bhūyo.anyajjñātavyamavaśiṣyate', meaning: 'I shall teach you in full this knowledge together with realization, knowing which nothing more remains to be known here.', inShort: 'I will give you the knowledge beyond which nothing is left to know.'),
  GitaVerse(chapter: 7, verse: 3, sanskrit: 'मनुष्याणां सहस्रेषु कश्चिद्यतति सिद्धये |\nयततामपि सिद्धानां कश्चिन्मां वेत्ति तत्त्वतः', transliteration: 'manuṣyāṇāṃ sahasreṣu kaścidyatati siddhaye .\nyatatāmapi siddhānāṃ kaścinmāṃ vetti tattvataḥ', meaning: 'Among thousands, scarcely one strives for perfection; and of those who strive and succeed, scarcely one knows Me in truth.', inShort: 'Among thousands, barely one truly comes to know Me.'),
  GitaVerse(chapter: 7, verse: 4, sanskrit: 'भूमिरापोऽनलो वायुः खं मनो बुद्धिरेव च |\nअहंकार इतीयं मे भिन्ना प्रकृतिरष्टधा', transliteration: 'bhūmirāpo.analo vāyuḥ khaṃ mano buddhireva ca .\nahaṃkāra itīyaṃ me bhinnā prakṛtiraṣṭadhā', meaning: 'Earth, water, fire, air, ether, mind, intellect, and ego — this is My nature divided into eight.', inShort: 'The elements, mind, intellect, and ego are My lower nature.'),
  GitaVerse(chapter: 7, verse: 5, sanskrit: 'अपरेयमितस्त्वन्यां प्रकृतिं विद्धि मे पराम् |\nजीवभूतां महाबाहो ययेदं धार्यते जगत्', transliteration: 'apareyamitastvanyāṃ prakṛtiṃ viddhi me parām .\njīvabhūtāṃ mahābāho yayedaṃ dhāryate jagat', meaning: 'This is My lower nature. But know My other, higher nature, O mighty-armed — the life-force by which this universe is sustained.', inShort: 'Beyond that is My higher nature, the life that holds all things.'),
  GitaVerse(chapter: 7, verse: 6, sanskrit: 'एतद्योनीनि भूतानि सर्वाणीत्युपधारय |\nअहं कृत्स्नस्य जगतः प्रभवः प्रलयस्तथा', transliteration: 'etadyonīni bhūtāni sarvāṇītyupadhāraya .\nahaṃ kṛtsnasya jagataḥ prabhavaḥ pralayastathā', meaning: 'Know that all beings have their birth in these two. I am the origin of the whole universe, and also its dissolution.', inShort: 'I am the source and the end of the entire universe.'),
  GitaVerse(chapter: 7, verse: 7, sanskrit: 'मत्तः परतरं नान्यत्किञ्चिदस्ति धनञ्जय |\nमयि सर्वमिदं प्रोतं सूत्रे मणिगणा इव', transliteration: 'mattaḥ parataraṃ nānyatkiñcidasti dhanañjaya .\nmayi sarvamidaṃ protaṃ sūtre maṇigaṇā iva', meaning: 'There is nothing higher than Me, O Arjuna. All this is strung upon Me like rows of gems on a thread.', inShort: 'All things are strung on Me like pearls on a single thread.'),
  GitaVerse(chapter: 7, verse: 8, sanskrit: 'रसोऽहमप्सु कौन्तेय प्रभास्मि शशिसूर्ययोः |\nप्रणवः सर्ववेदेषु शब्दः खे पौरुषं नृषु', transliteration: 'raso.ahamapsu kaunteya prabhāsmi śaśisūryayoḥ .\npraṇavaḥ sarvavedeṣu śabdaḥ khe pauruṣaṃ nṛṣu', meaning: 'I am the taste in water, O son of Kunti, the light in the moon and the sun; I am Om in all the Vedas, the sound in space, and the strength in human beings.', inShort: 'I am the taste in water, the light in the sun, the sacred Om.'),
  GitaVerse(chapter: 7, verse: 9, sanskrit: 'पुण्यो गन्धः पृथिव्यां च तेजश्चास्मि विभावसौ |\nजीवनं सर्वभूतेषु तपश्चास्मि तपस्विषु', transliteration: 'puṇyo gandhaḥ pṛthivyāṃ ca tejaścāsmi vibhāvasau .\njīvanaṃ sarvabhūteṣu tapaścāsmi tapasviṣu', meaning: 'I am the pure fragrance in the earth and the brightness in fire; I am the life in all beings and the austerity in ascetics.', inShort: 'I am the scent of the earth, the glow of fire, the life in all.'),
  GitaVerse(chapter: 7, verse: 10, sanskrit: 'बीजं मां सर्वभूतानां विद्धि पार्थ सनातनम् |\nबुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम्', transliteration: 'bījaṃ māṃ sarvabhūtānāṃ viddhi pārtha sanātanam .\nbuddhirbuddhimatāmasmi tejastejasvināmaham', meaning: 'Know Me, O Partha, as the eternal seed of all beings; I am the intelligence of the intelligent and the splendour of the splendid.', inShort: 'I am the eternal seed of all, the wisdom of the wise.'),
  GitaVerse(chapter: 7, verse: 11, sanskrit: 'बलं बलवतां चाहं कामरागविवर्जितम् |\nधर्माविरुद्धो भूतेषु कामोऽस्मि भरतर्षभ', transliteration: 'balaṃ balavatāṃ cāhaṃ kāmarāgavivarjitam .\ndharmāviruddho bhūteṣu kāmo.asmi bharatarṣabha', meaning: 'I am the strength of the strong, free from desire and attachment; and I am desire in beings that is not contrary to righteousness, O Bharata.', inShort: 'I am strength without craving, and desire that honours dharma.'),
  GitaVerse(chapter: 7, verse: 12, sanskrit: 'ये चैव सात्त्विका भावा राजसास्तामसाश्च ये |\nमत्त एवेति तान्विद्धि न त्वहं तेषु ते मयि', transliteration: 'ye caiva sāttvikā bhāvā rājasāstāmasāśca ye .\nmatta eveti tānviddhi na tvahaṃ teṣu te mayi', meaning: 'Know that all states of being — whether harmonious, passionate, or dull — flow from Me alone; yet I am not in them, they are in Me.', inShort: 'All of nature flows from Me, yet I am not bound by it.'),
  GitaVerse(chapter: 7, verse: 13, sanskrit: 'त्रिभिर्गुणमयैर्भावैरेभिः सर्वमिदं जगत् |\nमोहितं नाभिजानाति मामेभ्यः परमव्ययम्', transliteration: 'tribhirguṇamayairbhāvairebhiḥ sarvamidaṃ jagat .\nmohitaṃ nābhijānāti māmebhyaḥ paramavyayam', meaning: 'Deluded by these three qualities of nature, the whole world fails to know Me, who am beyond them and changeless.', inShort: 'The world, fooled by nature\'s three qualities, overlooks Me.'),
  GitaVerse(chapter: 7, verse: 14, sanskrit: 'दैवी ह्येषा गुणमयी मम माया दुरत्यया |\nमामेव ये प्रपद्यन्ते मायामेतां तरन्ति ते', transliteration: 'daivī hyeṣā guṇamayī mama māyā duratyayā .\nmāmeva ye prapadyante māyāmetāṃ taranti te', meaning: 'This divine power of Mine, made of the qualities, is hard to cross over; but those who take refuge in Me alone cross beyond it.', inShort: 'My illusion is hard to cross — but surrender to Me and you cross it.'),
  GitaVerse(chapter: 7, verse: 15, sanskrit: 'न मां दुष्कृतिनो मूढाः प्रपद्यन्ते नराधमाः |\nमाययापहृतज्ञाना आसुरं भावमाश्रिताः', transliteration: 'na māṃ duṣkṛtino mūḍhāḥ prapadyante narādhamāḥ .\nmāyayāpahṛtajñānā āsuraṃ bhāvamāśritāḥ', meaning: 'The evildoers, the deluded, and the lowest of people do not take refuge in Me; their knowledge is stolen away by illusion, and they cling to a demonic nature.', inShort: 'The deluded and cruel, robbed of wisdom, do not turn to Me.'),
  GitaVerse(chapter: 7, verse: 16, sanskrit: 'चतुर्विधा भजन्ते मां जनाः सुकृतिनोऽर्जुन |\nआर्तो जिज्ञासुरर्थार्थी ज्ञानी च भरतर्षभ', transliteration: 'caturvidhā bhajante māṃ janāḥ sukṛtino.arjuna .\nārto jijñāsurarthārthī jñānī ca bharatarṣabha', meaning: 'Four kinds of virtuous people worship Me, O Arjuna: the distressed, the seeker of knowledge, the seeker of wealth, and the wise, O best of the Bharatas.', inShort: 'Four kinds turn to Me: the suffering, the curious, the needy, and the wise.'),
  GitaVerse(chapter: 7, verse: 17, sanskrit: 'तेषां ज्ञानी नित्ययुक्त एकभक्तिर्विशिष्यते |\nप्रियो हि ज्ञानिनोऽत्यर्थमहं स च मम प्रियः', transliteration: 'teṣāṃ jñānī nityayukta ekabhaktirviśiṣyate .\npriyo hi jñānino.atyarthamahaṃ sa ca mama priyaḥ', meaning: 'Of these, the wise one, ever steadfast and devoted to the One, excels; for I am dearly loved by the wise, and he is dear to Me.', inShort: 'The wise lover of God is dearest of all, and I to him.'),
  GitaVerse(chapter: 7, verse: 18, sanskrit: 'उदाराः सर्व एवैते ज्ञानी त्वात्मैव मे मतम् |\nआस्थितः स हि युक्तात्मा मामेवानुत्तमां गतिम्', transliteration: 'udārāḥ sarva evaite jñānī tvātmaiva me matam .\nāsthitaḥ sa hi yuktātmā māmevānuttamāṃ gatim', meaning: 'All these are noble, but the wise one I hold to be My very Self; for, steadfast in mind, he is fixed on Me as the supreme goal.', inShort: 'All are noble, but the wise one is My very own Self.'),
  GitaVerse(chapter: 7, verse: 19, sanskrit: 'बहूनां जन्मनामन्ते ज्ञानवान्मां प्रपद्यते |\nवासुदेवः सर्वमिति स महात्मा सुदुर्लभः', transliteration: 'bahūnāṃ janmanāmante jñānavānmāṃ prapadyate .\nvāsudevaḥ sarvamiti sa mahātmā sudurlabhaḥ', meaning: 'At the end of many births, the wise one takes refuge in Me, realizing that all this is the divine. Such a great soul is very rare.', inShort: 'After many lives, the wise see all as God — a rare, great soul.'),
  GitaVerse(chapter: 7, verse: 20, sanskrit: 'कामैस्तैस्तैर्हृतज्ञानाः प्रपद्यन्तेऽन्यदेवताः |\nतं तं नियममास्थाय प्रकृत्या नियताः स्वया', transliteration: 'kāmaistaistairhṛtajñānāḥ prapadyante.anyadevatāḥ .\ntaṃ taṃ niyamamāsthāya prakṛtyā niyatāḥ svayā', meaning: 'Those whose wisdom is carried off by this or that desire take refuge in other gods, following various rites, compelled by their own nature.', inShort: 'Driven by desire, many turn to lesser gods.'),
  GitaVerse(chapter: 7, verse: 21, sanskrit: 'यो यो यां यां तनुं भक्तः श्रद्धयार्चितुमिच्छति |\nतस्य तस्याचलां श्रद्धां तामेव विदधाम्यहम्', transliteration: 'yo yo yāṃ yāṃ tanuṃ bhaktaḥ śraddhayārcitumicchati .\ntasya tasyācalāṃ śraddhāṃ tāmeva vidadhāmyaham', meaning: 'Whatever form a devotee seeks to worship with faith, I make that faith of his steady.', inShort: 'Whatever form you worship with faith, I steady that faith.'),
  GitaVerse(chapter: 7, verse: 22, sanskrit: 'स तया श्रद्धया युक्तस्तस्याराधनमीहते |\nलभते च ततः कामान्मयैव विहितान्हि तान्', transliteration: 'sa tayā śraddhayā yuktastasyārādhanamīhate .\nlabhate ca tataḥ kāmānmayaivavihitānhi tān', meaning: 'Endowed with that faith, he worships that form and obtains from it his desires — which are, in truth, granted by Me alone.', inShort: 'Through that faith he gains his wish — really granted by Me.'),
  GitaVerse(chapter: 7, verse: 23, sanskrit: 'अन्तवत्तु फलं तेषां तद्भवत्यल्पमेधसाम् |\nदेवान्देवयजो यान्ति मद्भक्ता यान्ति मामपि', transliteration: 'antavattu phalaṃ teṣāṃ tadbhavatyalpamedhasām .\ndevāndevayajo yānti madbhaktā yānti māmapi', meaning: 'But the fruit gained by these people of small understanding is limited; the worshippers of the gods go to the gods, while My devotees come to Me.', inShort: 'Limited prayers bring limited fruit; those who seek Me reach Me.'),
  GitaVerse(chapter: 7, verse: 24, sanskrit: 'अव्यक्तं व्यक्तिमापन्नं मन्यन्ते मामबुद्धयः |\nपरं भावमजानन्तो ममाव्ययमनुत्तमम्', transliteration: 'avyaktaṃ vyaktimāpannaṃ manyante māmabuddhayaḥ .\nparaṃ bhāvamajānanto mamāvyayamanuttamam', meaning: 'The unwise think of Me, the unmanifest, as having come into manifestation, not knowing My higher nature, which is imperishable and supreme.', inShort: 'The unwise mistake the formless Me for a mere form.'),
  GitaVerse(chapter: 7, verse: 25, sanskrit: 'नाहं प्रकाशः सर्वस्य योगमायासमावृतः |\nमूढोऽयं नाभिजानाति लोको मामजमव्ययम्', transliteration: 'nāhaṃ prakāśaḥ sarvasya yogamāyāsamāvṛtaḥ .\nmūḍho.ayaṃ nābhijānāti loko māmajamavyayam', meaning: 'Veiled by My creative power, I am not revealed to all; this deluded world does not know Me, the unborn and imperishable.', inShort: 'Hidden by My power, I am unseen by the deluded world.'),
  GitaVerse(chapter: 7, verse: 26, sanskrit: 'वेदाहं समतीतानि वर्तमानानि चार्जुन |\nभविष्याणि च भूतानि मां तु वेद न कश्चन', transliteration: 'vedāhaṃ samatītāni vartamānāni cārjuna .\nbhaviṣyāṇi ca bhūtāni māṃ tu veda na kaścana', meaning: 'I know the beings of the past, the present, and those yet to come, O Arjuna; but no one knows Me.', inShort: 'I know all beings, past and future — yet none fully knows Me.'),
  GitaVerse(chapter: 7, verse: 27, sanskrit: 'इच्छाद्वेषसमुत्थेन द्वन्द्वमोहेन भारत |\nसर्वभूतानि सम्मोहं सर्गे यान्ति परन्तप', transliteration: 'icchādveṣasamutthena dvandvamohena bhārata .\nsarvabhūtāni sammohaṃ sarge yānti parantapa', meaning: 'By the delusion of the pairs of opposites, arising from desire and aversion, O Bharata, all beings in creation fall into confusion.', inShort: 'Desire and aversion cast every creature into confusion.'),
  GitaVerse(chapter: 7, verse: 28, sanskrit: 'येषां त्वन्तगतं पापं जनानां पुण्यकर्मणाम् |\nते द्वन्द्वमोहनिर्मुक्ता भजन्ते मां दृढव्रताः', transliteration: 'yeṣāṃ tvantagataṃ pāpaṃ janānāṃ puṇyakarmaṇām .\nte dvandvamohanirmuktā bhajante māṃ dṛḍhavratāḥ', meaning: 'But those of virtuous deeds, whose sin has come to an end, freed from the delusion of opposites, worship Me with firm resolve.', inShort: 'The pure, beyond the pull of opposites, worship Me steadfastly.'),
  GitaVerse(chapter: 7, verse: 29, sanskrit: 'जरामरणमोक्षाय मामाश्रित्य यतन्ति ये |\nते ब्रह्म तद्विदुः कृत्स्नमध्यात्मं कर्म चाखिलम्', transliteration: 'jarāmaraṇamokṣāya māmāśritya yatanti ye .\nte brahma tadviduḥ kṛtsnamadhyātmaṃ karma cākhilam', meaning: 'Those who strive toward liberation from old age and death, taking refuge in Me, come to know that Brahman fully, the whole Self, and all action.', inShort: 'Those who take refuge in Me come to know the whole truth.'),
  GitaVerse(chapter: 7, verse: 30, sanskrit: 'साधिभूताधिदैवं मां साधियज्ञं च ये विदुः |\nप्रयाणकालेऽपि च मां ते विदुर्युक्तचेतसः', transliteration: 'sādhibhūtādhidaivaṃ māṃ sādhiyajñaṃ ca ye viduḥ .\nprayāṇakāle.api ca māṃ te viduryuktacetasaḥ', meaning: 'Those who know Me as the One underlying all beings, all gods, and all sacrifice, know Me even at the hour of death, their minds steadfast.', inShort: 'Knowing Me as the One in all, they hold Me even at death.'),
  GitaVerse(chapter: 8, verse: 1, sanskrit: 'अर्जुन उवाच |\nकिं तद् ब्रह्म किमध्यात्मं किं कर्म पुरुषोत्तम |\nअधिभूतं च किं प्रोक्तमधिदैवं किमुच्यते', transliteration: 'arjuna uvāca .\nkiṃ tad brahma kimadhyātmaṃ kiṃ karma puruṣottama .\nadhibhūtaṃ ca kiṃ proktamadhidaivaṃ kimucyate', meaning: 'Arjuna said: What is Brahman? What is the Self within? What is action, O Supreme Person? What is said to be the realm of beings, and what is called the realm of the gods?', inShort: 'Arjuna asks Krishna to explain the great terms He has used.'),
  GitaVerse(chapter: 8, verse: 2, sanskrit: 'अधियज्ञः कथं कोऽत्र देहेऽस्मिन्मधुसूदन |\nप्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः', transliteration: 'adhiyajñaḥ kathaṃ ko.atra dehe.asminmadhusūdana .\nprayāṇakāle ca kathaṃ jñeyo.asi niyatātmabhiḥ', meaning: 'Who is the Lord of sacrifice here in this body, and how does He dwell in it, O Madhusudana? And how are You to be known at the hour of death by those who have mastered themselves?', inShort: 'And how can the disciplined know You at the moment of death?'),
  GitaVerse(chapter: 8, verse: 3, sanskrit: 'श्रीभगवानुवाच |\nअक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते |\nभूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः', transliteration: 'śrībhagavānuvāca .\nakṣaraṃ brahma paramaṃ svabhāvo.adhyātmamucyate .\nbhūtabhāvodbhavakaro visargaḥ karmasaṃjñitaḥ', meaning: 'The Blessed Lord said: The imperishable Supreme is Brahman. Its own nature dwelling in each being is called the Self. The creative force that brings beings into existence is called action.', inShort: 'Brahman is the eternal; the Self is its presence in us; action is creation.'),
  GitaVerse(chapter: 8, verse: 4, sanskrit: 'अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम् |\nअधियज्ञोऽहमेवात्र देहे देहभृतां वर', transliteration: 'adhibhūtaṃ kṣaro bhāvaḥ puruṣaścādhidaivatam .\nadhiyajño.ahamevātra dehe dehabhṛtāṃ vara', meaning: 'The perishable world of things is the realm of beings; the cosmic Person is the realm of the gods; and I Myself, dwelling here in the body, am the Lord of sacrifice, O best of the embodied.', inShort: 'Matter, the cosmic spirit, and I within the body — these are the terms.'),
  GitaVerse(chapter: 8, verse: 5, sanskrit: 'अन्तकाले च मामेव स्मरन्मुक्त्वा कलेवरम् |\nयः प्रयाति स मद्भावं याति नास्त्यत्र संशयः', transliteration: 'antakāle ca māmeva smaranmuktvā kalevaram .\nyaḥ prayāti sa madbhāvaṃ yāti nāstyatra saṃśayaḥ', meaning: 'Whoever leaves the body at the time of death remembering Me alone comes to My being. Of this there is no doubt.', inShort: 'Remember Me at death, and you come to Me.'),
  GitaVerse(chapter: 8, verse: 6, sanskrit: 'यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम् |\nतं तमेवैति कौन्तेय सदा तद्भावभावितः', transliteration: 'yaṃ yaṃ vāpi smaranbhāvaṃ tyajatyante kalevaram .\ntaṃ tamevaiti kaunteya sadā tadbhāvabhāvitaḥ', meaning: 'Whatever state of being one remembers when finally leaving the body, to that very state one goes, O son of Kunti, having always dwelt on it.', inShort: 'What you think of at the end, you become — so live with it in mind.'),
  GitaVerse(chapter: 8, verse: 7, sanskrit: 'तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च |\nमय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयः (orसंशयम्)', transliteration: 'tasmātsarveṣu kāleṣu māmanusmara yudhya ca .\nmayyarpitamanobuddhirmāmevaiṣyasyasaṃśayaḥ', meaning: 'Therefore, at all times remember Me, and fight. With mind and intellect offered to Me, you will surely come to Me.', inShort: 'Remember Me always, and do your duty.'),
  GitaVerse(chapter: 8, verse: 8, sanskrit: 'अभ्यासयोगयुक्तेन चेतसा नान्यगामिना |\nपरमं पुरुषं दिव्यं याति पार्थानुचिन्तयन्', transliteration: 'abhyāsayogayuktena cetasā nānyagāminā .\nparamaṃ puruṣaṃ divyaṃ yāti pārthānucintayan', meaning: 'With a mind trained by the yoga of practice, never wandering elsewhere, constantly meditating on the Supreme Divine Person, one reaches Him, O Partha.', inShort: 'Steady practice keeps the mind fixed on the Divine.'),
  GitaVerse(chapter: 8, verse: 9, sanskrit: 'कविं पुराणमनुशासितार-\nमणोरणीयंसमनुस्मरेद्यः |\nसर्वस्य धातारमचिन्त्यरूप-\nमादित्यवर्णं तमसः परस्तात्', transliteration: 'kaviṃ purāṇamanuśāsitāraṃ aṇoraṇīyaṃsamanusmaredyaḥ .\nsarvasya dhātāramacintyarūpaṃ ādityavarṇaṃ tamasaḥ parastāt', meaning: 'One should meditate on the all-knowing, the ancient, the ruler of all, subtler than the subtlest, the sustainer of everything, of form beyond thought, radiant as the sun, beyond all darkness.', inShort: 'Meditate on the ancient, subtle, sun-bright One beyond darkness.'),
  GitaVerse(chapter: 8, verse: 10, sanskrit: 'प्रयाणकाले मनसाऽचलेन\nभक्त्या युक्तो योगबलेन चैव |\nभ्रुवोर्मध्ये प्राणमावेश्य सम्यक्\nस तं परं पुरुषमुपैति दिव्यम्', transliteration: 'prayāṇakāle manasā.acalena bhaktyā yukto yogabalena caiva .\nbhruvormadhye prāṇamāveśya samyak sa taṃ paraṃ puruṣamupaiti divyam', meaning: 'At the time of departure, with an unmoving mind, joined in devotion and by the strength of yoga, drawing the life-breath fully between the eyebrows, one reaches that Supreme Divine Person.', inShort: 'Steady mind, devotion, and breath held between the brows lead to Him.'),
  GitaVerse(chapter: 8, verse: 11, sanskrit: 'यदक्षरं वेदविदो वदन्ति\nविशन्ति यद्यतयो वीतरागाः |\nयदिच्छन्तो ब्रह्मचर्यं चरन्ति\nतत्ते पदं संग्रहेण प्रवक्ष्ये', transliteration: 'yadakṣaraṃ vedavido vadanti viśanti yadyatayo vītarāgāḥ .\nyadicchanto brahmacaryaṃ caranti tatte padaṃ saṃgraheṇa pravakṣye', meaning: 'That which the knowers of the Veda call the Imperishable, which sages free of passion enter, and for which seekers live a life of discipline — that goal I shall now briefly describe to you.', inShort: 'Krishna will now describe the goal the sages strive for.'),
  GitaVerse(chapter: 8, verse: 12, sanskrit: 'सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च |\nमूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम्', transliteration: 'sarvadvārāṇi saṃyamya mano hṛdi nirudhya ca .\nmūrdhnyādhāyātmanaḥ prāṇamāsthito yogadhāraṇām', meaning: 'Closing all the gates of the senses, confining the mind within the heart, drawing the life-breath up into the head, established in yogic concentration —', inShort: 'Close the senses, still the mind in the heart, lift the breath.'),
  GitaVerse(chapter: 8, verse: 13, sanskrit: 'ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन् |\nयः प्रयाति त्यजन्देहं स याति परमां गतिम्', transliteration: 'omityekākṣaraṃ brahma vyāharanmāmanusmaran .\nyaḥ prayāti tyajandehaṃ sa yāti paramāṃ gatim', meaning: '— uttering Om, the single syllable that is Brahman, and remembering Me, whoever departs leaving the body attains the supreme goal.', inShort: 'Leave the body chanting Om and remembering Me — reach the highest.'),
  GitaVerse(chapter: 8, verse: 14, sanskrit: 'अनन्यचेताः सततं यो मां स्मरति नित्यशः |\nतस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः', transliteration: 'ananyacetāḥ satataṃ yo māṃ smarati nityaśaḥ .\ntasyāhaṃ sulabhaḥ pārtha nityayuktasya yoginaḥ', meaning: 'For the yogi who remembers Me constantly, every day, with a mind turned to nothing else, I am easy to reach, O Partha, for he is ever united with Me.', inShort: 'To one who always remembers Me, I am easily found.'),
  GitaVerse(chapter: 8, verse: 15, sanskrit: 'मामुपेत्य पुनर्जन्म दुःखालयमशाश्वतम् |\nनाप्नुवन्ति महात्मानः संसिद्धिं परमां गताः', transliteration: 'māmupetya punarjanma duḥkhālayamaśāśvatam .\nnāpnuvanti mahātmānaḥ saṃsiddhiṃ paramāṃ gatāḥ', meaning: 'Having come to Me, the great souls do not return to rebirth, that impermanent home of sorrow, for they have reached the highest perfection.', inShort: 'Those who reach Me are free of the sorrowful cycle of birth.'),
  GitaVerse(chapter: 8, verse: 16, sanskrit: 'आब्रह्मभुवनाल्लोकाः पुनरावर्तिनोऽर्जुन |\nमामुपेत्य तु कौन्तेय पुनर्जन्म न विद्यते', transliteration: 'ābrahmabhuvanāllokāḥ punarāvartino.arjuna .\nmāmupetya tu kaunteya punarjanma na vidyate', meaning: 'All worlds, up to the realm of Brahma, are subject to return, O Arjuna. But on reaching Me, O son of Kunti, there is no rebirth.', inShort: 'Even the highest heavens end; only in Me is there no return.'),
  GitaVerse(chapter: 8, verse: 17, sanskrit: 'सहस्रयुगपर्यन्तमहर्यद् ब्रह्मणो विदुः |\nरात्रिं युगसहस्रान्तां तेऽहोरात्रविदो जनाः', transliteration: 'sahasrayugaparyantamaharyad brahmaṇo viduḥ .\nrātriṃ yugasahasrāntāṃ te.ahorātravido janāḥ', meaning: 'Those who know that a day of Brahma lasts a thousand ages, and that his night lasts a thousand ages, truly know day and night.', inShort: 'A single day and night of Brahma spans thousands of ages.'),
  GitaVerse(chapter: 8, verse: 18, sanskrit: 'अव्यक्ताद् व्यक्तयः सर्वाः प्रभवन्त्यहरागमे |\nरात्र्यागमे प्रलीयन्ते तत्रैवाव्यक्तसंज्ञके', transliteration: 'avyaktād vyaktayaḥ sarvāḥ prabhavantyaharāgame .\nrātryāgame pralīyante tatraivāvyaktasaṃjñake', meaning: 'At the coming of that day, all manifest things arise from the unmanifest; at the coming of night, they dissolve back into that same unmanifest.', inShort: 'Creation unfolds at Brahma\'s dawn and dissolves at his night.'),
  GitaVerse(chapter: 8, verse: 19, sanskrit: 'भूतग्रामः स एवायं भूत्वा भूत्वा प्रलीयते |\nरात्र्यागमेऽवशः पार्थ प्रभवत्यहरागमे', transliteration: 'bhūtagrāmaḥ sa evāyaṃ bhūtvā bhūtvā pralīyate .\nrātryāgame.avaśaḥ pārtha prabhavatyaharāgame', meaning: 'This same multitude of beings, coming into being again and again, dissolves helplessly at the coming of night, O Partha, and arises again at the coming of day.', inShort: 'Beings arise and dissolve again and again, beyond their control.'),
  GitaVerse(chapter: 8, verse: 20, sanskrit: 'परस्तस्मात्तु भावोऽन्योऽव्यक्तोऽव्यक्तात्सनातनः |\nयः स सर्वेषु भूतेषु नश्यत्सु न विनश्यति', transliteration: 'parastasmāttu bhāvo.anyo.avyakto.avyaktātsanātanaḥ .\nyaḥ sa sarveṣu bhūteṣu naśyatsu na vinaśyati', meaning: 'But beyond this unmanifest there is another, eternal Unmanifest, which does not perish when all beings perish.', inShort: 'Beyond it all lies an eternal reality that never perishes.'),
  GitaVerse(chapter: 8, verse: 21, sanskrit: 'अव्यक्तोऽक्षर इत्युक्तस्तमाहुः परमां गतिम् |\nयं प्राप्य न निवर्तन्ते तद्धाम परमं मम', transliteration: 'avyakto.akṣara ityuktastamāhuḥ paramāṃ gatim .\nyaṃ prāpya na nivartante taddhāma paramaṃ mama', meaning: 'That Unmanifest is called the Imperishable; it is declared to be the supreme goal. Those who reach it never return. That is My supreme abode.', inShort: 'That Imperishable is My highest abode, from which none return.'),
  GitaVerse(chapter: 8, verse: 22, sanskrit: 'पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया |\nयस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम्', transliteration: 'puruṣaḥ sa paraḥ pārtha bhaktyā labhyastvananyayā .\nyasyāntaḥsthāni bhūtāni yena sarvamidaṃ tatam', meaning: 'That Supreme Person, O Partha, in whom all beings dwell and by whom all this is pervaded, is reached through single-minded devotion.', inShort: 'The One who pervades everything is reached by pure devotion.'),
  GitaVerse(chapter: 8, verse: 23, sanskrit: 'यत्र काले त्वनावृत्तिमावृत्तिं चैव योगिनः |\nप्रयाता यान्ति तं कालं वक्ष्यामि भरतर्षभ', transliteration: 'yatra kāle tvanāvṛttimāvṛttiṃ caiva yoginaḥ .\nprayātā yānti taṃ kālaṃ vakṣyāmi bharatarṣabha', meaning: 'Now I shall tell you, O best of the Bharatas, of the times at which yogis depart and do not return, and at which they depart and return.', inShort: 'Krishna speaks of the two paths of departure.'),
  GitaVerse(chapter: 8, verse: 24, sanskrit: 'अग्निर्जोतिरहः शुक्लः षण्मासा उत्तरायणम् |\nतत्र प्रयाता गच्छन्ति ब्रह्म ब्रह्मविदो जनाः', transliteration: 'agnirjotirahaḥ śuklaḥ ṣaṇmāsā uttarāyaṇam .\ntatra prayātā gacchanti brahma brahmavido janāḥ', meaning: 'Fire, light, day, the bright fortnight, the six months of the sun\'s northern course — departing then, the knowers of Brahman go to Brahman.', inShort: 'The path of light leads the knowers to Brahman.'),
  GitaVerse(chapter: 8, verse: 25, sanskrit: 'धूमो रात्रिस्तथा कृष्णः षण्मासा दक्षिणायनम् |\nतत्र चान्द्रमसं ज्योतिर्योगी प्राप्य निवर्तते', transliteration: 'dhūmo rātristathā kṛṣṇaḥ ṣaṇmāsā dakṣiṇāyanam .\ntatra cāndramasaṃ jyotiryogī prāpya nivartate', meaning: 'Smoke, night, the dark fortnight, the six months of the sun\'s southern course — departing then, the yogi reaches the lunar light and returns.', inShort: 'The path of smoke leads to the moon\'s light, and back to birth.'),
  GitaVerse(chapter: 8, verse: 26, sanskrit: 'शुक्लकृष्णे गती ह्येते जगतः शाश्वते मते |\nएकया यात्यनावृत्तिमन्ययावर्तते पुनः', transliteration: 'śuklakṛṣṇe gatī hyete jagataḥ śāśvate mate .\nekayā yātyanāvṛttimanyayāvartate punaḥ', meaning: 'These two paths, the bright and the dark, are held to be eternal in the world. By one, a person goes and does not return; by the other, one comes back again.', inShort: 'Of the two eternal paths, one frees and one returns.'),
  GitaVerse(chapter: 8, verse: 27, sanskrit: 'नैते सृती पार्थ जानन्योगी मुह्यति कश्चन |\nतस्मात्सर्वेषु कालेषु योगयुक्तो भवार्जुन', transliteration: 'naite sṛtī pārtha jānanyogī muhyati kaścana .\ntasmātsarveṣu kāleṣu yogayukto bhavārjuna', meaning: 'Knowing these two paths, O Partha, no yogi is ever deluded. Therefore, at all times, be steadfast in yoga, O Arjuna.', inShort: 'Knowing the paths, stay rooted in yoga at all times.'),
  GitaVerse(chapter: 8, verse: 28, sanskrit: 'वेदेषु यज्ञेषु तपःसु चैव\nदानेषु यत्पुण्यफलं प्रदिष्टम् |\nअत्येति तत्सर्वमिदं विदित्वा\nयोगी परं स्थानमुपैति चाद्यम्', transliteration: 'vedeṣu yajñeṣu tapaḥsu caiva dāneṣu yatpuṇyaphalaṃ pradiṣṭam .\natyeti tatsarvamidaṃ viditvā yogī paraṃ sthānamupaiti cādyam', meaning: 'Whatever merit is promised for studying the Vedas, for sacrifice, austerity, and charity, the yogi who knows this goes beyond it all and reaches the supreme, original abode.', inShort: 'This knowledge surpasses all rituals and leads to the highest.'),
  GitaVerse(chapter: 9, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nइदं तु ते गुह्यतमं प्रवक्ष्याम्यनसूयवे |\nज्ञानं विज्ञानसहितं यज्ज्ञात्वा मोक्ष्यसेऽशुभात्', transliteration: 'śrībhagavānuvāca .\nidaṃ tu te guhyatamaṃ pravakṣyāmyanasūyave .\njñānaṃ vijñānasahitaṃ yajjñātvā mokṣyase.aśubhāt', meaning: 'The Blessed Lord said: To you, who do not find fault, I shall now reveal this most secret wisdom, together with its realization. Knowing it, you will be freed from all ill.', inShort: 'Krishna offers Arjuna the deepest, most freeing wisdom.'),
  GitaVerse(chapter: 9, verse: 2, sanskrit: 'राजविद्या राजगुह्यं पवित्रमिदमुत्तमम् |\nप्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुमव्ययम्', transliteration: 'rājavidyā rājaguhyaṃ pavitramidamuttamam .\npratyakṣāvagamaṃ dharmyaṃ susukhaṃ kartumavyayam', meaning: 'This is the king of knowledge, the king of secrets, the supreme purifier. It is directly experienced, in harmony with dharma, joyful to practice, and imperishable.', inShort: 'It is the royal secret — pure, direct, joyful, and lasting.'),
  GitaVerse(chapter: 9, verse: 3, sanskrit: 'अश्रद्दधानाः पुरुषा धर्मस्यास्य परन्तप |\nअप्राप्य मां निवर्तन्ते मृत्युसंसारवर्त्मनि', transliteration: 'aśraddadhānāḥ puruṣā dharmasyāsya parantapa .\naprāpya māṃ nivartante mṛtyusaṃsāravartmani', meaning: 'Those who have no faith in this teaching, O scorcher of foes, do not reach Me and return to the path of death and rebirth.', inShort: 'Without faith, one stays caught in the cycle of birth and death.'),
  GitaVerse(chapter: 9, verse: 4, sanskrit: 'मया ततमिदं सर्वं जगदव्यक्तमूर्तिना |\nमत्स्थानि सर्वभूतानि न चाहं तेष्ववस्थितः', transliteration: 'mayā tatamidaṃ sarvaṃ jagadavyaktamūrtinā .\nmatsthāni sarvabhūtāni na cāhaṃ teṣvavasthitaḥ', meaning: 'This whole universe is pervaded by Me in My unmanifest form. All beings dwell in Me, but I do not dwell in them.', inShort: 'I pervade all things, yet am not contained by them.'),
  GitaVerse(chapter: 9, verse: 5, sanskrit: 'न च मत्स्थानि भूतानि पश्य मे योगमैश्वरम् |\nभूतभृन्न च भूतस्थो ममात्मा भूतभावनः', transliteration: 'na ca matsthāni bhūtāni paśya me yogamaiśvaram .\nbhūtabhṛnna ca bhūtastho mamātmā bhūtabhāvanaḥ', meaning: 'And yet beings do not dwell in Me — behold My divine mystery! My Self sustains all beings and brings them forth, yet does not dwell in them.', inShort: 'Behold the mystery: I hold all beings, yet stay untouched.'),
  GitaVerse(chapter: 9, verse: 6, sanskrit: 'यथाकाशस्थितो नित्यं वायुः सर्वत्रगो महान् |\nतथा सर्वाणि भूतानि मत्स्थानीत्युपधारय', transliteration: 'yathākāśasthito nityaṃ vāyuḥ sarvatrago mahān .\ntathā sarvāṇi bhūtāni matsthānītyupadhāraya', meaning: 'Just as the mighty wind, moving everywhere, always rests in space, know that in the same way all beings rest in Me.', inShort: 'As the wind moves within space, all beings move within Me.'),
  GitaVerse(chapter: 9, verse: 7, sanskrit: 'सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम् |\nकल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम्', transliteration: 'sarvabhūtāni kaunteya prakṛtiṃ yānti māmikām .\nkalpakṣaye punastāni kalpādau visṛjāmyaham', meaning: 'At the end of a cosmic cycle, O son of Kunti, all beings return to My nature; at the beginning of a new cycle, I send them forth again.', inShort: 'Beings return to Me at the end of an age and emerge again at its dawn.'),
  GitaVerse(chapter: 9, verse: 8, sanskrit: 'प्रकृतिं स्वामवष्टभ्य विसृजामि पुनः पुनः |\nभूतग्राममिमं कृत्स्नमवशं प्रकृतेर्वशात्', transliteration: 'prakṛtiṃ svāmavaṣṭabhya visṛjāmi punaḥ punaḥ .\nbhūtagrāmamimaṃ kṛtsnamavaśaṃ prakṛtervaśāt', meaning: 'Resting on My own nature, I send forth again and again this whole multitude of beings, helpless under the sway of nature.', inShort: 'Through My nature, I bring forth all beings again and again.'),
  GitaVerse(chapter: 9, verse: 9, sanskrit: 'न च मां तानि कर्माणि निबध्नन्ति धनञ्जय |\nउदासीनवदासीनमसक्तं तेषु कर्मसु', transliteration: 'na ca māṃ tāni karmāṇi nibadhnanti dhanañjaya .\nudāsīnavadāsīnamasaktaṃ teṣu karmasu', meaning: 'These actions do not bind Me, O Dhananjaya, for I sit as one indifferent, unattached to them.', inShort: 'My actions do not bind Me, for I am unattached.'),
  GitaVerse(chapter: 9, verse: 10, sanskrit: 'मयाध्यक्षेण प्रकृतिः सूयते सचराचरम् |\nहेतुनानेन कौन्तेय जगद्विपरिवर्तते', transliteration: 'mayādhyakṣeṇa prakṛtiḥ sūyate sacarācaram .\nhetunānena kaunteya jagadviparivartate', meaning: 'Under My watchful eye, nature brings forth all that moves and does not move. For this reason, O son of Kunti, the world revolves.', inShort: 'Nature creates under My gaze, and so the world turns.'),
  GitaVerse(chapter: 9, verse: 11, sanskrit: 'अवजानन्ति मां मूढा मानुषीं तनुमाश्रितम् |\nपरं भावमजानन्तो मम भूतमहेश्वरम्', transliteration: 'avajānanti māṃ mūḍhā mānuṣīṃ tanumāśritam .\nparaṃ bhāvamajānanto mama bhūtamaheśvaram', meaning: 'Fools disregard Me when I take a human form, not knowing My higher nature as the great Lord of all beings.', inShort: 'The deluded see only My human form, not the Lord within it.'),
  GitaVerse(chapter: 9, verse: 12, sanskrit: 'मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः |\nराक्षसीमासुरीं चैव प्रकृतिं मोहिनीं श्रिताः', transliteration: 'moghāśā moghakarmāṇo moghajñānā vicetasaḥ .\nrākṣasīmāsurīṃ caiva prakṛtiṃ mohinīṃ śritāḥ', meaning: 'Their hopes, actions, and knowledge are in vain; they are senseless, held by a deluding nature that is fiendish and demonic.', inShort: 'Without understanding, their hopes and efforts come to nothing.'),
  GitaVerse(chapter: 9, verse: 13, sanskrit: 'महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः |\nभजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम्', transliteration: 'mahātmānastu māṃ pārtha daivīṃ prakṛtimāśritāḥ .\nbhajantyananyamanaso jñātvā bhūtādimavyayam', meaning: 'But the great souls, O Partha, sheltered in the divine nature, worship Me with undivided minds, knowing Me as the imperishable source of all beings.', inShort: 'Great souls worship Me with whole hearts as the source of all.'),
  GitaVerse(chapter: 9, verse: 14, sanskrit: 'सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः |\nनमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते', transliteration: 'satataṃ kīrtayanto māṃ yatantaśca dṛḍhavratāḥ .\nnamasyantaśca māṃ bhaktyā nityayuktā upāsate', meaning: 'Always singing My glories, striving with firm resolve, bowing to Me in devotion, ever steadfast, they worship Me.', inShort: 'They sing of Me, strive firmly, and bow to Me with love.'),
  GitaVerse(chapter: 9, verse: 15, sanskrit: 'ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते |\nएकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम्', transliteration: 'jñānayajñena cāpyanye yajanto māmupāsate .\nekatvena pṛthaktvena bahudhā viśvatomukham', meaning: 'Others worship Me through the sacrifice of knowledge — as the One, as the many distinct, and in countless forms, as the One whose face is everywhere.', inShort: 'Others worship Me through knowledge, as one and as many.'),
  GitaVerse(chapter: 9, verse: 16, sanskrit: 'अहं क्रतुरहं यज्ञः स्वधाहमहमौषधम् |\nमन्त्रोऽहमहमेवाज्यमहमग्निरहं हुतम्', transliteration: 'ahaṃ kraturahaṃ yajñaḥ svadhāhamahamauṣadham .\nmantro.ahamahamevājyamahamagnirahaṃ hutam', meaning: 'I am the ritual, I am the sacrifice, I am the offering to the ancestors, I am the healing herb. I am the sacred chant, I am the clarified butter, I am the fire, and I am the act of offering.', inShort: 'Every part of the sacrifice is Me.'),
  GitaVerse(chapter: 9, verse: 17, sanskrit: 'पिताहमस्य जगतो माता धाता पितामहः |\nवेद्यं पवित्रमोंकार ऋक्साम यजुरेव च', transliteration: 'pitāhamasya jagato mātā dhātā pitāmahaḥ .\nvedyaṃ pavitramoṃkāra ṛksāma yajureva ca', meaning: 'I am the father of this world, its mother, its sustainer, its grandsire. I am what is to be known, the purifier, the syllable Om, and the Rig, Sama, and Yajur Vedas.', inShort: 'I am the world\'s father, mother, and the sacred Om.'),
  GitaVerse(chapter: 9, verse: 18, sanskrit: 'गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत् |\nप्रभवः प्रलयः स्थानं निधानं बीजमव्ययम्', transliteration: 'gatirbhartā prabhuḥ sākṣī nivāsaḥ śaraṇaṃ suhṛt .\nprabhavaḥ pralayaḥ sthānaṃ nidhānaṃ bījamavyayam', meaning: 'I am the goal, the support, the master, the witness, the abode, the refuge, the friend; the origin and the dissolution, the foundation, the treasure-house, and the imperishable seed.', inShort: 'I am your goal, refuge, friend, and the seed of all.'),
  GitaVerse(chapter: 9, verse: 19, sanskrit: 'तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च |\nअमृतं चैव मृत्युश्च सदसच्चाहमर्जुन', transliteration: 'tapāmyahamahaṃ varṣaṃ nigṛhṇāmyutsṛjāmi ca .\namṛtaṃ caiva mṛtyuśca sadasaccāhamarjuna', meaning: 'I give heat; I hold back and send forth the rain. I am immortality and also death; I am both what is and what is not, O Arjuna.', inShort: 'I am the heat, the rain, life and death, being and non-being.'),
  GitaVerse(chapter: 9, verse: 20, sanskrit: 'त्रैविद्या मां सोमपाः पूतपापा\nयज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते |\nते पुण्यमासाद्य सुरेन्द्रलोक-\nमश्नन्ति दिव्यान्दिवि देवभोगान्', transliteration: 'traividyā māṃ somapāḥ pūtapāpā yajñairiṣṭvā svargatiṃ prārthayante .\nte puṇyamāsādya surendralokaṃ aśnanti divyāndivi devabhogān', meaning: 'Those who follow the three Vedas, drink the soma, and are cleansed of sin worship Me with sacrifices and pray for heaven. Reaching the holy world of Indra, they enjoy the divine pleasures of the gods.', inShort: 'Ritualists who seek heaven reach it and enjoy its pleasures.'),
  GitaVerse(chapter: 9, verse: 21, sanskrit: 'ते तं भुक्त्वा स्वर्गलोकं विशालं\nक्षीणे पुण्ये मर्त्यलोकं विशन्ति |\nएवं त्रयीधर्ममनुप्रपन्ना\nगतागतं कामकामा लभन्ते', transliteration: 'te taṃ bhuktvā svargalokaṃ viśālaṃ kṣīṇe puṇye martyalokaṃ viśanti .\nevaṃ trayīdharmamanuprapannā gatāgataṃ kāmakāmā labhante', meaning: 'Having enjoyed that vast heavenly world, when their merit is spent they return to the world of mortals. Thus, following the rituals of the Vedas and desiring pleasures, they come and go.', inShort: 'When their merit runs out, they return to earth again.'),
  GitaVerse(chapter: 9, verse: 22, sanskrit: 'अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते |\nतेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम्', transliteration: 'ananyāścintayanto māṃ ye janāḥ paryupāsate .\nteṣāṃ nityābhiyuktānāṃ yogakṣemaṃ vahāmyaham', meaning: 'Those who worship Me, thinking of Me alone with no other aim, ever devoted — I carry what they lack and protect what they have.', inShort: 'To those devoted only to Me, I bring what they need and guard it.'),
  GitaVerse(chapter: 9, verse: 23, sanskrit: 'येऽप्यन्यदेवता भक्ता यजन्ते श्रद्धयान्विताः |\nतेऽपि मामेव कौन्तेय यजन्त्यविधिपूर्वकम्', transliteration: 'ye.apyanyadevatābhaktā yajante śraddhayānvitāḥ .\nte.api māmeva kaunteya yajantyavidhipūrvakam', meaning: 'Even those devoted to other gods who worship them with faith, O son of Kunti, worship Me alone, though not by the proper way.', inShort: 'Whoever is worshipped with faith, the worship reaches Me.'),
  GitaVerse(chapter: 9, verse: 24, sanskrit: 'अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च |\nन तु मामभिजानन्ति तत्त्वेनातश्च्यवन्ति ते', transliteration: 'ahaṃ hi sarvayajñānāṃ bhoktā ca prabhureva ca .\nna tu māmabhijānanti tattvenātaścyavanti te', meaning: 'For I am the enjoyer and the Lord of all sacrifices. But they do not know Me in truth, and so they fall back.', inShort: 'I receive all offerings; those who don\'t know this fall back.'),
  GitaVerse(chapter: 9, verse: 25, sanskrit: 'यान्ति देवव्रता देवान्पितॄन्यान्ति पितृव्रताः |\nभूतानि यान्ति भूतेज्या यान्ति मद्याजिनोऽपि माम्', transliteration: 'yānti devavratā devānpitṝnyānti pitṛvratāḥ .\nbhūtāni yānti bhūtejyā yānti madyājino.api mām', meaning: 'Those devoted to the gods go to the gods; those devoted to the ancestors go to the ancestors; those who worship spirits go to the spirits; and those who worship Me come to Me.', inShort: 'You reach what you worship — worship Me and come to Me.'),
  GitaVerse(chapter: 9, verse: 26, sanskrit: 'पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति |\nतदहं भक्त्युपहृतमश्नामि प्रयतात्मनः', transliteration: 'patraṃ puṣpaṃ phalaṃ toyaṃ yo me bhaktyā prayacchati .\ntadahaṃ bhaktyupahṛtamaśnāmi prayatātmanaḥ', meaning: 'Whoever offers Me with devotion a leaf, a flower, a fruit, or a little water — that offering of love from a pure heart I accept.', inShort: 'Even a leaf, a flower, or water, offered with love, I accept.'),
  GitaVerse(chapter: 9, verse: 27, sanskrit: 'यत्करोषि यदश्नासि यज्जुहोषि ददासि यत् |\nयत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम्', transliteration: 'yatkaroṣi yadaśnāsi yajjuhoṣi dadāsi yat .\nyattapasyasi kaunteya tatkuruṣva madarpaṇam', meaning: 'Whatever you do, whatever you eat, whatever you offer, whatever you give, whatever austerity you practice, O son of Kunti, do it as an offering to Me.', inShort: 'Make everything you do an offering to Me.'),
  GitaVerse(chapter: 9, verse: 28, sanskrit: 'शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः |\nसंन्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि', transliteration: 'śubhāśubhaphalairevaṃ mokṣyase karmabandhanaiḥ .\nsaṃnyāsayogayuktātmā vimukto māmupaiṣyasi', meaning: 'In this way you will be freed from the bonds of action, with their good and bad results. With your mind steadied by the yoga of renunciation, you will be liberated and come to Me.', inShort: 'Offering all to Me frees you from karma and brings you to Me.'),
  GitaVerse(chapter: 9, verse: 29, sanskrit: 'समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः |\nये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम्', transliteration: 'samo.ahaṃ sarvabhūteṣu na me dveṣyo.asti na priyaḥ .\nye bhajanti tu māṃ bhaktyā mayi te teṣu cāpyaham', meaning: 'I am the same toward all beings; to Me none is hateful and none is favored. But those who worship Me with devotion are in Me, and I am in them.', inShort: 'I am equal to all, but those who love Me live in Me, and I in them.'),
  GitaVerse(chapter: 9, verse: 30, sanskrit: 'अपि चेत्सुदुराचारो भजते मामनन्यभाक् |\nसाधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः', transliteration: 'api cetsudurācāro bhajate māmananyabhāk .\nsādhureva sa mantavyaḥ samyagvyavasito hi saḥ', meaning: 'Even if a person of very wicked conduct worships Me with undivided devotion, he should be regarded as good, for he has rightly resolved.', inShort: 'Even the worst who turns to Me fully is to be counted as good.'),
  GitaVerse(chapter: 9, verse: 31, sanskrit: 'क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति |\nकौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति', transliteration: 'kṣipraṃ bhavati dharmātmā śaśvacchāntiṃ nigacchati .\nkaunteya pratijānīhi na me bhaktaḥ praṇaśyati', meaning: 'Quickly he becomes righteous and attains lasting peace. O son of Kunti, declare it boldly: My devotee never perishes.', inShort: 'My devotee soon finds peace — declare it: they never perish.'),
  GitaVerse(chapter: 9, verse: 32, sanskrit: 'मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः |\nस्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम्', transliteration: 'māṃ hi pārtha vyapāśritya ye.api syuḥ pāpayonayaḥ .\nstriyo vaiśyāstathā śūdrāste.api yānti parāṃ gatim', meaning: 'Those who take refuge in Me, O Partha, whatever their birth — women, merchants, and laborers too — they also reach the supreme goal.', inShort: 'Whoever takes refuge in Me, whatever their birth, reaches the highest.'),
  GitaVerse(chapter: 9, verse: 33, sanskrit: 'किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा |\nअनित्यमसुखं लोकमिमं प्राप्य भजस्व माम्', transliteration: 'kiṃ punarbrāhmaṇāḥ puṇyā bhaktā rājarṣayastathā .\nanityamasukhaṃ lokamimaṃ prāpya bhajasva mām', meaning: 'How much more then the pure Brahmins and devoted royal sages! Having come into this fleeting, joyless world, worship Me.', inShort: 'This world is fleeting — so turn to Me in devotion.'),
  GitaVerse(chapter: 9, verse: 34, sanskrit: 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु |\nमामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः', transliteration: 'manmanā bhava madbhakto madyājī māṃ namaskuru .\nmāmevaiṣyasi yuktvaivamātmānaṃ matparāyaṇaḥ', meaning: 'Fix your mind on Me, be devoted to Me, worship Me, bow down to Me. Uniting yourself with Me, with Me as your supreme goal, you will surely come to Me.', inShort: 'Mind on Me, heart devoted to Me — and you will come to Me.'),
  GitaVerse(chapter: 10, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nभूय एव महाबाहो शृणु मे परमं वचः |\nयत्तेऽहं प्रीयमाणाय वक्ष्यामि हितकाम्यया', transliteration: 'śrībhagavānuvāca .\nbhūya eva mahābāho śṛṇu me paramaṃ vacaḥ .\nyatte.ahaṃ prīyamāṇāya vakṣyāmi hitakāmyayā', meaning: 'The Blessed Lord said: Hear once more, O mighty-armed, My supreme word, which I speak to you, who delight in it, out of My wish for your good.', inShort: 'Krishna speaks again for Arjuna\'s good.'),
  GitaVerse(chapter: 10, verse: 2, sanskrit: 'न मे विदुः सुरगणाः प्रभवं न महर्षयः |\nअहमादिर्हि देवानां महर्षीणां च सर्वशः', transliteration: 'na me viduḥ suragaṇāḥ prabhavaṃ na maharṣayaḥ .\nahamādirhi devānāṃ maharṣīṇāṃ ca sarvaśaḥ', meaning: 'Neither the hosts of gods nor the great sages know My origin, for in every way I am the source of the gods and the great sages.', inShort: 'Even the gods and sages do not know My origin — I am theirs.'),
  GitaVerse(chapter: 10, verse: 3, sanskrit: 'यो मामजमनादिं च वेत्ति लोकमहेश्वरम् |\nअसम्मूढः स मर्त्येषु सर्वपापैः प्रमुच्यते', transliteration: 'yo māmajamanādiṃ ca vetti lokamaheśvaram .\nasammūḍhaḥ sa martyeṣu sarvapāpaiḥ pramucyate', meaning: 'Whoever knows Me as unborn, without beginning, and the great Lord of the worlds, is free of delusion among mortals and is released from all sins.', inShort: 'Knowing Me as the unborn Lord frees one from all sin.'),
  GitaVerse(chapter: 10, verse: 4, sanskrit: 'बुद्धिर्ज्ञानमसम्मोहः क्षमा सत्यं दमः शमः |\nसुखं दुःखं भवोऽभावो भयं चाभयमेव च', transliteration: 'buddhirjñānamasammohaḥ kṣamā satyaṃ damaḥ śamaḥ .\nsukhaṃ duḥkhaṃ bhavo.abhāvo bhayaṃ cābhayameva ca', meaning: 'Intelligence, knowledge, clarity of mind, forgiveness, truth, self-control, calm, pleasure and pain, birth and death, fear and fearlessness —', inShort: 'All qualities of mind and life —'),
  GitaVerse(chapter: 10, verse: 5, sanskrit: 'अहिंसा समता तुष्टिस्तपो दानं यशोऽयशः |\nभवन्ति भावा भूतानां मत्त एव पृथग्विधाः', transliteration: 'ahiṃsā samatā tuṣṭistapo dānaṃ yaśo.ayaśaḥ .\nbhavanti bhāvā bhūtānāṃ matta eva pṛthagvidhāḥ', meaning: '— non-violence, equanimity, contentment, austerity, charity, fame and disgrace: these many states of beings arise from Me alone.', inShort: '— every state of being, good and bad, comes from Me.'),
  GitaVerse(chapter: 10, verse: 6, sanskrit: 'महर्षयः सप्त पूर्वे चत्वारो मनवस्तथा |\nमद्भावा मानसा जाता येषां लोक इमाः प्रजाः', transliteration: 'maharṣayaḥ sapta pūrve catvāro manavastathā .\nmadbhāvā mānasā jātā yeṣāṃ loka imāḥ prajāḥ', meaning: 'The seven great sages of old and the four Manus, from whom all the creatures of this world descend, were born of My mind and share My nature.', inShort: 'The ancient sages and the fathers of mankind were born of My mind.'),
  GitaVerse(chapter: 10, verse: 7, sanskrit: 'एतां विभूतिं योगं च मम यो वेत्ति तत्त्वतः |\nसोऽविकम्पेन योगेन युज्यते नात्र संशयः', transliteration: 'etāṃ vibhūtiṃ yogaṃ ca mama yo vetti tattvataḥ .\nso.avikampena yogena yujyate nātra saṃśayaḥ', meaning: 'Whoever truly knows this glory and power of Mine is united with Me in unshakable yoga. Of this there is no doubt.', inShort: 'Knowing My glory brings unshakable union with Me.'),
  GitaVerse(chapter: 10, verse: 8, sanskrit: 'अहं सर्वस्य प्रभवो मत्तः सर्वं प्रवर्तते |\nइति मत्वा भजन्ते मां बुधा भावसमन्विताः', transliteration: 'ahaṃ sarvasya prabhavo mattaḥ sarvaṃ pravartate .\niti matvā bhajante māṃ budhā bhāvasamanvitāḥ', meaning: 'I am the source of all; from Me everything proceeds. Knowing this, the wise worship Me, filled with love.', inShort: 'Knowing I am the source of all, the wise worship Me with love.'),
  GitaVerse(chapter: 10, verse: 9, sanskrit: 'मच्चित्ता मद्गतप्राणा बोधयन्तः परस्परम् |\nकथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च', transliteration: 'maccittā madgataprāṇā bodhayantaḥ parasparam .\nkathayantaśca māṃ nityaṃ tuṣyanti ca ramanti ca', meaning: 'With minds fixed on Me, their lives given to Me, enlightening one another and always speaking of Me, they are content and delight in Me.', inShort: 'My devotees speak of Me together and find joy in Me.'),
  GitaVerse(chapter: 10, verse: 10, sanskrit: 'तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम् |\nददामि बुद्धियोगं तं येन मामुपयान्ति ते', transliteration: 'teṣāṃ satatayuktānāṃ bhajatāṃ prītipūrvakam .\ndadāmi buddhiyogaṃ taṃ yena māmupayānti te', meaning: 'To those who are ever devoted and worship Me with love, I give the yoga of understanding by which they come to Me.', inShort: 'To loving devotees, I give the wisdom that leads to Me.'),
  GitaVerse(chapter: 10, verse: 11, sanskrit: 'तेषामेवानुकम्पार्थमहमज्ञानजं तमः |\nनाशयाम्यात्मभावस्थो ज्ञानदीपेन भास्वता', transliteration: 'teṣāmevānukampārthamahamajñānajaṃ tamaḥ .\nnāśayāmyātmabhāvastho jñānadīpena bhāsvatā', meaning: 'Out of compassion for them, dwelling in their hearts, I destroy the darkness born of ignorance with the shining lamp of knowledge.', inShort: 'From within their hearts, I dispel their darkness with wisdom\'s lamp.'),
  GitaVerse(chapter: 10, verse: 12, sanskrit: 'अर्जुन उवाच |\nपरं ब्रह्म परं धाम पवित्रं परमं भवान् |\nपुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम्', transliteration: 'arjuna uvāca .\nparaṃ brahma paraṃ dhāma pavitraṃ paramaṃ bhavān .\npuruṣaṃ śāśvataṃ divyamādidevamajaṃ vibhum', meaning: 'Arjuna said: You are the Supreme Brahman, the supreme abode, the supreme purifier, the eternal divine Person, the first of the gods, unborn and all-pervading.', inShort: 'Arjuna proclaims Krishna as the Supreme, eternal and unborn.'),
  GitaVerse(chapter: 10, verse: 13, sanskrit: 'आहुस्त्वामृषयः सर्वे देवर्षिर्नारदस्तथा |\nअसितो देवलो व्यासः स्वयं चैव ब्रवीषि मे', transliteration: 'āhustvāmṛṣayaḥ sarve devarṣirnāradastathā .\nasito devalo vyāsaḥ svayaṃ caiva bravīṣi me', meaning: 'All the sages declare this of You — the divine sage Narada, as well as Asita, Devala, and Vyasa — and now You Yourself tell me so.', inShort: 'The great sages say so, and now You say it Yourself.'),
  GitaVerse(chapter: 10, verse: 14, sanskrit: 'सर्वमेतदृतं मन्ये यन्मां वदसि केशव |\nन हि ते भगवन्व्यक्तिं विदुर्देवा न दानवाः', transliteration: 'sarvametadṛtaṃ manye yanmāṃ vadasi keśava .\nna hi te bhagavanvyaktiṃ vidurdevā na dānavāḥ', meaning: 'I accept as true all that You tell me, O Keshava. Truly, O Lord, neither the gods nor the demons know Your manifestation.', inShort: 'I believe You fully; neither gods nor demons know Your nature.'),
  GitaVerse(chapter: 10, verse: 15, sanskrit: 'स्वयमेवात्मनात्मानं वेत्थ त्वं पुरुषोत्तम |\nभूतभावन भूतेश देवदेव जगत्पते', transliteration: 'svayamevātmanātmānaṃ vettha tvaṃ puruṣottama .\nbhūtabhāvana bhūteśa devadeva jagatpate', meaning: 'You alone know Yourself through Yourself, O Supreme Person — source of beings, Lord of beings, God of gods, Lord of the world.', inShort: 'Only You know Yourself, O Lord of all.'),
  GitaVerse(chapter: 10, verse: 16, sanskrit: 'वक्तुमर्हस्यशेषेण दिव्या ह्यात्मविभूतयः |\nयाभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि', transliteration: 'vaktumarhasyaśeṣeṇa divyā hyātmavibhūtayaḥ .\nyābhirvibhūtibhirlokānimāṃstvaṃ vyāpya tiṣṭhasi', meaning: 'Please tell me fully of Your divine glories, by which You pervade these worlds and abide in them.', inShort: 'Tell me of the glories by which You fill the worlds.'),
  GitaVerse(chapter: 10, verse: 17, sanskrit: 'कथं विद्यामहं योगिंस्त्वां सदा परिचिन्तयन् |\nकेषु केषु च भावेषु चिन्त्योऽसि भगवन्मया', transliteration: 'kathaṃ vidyāmahaṃ yogiṃstvāṃ sadā paricintayan .\nkeṣu keṣu ca bhāveṣu cintyo.asi bhagavanmayā', meaning: 'How may I know You, O Yogi, by always meditating on You? In what forms, O Lord, should I think of You?', inShort: 'In what forms should I meditate on You?'),
  GitaVerse(chapter: 10, verse: 18, sanskrit: 'विस्तरेणात्मनो योगं विभूतिं च जनार्दन |\nभूयः कथय तृप्तिर्हि शृण्वतो नास्ति मेऽमृतम्', transliteration: 'vistareṇātmano yogaṃ vibhūtiṃ ca janārdana .\nbhūyaḥ kathaya tṛptirhi śṛṇvato nāsti me.amṛtam', meaning: 'Tell me again in detail of Your power and Your glories, O Janardana, for I am never satisfied hearing Your nectar-like words.', inShort: 'Tell me more — I never tire of Your nectar-like words.'),
  GitaVerse(chapter: 10, verse: 19, sanskrit: 'श्रीभगवानुवाच |\nहन्त ते कथयिष्यामि दिव्या ह्यात्मविभूतयः |\nप्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे', transliteration: 'śrībhagavānuvāca .\nhanta te kathayiṣyāmi divyā hyātmavibhūtayaḥ .\nprādhānyataḥ kuruśreṣṭha nāstyanto vistarasya me', meaning: 'The Blessed Lord said: Very well, I will tell you of My divine glories, but only the most prominent, O best of the Kurus, for there is no end to My extent.', inShort: 'Krishna will name His chief glories, for they are endless.'),
  GitaVerse(chapter: 10, verse: 20, sanskrit: 'अहमात्मा गुडाकेश सर्वभूताशयस्थितः |\nअहमादिश्च मध्यं च भूतानामन्त एव च', transliteration: 'ahamātmā guḍākeśa sarvabhūtāśayasthitaḥ .\nahamādiśca madhyaṃ ca bhūtānāmanta eva ca', meaning: 'I am the Self, O Gudakesha, seated in the heart of all beings. I am the beginning, the middle, and the end of all beings.', inShort: 'I am the Self in every heart, and the beginning, middle, and end.'),
  GitaVerse(chapter: 10, verse: 21, sanskrit: 'आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान् |\nमरीचिर्मरुतामस्मि नक्षत्राणामहं शशी', transliteration: 'ādityānāmahaṃ viṣṇurjyotiṣāṃ raviraṃśumān .\nmarīcirmarutāmasmi nakṣatrāṇāmahaṃ śaśī', meaning: 'Among the Adityas I am Vishnu; among lights, the radiant sun. Among the Maruts I am Marichi; among the stars, I am the moon.', inShort: 'I am Vishnu, the sun, and the moon among stars.'),
  GitaVerse(chapter: 10, verse: 22, sanskrit: 'वेदानां सामवेदोऽस्मि देवानामस्मि वासवः |\nइन्द्रियाणां मनश्चास्मि भूतानामस्मि चेतना', transliteration: 'vedānāṃ sāmavedo.asmi devānāmasmi vāsavaḥ .\nindriyāṇāṃ manaścāsmi bhūtānāmasmi cetanā', meaning: 'Among the Vedas I am the Sama Veda; among the gods I am Indra. Among the senses I am the mind; in living beings I am consciousness.', inShort: 'I am the Sama Veda, Indra, the mind, and consciousness itself.'),
  GitaVerse(chapter: 10, verse: 23, sanskrit: 'रुद्राणां शङ्करश्चास्मि वित्तेशो यक्षरक्षसाम् |\nवसूनां पावकश्चास्मि मेरुः शिखरिणामहम्', transliteration: 'rudrāṇāṃ śaṅkaraścāsmi vitteśo yakṣarakṣasām .\nvasūnāṃ pāvakaścāsmi meruḥ śikhariṇāmaham', meaning: 'Among the Rudras I am Shankara; among the Yakshas and Rakshasas, Kubera, lord of wealth. Among the Vasus I am fire; among mountains, Meru.', inShort: 'I am Shiva, Kubera, fire, and Mount Meru.'),
  GitaVerse(chapter: 10, verse: 24, sanskrit: 'पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम् |\nसेनानीनामहं स्कन्दः सरसामस्मि सागरः', transliteration: 'purodhasāṃ ca mukhyaṃ māṃ viddhi pārtha bṛhaspatim .\nsenānīnāmahaṃ skandaḥ sarasāmasmi sāgaraḥ', meaning: 'Among priests, O Partha, know Me to be the chief, Brihaspati. Among generals I am Skanda; among bodies of water, I am the ocean.', inShort: 'I am Brihaspati among priests, Skanda among generals, the ocean among waters.'),
  GitaVerse(chapter: 10, verse: 25, sanskrit: 'महर्षीणां भृगुरहं गिरामस्म्येकमक्षरम् |\nयज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः', transliteration: 'maharṣīṇāṃ bhṛgurahaṃ girāmasmyekamakṣaram .\nyajñānāṃ japayajño.asmi sthāvarāṇāṃ himālayaḥ', meaning: 'Among the great sages I am Bhrigu; among words, the single syllable Om. Among sacrifices I am the silent repetition of the divine name; among immovable things, the Himalaya.', inShort: 'I am Om among words, japa among sacrifices, the Himalaya among mountains.'),
  GitaVerse(chapter: 10, verse: 26, sanskrit: 'अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः |\nगन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः', transliteration: 'aśvatthaḥ sarvavṛkṣāṇāṃ devarṣīṇāṃ ca nāradaḥ .\ngandharvāṇāṃ citrarathaḥ siddhānāṃ kapilo muniḥ', meaning: 'Among all trees I am the sacred fig; among divine sages, Narada. Among the Gandharvas I am Chitraratha; among the perfected ones, the sage Kapila.', inShort: 'I am the sacred fig tree, Narada, and the sage Kapila.'),
  GitaVerse(chapter: 10, verse: 27, sanskrit: 'उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम् |\nऐरावतं गजेन्द्राणां नराणां च नराधिपम्', transliteration: 'uccaiḥśravasamaśvānāṃ viddhi māmamṛtodbhavam .\nairāvataṃ gajendrāṇāṃ narāṇāṃ ca narādhipam', meaning: 'Among horses know Me as Uchchaihshravas, born from the nectar of the churned ocean; among lordly elephants, Airavata; and among men, the king.', inShort: 'I am the finest horse, the noblest elephant, the king among men.'),
  GitaVerse(chapter: 10, verse: 28, sanskrit: 'आयुधानामहं वज्रं धेनूनामस्मि कामधुक् |\nप्रजनश्चास्मि कन्दर्पः सर्पाणामस्मि वासुकिः', transliteration: 'āyudhānāmahaṃ vajraṃ dhenūnāmasmi kāmadhuk .\nprajanaścāsmi kandarpaḥ sarpāṇāmasmi vāsukiḥ', meaning: 'Among weapons I am the thunderbolt; among cows, the wish-fulfilling Kamadhenu. I am Kandarpa, the god of love who brings forth life; among serpents, I am Vasuki.', inShort: 'I am the thunderbolt, the wish-granting cow, and the power of creation.'),
  GitaVerse(chapter: 10, verse: 29, sanskrit: 'अनन्तश्चास्मि नागानां वरुणो यादसामहम् |\nपितॄणामर्यमा चास्मि यमः संयमतामहम्', transliteration: 'anantaścāsmi nāgānāṃ varuṇo yādasāmaham .\npitṝṇāmaryamā cāsmi yamaḥ saṃyamatāmaham', meaning: 'Among the Nagas I am Ananta; among water beings, Varuna. Among the ancestors I am Aryaman; among those who govern, I am Yama.', inShort: 'I am Ananta, Varuna, Aryaman, and Yama the restrainer.'),
  GitaVerse(chapter: 10, verse: 30, sanskrit: 'प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम् |\nमृगाणां च मृगेन्द्रोऽहं वैनतेयश्च पक्षिणाम्', transliteration: 'prahlādaścāsmi daityānāṃ kālaḥ kalayatāmaham .\nmṛgāṇāṃ ca mṛgendro.ahaṃ vainateyaśca pakṣiṇām', meaning: 'Among the Daityas I am Prahlada; among those who reckon, I am Time. Among beasts I am the lion; among birds, Garuda.', inShort: 'I am Prahlada, Time itself, the lion, and Garuda.'),
  GitaVerse(chapter: 10, verse: 31, sanskrit: 'पवनः पवतामस्मि रामः शस्त्रभृतामहम् |\nझषाणां मकरश्चास्मि स्रोतसामस्मि जाह्नवी', transliteration: 'pavanaḥ pavatāmasmi rāmaḥ śastrabhṛtāmaham .\njhaṣāṇāṃ makaraścāsmi srotasāmasmi jāhnavī', meaning: 'Among purifiers I am the wind; among warriors, Rama. Among sea creatures I am the makara; among rivers, the Ganga.', inShort: 'I am the wind, Rama among warriors, and the Ganga among rivers.'),
  GitaVerse(chapter: 10, verse: 32, sanskrit: 'सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन |\nअध्यात्मविद्या विद्यानां वादः प्रवदतामहम्', transliteration: 'sargāṇāmādirantaśca madhyaṃ caivāhamarjuna .\nadhyātmavidyā vidyānāṃ vādaḥ pravadatāmaham', meaning: 'Of all creations I am the beginning, the end, and also the middle, O Arjuna. Among sciences I am the knowledge of the Self; among those who debate, I am the reasoning that seeks truth.', inShort: 'I am the start, middle, and end of creation, and knowledge of the Self.'),
  GitaVerse(chapter: 10, verse: 33, sanskrit: 'अक्षराणामकारोऽस्मि द्वन्द्वः सामासिकस्य च |\nअहमेवाक्षयः कालो धाताहं विश्वतोमुखः', transliteration: 'akṣarāṇāmakāro.asmi dvandvaḥ sāmāsikasya ca .\nahamevākṣayaḥ kālo dhātāhaṃ viśvatomukhaḥ', meaning: 'Among letters I am the letter A; among compounds, the joining of equals. I alone am unending Time; I am the sustainer whose face is everywhere.', inShort: 'I am the letter A, endless Time, and the sustainer of all.'),
  GitaVerse(chapter: 10, verse: 34, sanskrit: 'मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम् |\nकीर्तिः श्रीर्वाक्च नारीणां स्मृतिर्मेधा धृतिः क्षमा', transliteration: 'mṛtyuḥ sarvaharaścāhamudbhavaśca bhaviṣyatām .\nkīrtiḥ śrīrvākca nārīṇāṃ smṛtirmedhā dhṛtiḥ kṣamā', meaning: 'I am all-devouring death and the origin of all that is yet to be. Among feminine qualities I am fame, prosperity, speech, memory, intelligence, steadfastness, and forgiveness.', inShort: 'I am death and birth, and the graces of fame, memory, and patience.'),
  GitaVerse(chapter: 10, verse: 35, sanskrit: 'बृहत्साम तथा साम्नां गायत्री छन्दसामहम् |\nमासानां मार्गशीर्षोऽहमृतूनां कुसुमाकरः', transliteration: 'bṛhatsāma tathā sāmnāṃ gāyatrī chandasāmaham .\nmāsānāṃ mārgaśīrṣo.ahamṛtūnāṃ kusumākaraḥ', meaning: 'Among hymns I am the Brihat Sama; among poetic meters, the Gayatri. Among months I am Margashirsha; among seasons, flower-laden spring.', inShort: 'I am the Gayatri among meters and spring among seasons.'),
  GitaVerse(chapter: 10, verse: 36, sanskrit: 'द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम् |\nजयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम्', transliteration: 'dyūtaṃ chalayatāmasmi tejastejasvināmaham .\njayo.asmi vyavasāyo.asmi sattvaṃ sattvavatāmaham', meaning: 'Of the deceitful I am gambling; I am the splendor of the splendid. I am victory, I am resolve, I am the goodness of the good.', inShort: 'I am victory, resolve, and the goodness in the good.'),
  GitaVerse(chapter: 10, verse: 37, sanskrit: 'वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनञ्जयः |\nमुनीनामप्यहं व्यासः कवीनामुशना कविः', transliteration: 'vṛṣṇīnāṃ vāsudevo.asmi pāṇḍavānāṃ dhanañjayaḥ .\nmunīnāmapyahaṃ vyāsaḥ kavīnāmuśanā kaviḥ', meaning: 'Among the Vrishnis I am Vasudeva; among the Pandavas, Dhananjaya. Among sages I am Vyasa; among poets, the poet Ushana.', inShort: 'I am Krishna among the Vrishnis, Arjuna among the Pandavas, Vyasa among sages.'),
  GitaVerse(chapter: 10, verse: 38, sanskrit: 'दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम् |\nमौनं चैवास्मि गुह्यानां ज्ञानं ज्ञानवतामहम्', transliteration: 'daṇḍo damayatāmasmi nītirasmi jigīṣatām .\nmaunaṃ caivāsmi guhyānāṃ jñānaṃ jñānavatāmaham', meaning: 'Among punishers I am the rod of justice; among those who seek victory, I am wise policy. Among secrets I am silence; and of the wise, I am their wisdom.', inShort: 'I am justice, wise policy, silence, and the wisdom of the wise.'),
  GitaVerse(chapter: 10, verse: 39, sanskrit: 'यच्चापि सर्वभूतानां बीजं तदहमर्जुन |\nन तदस्ति विना यत्स्यान्मया भूतं चराचरम्', transliteration: 'yaccāpi sarvabhūtānāṃ bījaṃ tadahamarjuna .\nna tadasti vinā yatsyānmayā bhūtaṃ carācaram', meaning: 'Whatever is the seed of all beings, that I am, O Arjuna. There is nothing, moving or unmoving, that can exist without Me.', inShort: 'I am the seed of all; nothing exists without Me.'),
  GitaVerse(chapter: 10, verse: 40, sanskrit: 'नान्तोऽस्ति मम दिव्यानां विभूतीनां परन्तप |\nएष तूद्देशतः प्रोक्तो विभूतेर्विस्तरो मया', transliteration: 'nānto.asti mama divyānāṃ vibhūtīnāṃ parantapa .\neṣa tūddeśataḥ prokto vibhūtervistaro mayā', meaning: 'There is no end to My divine glories, O scorcher of foes. What I have told you is only a brief indication of their vastness.', inShort: 'My glories are endless; these are only a few.'),
  GitaVerse(chapter: 10, verse: 41, sanskrit: 'यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा |\nतत्तदेवावगच्छ त्वं मम तेजोंऽशसम्भवम्', transliteration: 'yadyadvibhūtimatsattvaṃ śrīmadūrjitameva vā .\ntattadevāvagaccha tvaṃ mama tejoṃśasambhavam', meaning: 'Whatever is glorious, prosperous, or mighty, know that it springs from but a spark of My splendor.', inShort: 'Wherever you see greatness, know it as a spark of Me.'),
  GitaVerse(chapter: 10, verse: 42, sanskrit: 'अथवा बहुनैतेन किं ज्ञातेन तवार्जुन |\nविष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत्', transliteration: 'athavā bahunaitena kiṃ jñātena tavārjuna .\nviṣṭabhyāhamidaṃ kṛtsnamekāṃśena sthito jagat', meaning: 'But what need is there, O Arjuna, for all this detailed knowledge? With a single fragment of Myself I pervade and support this entire universe.', inShort: 'A single fragment of Me holds up the whole universe.'),
  GitaVerse(chapter: 11, verse: 1, sanskrit: 'अर्जुन उवाच |\nमदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम् |\nयत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम', transliteration: 'arjuna uvāca .\nmadanugrahāya paramaṃ guhyamadhyātmasaṃjñitam .\nyattvayoktaṃ vacastena moho.ayaṃ vigato mama', meaning: 'Arjuna said: Out of compassion for me, You have spoken this supreme secret concerning the Self. Through Your words, my delusion is gone.', inShort: 'Arjuna\'s confusion has cleared through Krishna\'s teaching.'),
  GitaVerse(chapter: 11, verse: 2, sanskrit: 'भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया |\nत्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम्', transliteration: 'bhavāpyayau hi bhūtānāṃ śrutau vistaraśo mayā .\ntvattaḥ kamalapatrākṣa māhātmyamapi cāvyayam', meaning: 'I have heard from You in detail of the origin and dissolution of beings, O lotus-eyed one, and of Your imperishable greatness.', inShort: 'He has heard of creation, dissolution, and Krishna\'s greatness.'),
  GitaVerse(chapter: 11, verse: 3, sanskrit: 'एवमेतद्यथात्थ त्वमात्मानं परमेश्वर |\nद्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम', transliteration: 'evametadyathāttha tvamātmānaṃ parameśvara .\ndraṣṭumicchāmi te rūpamaiśvaraṃ puruṣottama', meaning: 'It is just as You have described Yourself, O Supreme Lord. Yet I long to see Your divine form, O Supreme Person.', inShort: 'Arjuna longs to see Krishna\'s divine form.'),
  GitaVerse(chapter: 11, verse: 4, sanskrit: 'मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो |\nयोगेश्वर ततो मे त्वं दर्शयात्मानमव्ययम्', transliteration: 'manyase yadi tacchakyaṃ mayā draṣṭumiti prabho .\nyogeśvara tato me tvaṃ darśayātmānamavyayam', meaning: 'If You think it possible for me to see it, O Lord, then, O Lord of yoga, show me Your imperishable Self.', inShort: 'If I am able, Lord of yoga, please show it to me.'),
  GitaVerse(chapter: 11, verse: 5, sanskrit: 'श्रीभगवानुवाच |\nपश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः |\nनानाविधानि दिव्यानि नानावर्णाकृतीनि च', transliteration: 'śrībhagavānuvāca .\npaśya me pārtha rūpāṇi śataśo.atha sahasraśaḥ .\nnānāvidhāni divyāni nānāvarṇākṛtīni ca', meaning: 'The Blessed Lord said: Behold, O Partha, My forms by the hundreds and thousands — divine, of many kinds, of many colors and shapes.', inShort: 'Krishna invites Arjuna to see His countless divine forms.'),
  GitaVerse(chapter: 11, verse: 6, sanskrit: 'पश्यादित्यान्वसून्रुद्रानश्विनौ मरुतस्तथा |\nबहून्यदृष्टपूर्वाणि पश्याश्चर्याणि भारत', transliteration: 'paśyādityānvasūnrudrānaśvinau marutastathā .\nbahūnyadṛṣṭapūrvāṇi paśyāścaryāṇi bhārata', meaning: 'Behold the Adityas, the Vasus, the Rudras, the two Ashvins, and the Maruts. Behold many wonders never seen before, O Bharata.', inShort: 'See the gods and wonders no one has seen before.'),
  GitaVerse(chapter: 11, verse: 7, sanskrit: 'इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम् |\nमम देहे गुडाकेश यच्चान्यद् द्रष्टुमिच्छसि', transliteration: 'ihaikasthaṃ jagatkṛtsnaṃ paśyādya sacarācaram .\nmama dehe guḍākeśa yaccānyad draṣṭumicchasi', meaning: 'Behold now, O Gudakesha, the entire universe, moving and unmoving, gathered as one here in My body, and whatever else you wish to see.', inShort: 'The whole universe stands in one place within My body.'),
  GitaVerse(chapter: 11, verse: 8, sanskrit: 'न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा |\nदिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम्', transliteration: 'na tu māṃ śakyase draṣṭumanenaiva svacakṣuṣā .\ndivyaṃ dadāmi te cakṣuḥ paśya me yogamaiśvaram', meaning: 'But you cannot see Me with these eyes of yours. I give you divine sight — behold My divine power.', inShort: 'Human eyes cannot see it, so I give you divine sight.'),
  GitaVerse(chapter: 11, verse: 9, sanskrit: 'सञ्जय उवाच |\nएवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः |\nदर्शयामास पार्थाय परमं रूपमैश्वरम्', transliteration: 'sañjaya uvāca .\nevamuktvā tato rājanmahāyogeśvaro hariḥ .\ndarśayāmāsa pārthāya paramaṃ rūpamaiśvaram', meaning: 'Sanjaya said: Having spoken thus, O king, Hari, the great Lord of yoga, revealed to Partha His supreme, divine form.', inShort: 'Krishna reveals His supreme form to Arjuna.'),
  GitaVerse(chapter: 11, verse: 10, sanskrit: 'अनेकवक्त्रनयनमनेकाद्भुतदर्शनम् |\nअनेकदिव्याभरणं दिव्यानेकोद्यतायुधम्', transliteration: 'anekavaktranayanamanekādbhutadarśanam .\nanekadivyābharaṇaṃ divyānekodyatāyudham', meaning: 'With countless mouths and eyes, countless wondrous sights, countless divine ornaments, and countless divine weapons raised —', inShort: 'A form of endless mouths, eyes, ornaments, and weapons —'),
  GitaVerse(chapter: 11, verse: 11, sanskrit: 'दिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम् |\nसर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम्', transliteration: 'divyamālyāmbaradharaṃ divyagandhānulepanam .\nsarvāścaryamayaṃ devamanantaṃ viśvatomukham', meaning: '— wearing divine garlands and garments, anointed with divine fragrances, all-wondrous, resplendent, infinite, facing every direction.', inShort: '— divine, wondrous, infinite, facing every way.'),
  GitaVerse(chapter: 11, verse: 12, sanskrit: 'दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता |\nयदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः', transliteration: 'divi sūryasahasrasya bhavedyugapadutthitā .\nyadi bhāḥ sadṛśī sā syādbhāsastasya mahātmanaḥ', meaning: 'If the light of a thousand suns were to blaze forth at once in the sky, it might resemble the splendor of that great Being.', inShort: 'Its radiance is like a thousand suns rising at once.'),
  GitaVerse(chapter: 11, verse: 13, sanskrit: 'तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा |\nअपश्यद्देवदेवस्य शरीरे पाण्डवस्तदा', transliteration: 'tatraikasthaṃ jagatkṛtsnaṃ pravibhaktamanekadhā .\napaśyaddevadevasya śarīre pāṇḍavastadā', meaning: 'There, in the body of the God of gods, the son of Pandu then saw the entire universe, with its many divisions, gathered together as one.', inShort: 'Arjuna sees the whole universe within Krishna\'s body.'),
  GitaVerse(chapter: 11, verse: 14, sanskrit: 'ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः |\nप्रणम्य शिरसा देवं कृताञ्जलिरभाषत', transliteration: 'tataḥ sa vismayāviṣṭo hṛṣṭaromā dhanañjayaḥ .\npraṇamya śirasā devaṃ kṛtāñjalirabhāṣata', meaning: 'Then Dhananjaya, overcome with wonder, his hair standing on end, bowed his head to the Lord and spoke with joined palms.', inShort: 'Awestruck, Arjuna bows and speaks with folded hands.'),
  GitaVerse(chapter: 11, verse: 15, sanskrit: 'अर्जुन उवाच |\nपश्यामि देवांस्तव देव देहे\nसर्वांस्तथा भूतविशेषसङ्घान् |\nब्रह्माणमीशं कमलासनस्थ-\nमृषींश्च सर्वानुरगांश्च दिव्यान्', transliteration: 'arjuna uvāca .\npaśyāmi devāṃstava deva dehe sarvāṃstathā bhūtaviśeṣasaṅghān .\nbrahmāṇamīśaṃ kamalāsanasthaṃ ṛṣīṃśca sarvānuragāṃśca divyān', meaning: 'Arjuna said: In Your body, O God, I see all the gods and the hosts of every kind of being — Brahma the Lord seated on the lotus, all the sages, and the divine serpents.', inShort: 'Arjuna sees all gods, sages, and beings in Krishna\'s body.'),
  GitaVerse(chapter: 11, verse: 16, sanskrit: 'अनेकबाहूदरवक्त्रनेत्रं\nपश्यामि त्वां सर्वतोऽनन्तरूपम् |\nनान्तं न मध्यं न पुनस्तवादिं\nपश्यामि विश्वेश्वर विश्वरूप', transliteration: 'anekabāhūdaravaktranetraṃ paśyāmi tvāṃ sarvato.anantarūpam .\nnāntaṃ na madhyaṃ na punastavādiṃ paśyāmi viśveśvara viśvarūpa', meaning: 'I see You everywhere, infinite in form, with countless arms, bellies, mouths, and eyes. I see no end, no middle, and no beginning to You, O Lord of the universe, O universal form.', inShort: 'Your form is endless — no beginning, middle, or end.'),
  GitaVerse(chapter: 11, verse: 17, sanskrit: 'किरीटिनं गदिनं चक्रिणं च\nतेजोराशिं सर्वतो दीप्तिमन्तम् |\nपश्यामि त्वां दुर्निरीक्ष्यं समन्ताद्\nदीप्तानलार्कद्युतिमप्रमेयम्', transliteration: 'kirīṭinaṃ gadinaṃ cakriṇaṃ ca tejorāśiṃ sarvato dīptimantam .\npaśyāmi tvāṃ durnirīkṣyaṃ samantād dīptānalārkadyutimaprameyam', meaning: 'I see You with crown, mace, and discus, a mass of radiance glowing on all sides, hard to look upon, blazing all around like fire and the sun, beyond measure.', inShort: 'You blaze like fire and sun, too bright to behold.'),
  GitaVerse(chapter: 11, verse: 18, sanskrit: 'त्वमक्षरं परमं वेदितव्यं\nत्वमस्य विश्वस्य परं निधानम् |\nत्वमव्ययः शाश्वतधर्मगोप्ता\nसनातनस्त्वं पुरुषो मतो मे', transliteration: 'tvamakṣaraṃ paramaṃ veditavyaṃ tvamasya viśvasya paraṃ nidhānam .\ntvamavyayaḥ śāśvatadharmagoptā sanātanastvaṃ puruṣo mato me', meaning: 'You are the Imperishable, the supreme to be known; You are the ultimate resting place of this universe. You are the unchanging guardian of eternal dharma; You are, I believe, the eternal Person.', inShort: 'You are the Imperishable, guardian of eternal dharma.'),
  GitaVerse(chapter: 11, verse: 19, sanskrit: 'अनादिमध्यान्तमनन्तवीर्य-\nमनन्तबाहुं शशिसूर्यनेत्रम् |\nपश्यामि त्वां दीप्तहुताशवक्त्रं\nस्वतेजसा विश्वमिदं तपन्तम्', transliteration: 'anādimadhyāntamanantavīryam anantabāhuṃ śaśisūryanetram .\npaśyāmi tvāṃ dīptahutāśavaktraṃ svatejasā viśvamidaṃ tapantam', meaning: 'I see You without beginning, middle, or end, of infinite power, with countless arms, the sun and moon as Your eyes, Your mouth a blazing fire, scorching this universe with Your radiance.', inShort: 'Your eyes are sun and moon; Your radiance scorches the world.'),
  GitaVerse(chapter: 11, verse: 20, sanskrit: 'द्यावापृथिव्योरिदमन्तरं हि\nव्याप्तं त्वयैकेन दिशश्च सर्वाः |\nदृष्ट्वाद्भुतं रूपमुग्रं तवेदं\nलोकत्रयं प्रव्यथितं महात्मन्', transliteration: 'dyāvāpṛthivyoridamantaraṃ hi vyāptaṃ tvayaikena diśaśca sarvāḥ .\ndṛṣṭvādbhutaṃ rūpamugraṃ tavedaṃ lokatrayaṃ pravyathitaṃ mahātman', meaning: 'The space between heaven and earth and all the directions are filled by You alone. Seeing this wondrous and terrible form of Yours, the three worlds tremble, O great-souled one.', inShort: 'You fill all space; the three worlds tremble at the sight.'),
  GitaVerse(chapter: 11, verse: 21, sanskrit: 'अमी हि त्वां सुरसङ्घा विशन्ति\nकेचिद्भीताः प्राञ्जलयो गृणन्ति |\nस्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घाः\nस्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः', transliteration: 'amī hi tvāṃ surasaṅghā viśanti kecidbhītāḥ prāñjalayo gṛṇanti .\nsvastītyuktvā maharṣisiddhasaṅghāḥ stuvanti tvāṃ stutibhiḥ puṣkalābhiḥ', meaning: 'These hosts of gods are entering You; some, in fear, praise You with joined palms. Calling out blessings of peace, the hosts of great sages and perfected ones praise You with abundant hymns.', inShort: 'Gods enter You in awe; sages sing Your praises.'),
  GitaVerse(chapter: 11, verse: 22, sanskrit: 'रुद्रादित्या वसवो ये च साध्या\nविश्वेऽश्विनौ मरुतश्चोष्मपाश्च |\nगन्धर्वयक्षासुरसिद्धसङ्घा\nवीक्षन्ते त्वां विस्मिताश्चैव सर्वे', transliteration: 'rudrādityā vasavo ye ca sādhyā viśve.aśvinau marutaścoṣmapāśca .\ngandharvayakṣāsurasiddhasaṅghā vīkṣante tvāṃ vismitāścaiva sarve', meaning: 'The Rudras, Adityas, Vasus, and Sadhyas, the Vishvadevas, the two Ashvins, the Maruts, and the ancestors, and hosts of Gandharvas, Yakshas, demons, and perfected ones all gaze upon You in amazement.', inShort: 'All the heavenly hosts gaze at You in amazement.'),
  GitaVerse(chapter: 11, verse: 23, sanskrit: 'रूपं महत्ते बहुवक्त्रनेत्रं\nमहाबाहो बहुबाहूरुपादम् |\nबहूदरं बहुदंष्ट्राकरालं\nदृष्ट्वा लोकाः प्रव्यथितास्तथाहम्', transliteration: 'rūpaṃ mahatte bahuvaktranetraṃ mahābāho bahubāhūrupādam .\nbahūdaraṃ bahudaṃṣṭrākarālaṃ dṛṣṭvā lokāḥ pravyathitāstathāham', meaning: 'Seeing Your immense form, O mighty-armed, with its many mouths and eyes, many arms, thighs, and feet, many bellies, and fearsome tusks, the worlds are terrified, and so am I.', inShort: 'Seeing Your vast, fearsome form, the worlds and I are terrified.'),
  GitaVerse(chapter: 11, verse: 24, sanskrit: 'नभःस्पृशं दीप्तमनेकवर्णं\nव्यात्ताननं दीप्तविशालनेत्रम् |\nदृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा\nधृतिं न विन्दामि शमं च विष्णो', transliteration: 'nabhaḥspṛśaṃ dīptamanekavarṇaṃ vyāttānanaṃ dīptaviśālanetram .\ndṛṣṭvā hi tvāṃ pravyathitāntarātmā dhṛtiṃ na vindāmi śamaṃ ca viṣṇo', meaning: 'Seeing You touching the sky, blazing in many colors, with mouths wide open and huge flaming eyes, my inmost self trembles, and I find neither courage nor peace, O Vishnu.', inShort: 'Seeing You touch the sky, I lose all courage and calm.'),
  GitaVerse(chapter: 11, verse: 25, sanskrit: 'दंष्ट्राकरालानि च ते मुखानि\nदृष्ट्वैव कालानलसन्निभानि |\nदिशो न जाने न लभे च शर्म\nप्रसीद देवेश जगन्निवास', transliteration: 'daṃṣṭrākarālāni ca te mukhāni dṛṣṭvaiva kālānalasannibhāni .\ndiśo na jāne na labhe ca śarma prasīda deveśa jagannivāsa', meaning: 'Seeing Your mouths, fearsome with tusks, like the fires of cosmic dissolution, I lose all sense of direction and find no peace. Be gracious, O Lord of gods, refuge of the worlds!', inShort: 'Your fiery mouths overwhelm me — be gracious, O Lord!'),
  GitaVerse(chapter: 11, verse: 26, sanskrit: 'अमी च त्वां धृतराष्ट्रस्य पुत्राः\nसर्वे सहैवावनिपालसङ्घैः |\nभीष्मो द्रोणः सूतपुत्रस्तथासौ\nसहास्मदीयैरपि योधमुख्यैः', transliteration: 'amī ca tvāṃ dhṛtarāṣṭrasya putrāḥ sarve sahaivāvanipālasaṅghaiḥ .\nbhīṣmo droṇaḥ sūtaputrastathāsau sahāsmadīyairapi yodhamukhyaiḥ', meaning: 'All these sons of Dhritarashtra, together with the hosts of kings — Bhishma, Drona, and Karna, the charioteer\'s son, along with the chief warriors on our side too —', inShort: 'All the warriors of both armies —'),
  GitaVerse(chapter: 11, verse: 27, sanskrit: 'वक्त्राणि ते त्वरमाणा विशन्ति\nदंष्ट्राकरालानि भयानकानि |\nकेचिद्विलग्ना दशनान्तरेषु\nसन्दृश्यन्ते चूर्णितैरुत्तमाङ्गैः', transliteration: 'vaktrāṇi te tvaramāṇā viśanti daṃṣṭrākarālāni bhayānakāni .\nkecidvilagnā daśanāntareṣu sandṛśyante cūrṇitairuttamāṅgaiḥ', meaning: '— are rushing into Your fearsome mouths, terrible with tusks. Some are seen caught between Your teeth, their heads crushed to powder.', inShort: '— rush into Your terrible mouths and are crushed.'),
  GitaVerse(chapter: 11, verse: 28, sanskrit: 'यथा नदीनां बहवोऽम्बुवेगाः\nसमुद्रमेवाभिमुखा द्रवन्ति |\nतथा तवामी नरलोकवीरा\nविशन्ति वक्त्राण्यभिविज्वलन्ति', transliteration: 'yathā nadīnāṃ bahavo.ambuvegāḥ samudramevābhimukhā dravanti .\ntathā tavāmī naralokavīrā viśanti vaktrāṇyabhivijvalanti', meaning: 'As the many torrents of rivers rush toward the ocean, so these heroes of the human world enter Your blazing mouths.', inShort: 'Like rivers to the sea, heroes rush into Your mouths.'),
  GitaVerse(chapter: 11, verse: 29, sanskrit: 'यथा प्रदीप्तं ज्वलनं पतङ्गा\nविशन्ति नाशाय समृद्धवेगाः |\nतथैव नाशाय विशन्ति लोकास्-\nतवापि वक्त्राणि समृद्धवेगाः', transliteration: 'yathā pradīptaṃ jvalanaṃ pataṅgā viśanti nāśāya samṛddhavegāḥ .\ntathaiva nāśāya viśanti lokās- tavāpi vaktrāṇi samṛddhavegāḥ', meaning: 'As moths rush at full speed into a blazing fire to their destruction, so these worlds rush at full speed into Your mouths to their destruction.', inShort: 'Like moths into a flame, the worlds rush to their end in You.'),
  GitaVerse(chapter: 11, verse: 30, sanskrit: 'लेलिह्यसे ग्रसमानः समन्ताल्-\nलोकान्समग्रान्वदनैर्ज्वलद्भिः |\nतेजोभिरापूर्य जगत्समग्रं\nभासस्तवोग्राः प्रतपन्ति विष्णो', transliteration: 'lelihyase grasamānaḥ samantāl- lokānsamagrānvadanairjvaladbhiḥ .\ntejobhirāpūrya jagatsamagraṃ bhāsastavogrāḥ pratapanti viṣṇo', meaning: 'Devouring all the worlds on every side with Your flaming mouths, You lick Your lips. Your fierce rays fill the whole universe with radiance and scorch it, O Vishnu.', inShort: 'You devour the worlds, and Your fierce light scorches all.'),
  GitaVerse(chapter: 11, verse: 31, sanskrit: 'आख्याहि मे को भवानुग्ररूपो\nनमोऽस्तु ते देववर प्रसीद |\nविज्ञातुमिच्छामि भवन्तमाद्यं\nन हि प्रजानामि तव प्रवृत्तिम्', transliteration: 'ākhyāhi me ko bhavānugrarūpo namo.astu te devavara prasīda .\nvijñātumicchāmi bhavantamādyaṃ na hi prajānāmi tava pravṛttim', meaning: 'Tell me who You are, so fierce in form. Salutations to You, O best of gods; be gracious! I wish to know You, the Primal One, for I do not understand what You are doing.', inShort: 'Arjuna begs to know who this fierce form is and what it intends.'),
  GitaVerse(chapter: 11, verse: 32, sanskrit: 'श्रीभगवानुवाच |\nकालोऽस्मि लोकक्षयकृत्प्रवृद्धो\nलोकान्समाहर्तुमिह प्रवृत्तः |\nऋतेऽपि त्वां न भविष्यन्ति सर्वे\nयेऽवस्थिताः प्रत्यनीकेषु योधाः', transliteration: 'śrībhagavānuvāca .\nkālo.asmi lokakṣayakṛtpravṛddho lokānsamāhartumiha pravṛttaḥ .\nṛte.api tvāṃ na bhaviṣyanti sarve ye.avasthitāḥ pratyanīkeṣu yodhāḥ', meaning: 'The Blessed Lord said: I am Time, the mighty destroyer of the worlds, come forth here to consume the worlds. Even without you, none of the warriors arrayed in the opposing armies shall survive.', inShort: 'I am Time, destroyer of worlds; these warriors will fall regardless.'),
  GitaVerse(chapter: 11, verse: 33, sanskrit: 'तस्मात्त्वमुत्तिष्ठ यशो लभस्व\nजित्वा शत्रून् भुङ्क्ष्व राज्यं समृद्धम् |\nमयैवैते निहताः पूर्वमेव\nनिमित्तमात्रं भव सव्यसाचिन्', transliteration: 'tasmāttvamuttiṣṭha yaśo labhasva jitvā śatrūn bhuṅkṣva rājyaṃ samṛddham .\nmayaivaite nihatāḥ pūrvameva nimittamātraṃ bhava savyasācin', meaning: 'Therefore arise and win glory! Conquer your enemies and enjoy a flourishing kingdom. They have already been slain by Me; be merely the instrument, O ambidextrous archer.', inShort: 'Rise and act — be only My instrument, for they are already slain.'),
  GitaVerse(chapter: 11, verse: 34, sanskrit: 'द्रोणं च भीष्मं च जयद्रथं च\nकर्णं तथान्यानपि योधवीरान् |\nमया हतांस्त्वं जहि मा व्यथिष्ठा\nयुध्यस्व जेतासि रणे सपत्नान्', transliteration: 'droṇaṃ ca bhīṣmaṃ ca jayadrathaṃ ca karṇaṃ tathānyānapi yodhavīrān .\nmayā hatāṃstvaṃ jahi mavyathiṣṭhā yudhyasva jetāsi raṇe sapatnān', meaning: 'Drona, Bhishma, Jayadratha, Karna, and the other great warriors as well have already been slain by Me — slay them. Do not be distressed. Fight, and you will conquer your rivals in battle.', inShort: 'Fight without fear; the outcome is already Mine.'),
  GitaVerse(chapter: 11, verse: 35, sanskrit: 'सञ्जय उवाच |\nएतच्छ्रुत्वा वचनं केशवस्य\nकृताञ्जलिर्वेपमानः किरीटी |\nनमस्कृत्वा भूय एवाह कृष्णं\nसगद्गदं भीतभीतः प्रणम्य', transliteration: 'sañjaya uvāca .\netacchrutvā vacanaṃ keśavasya kṛtāñjalirvepamānaḥ kirīṭī .\nnamaskṛtvā bhūya evāha kṛṣṇaṃ sagadgadaṃ bhītabhītaḥ praṇamya', meaning: 'Sanjaya said: Hearing these words of Keshava, the crowned Arjuna, trembling, with joined palms, bowed down and, overwhelmed with fear, spoke again to Krishna in a choked voice.', inShort: 'Trembling, Arjuna bows and speaks to Krishna again.'),
  GitaVerse(chapter: 11, verse: 36, sanskrit: 'अर्जुन उवाच |\nस्थाने हृषीकेश तव प्रकीर्त्या\nजगत्प्रहृष्यत्यनुरज्यते च |\nरक्षांसि भीतानि दिशो द्रवन्ति\nसर्वे नमस्यन्ति च सिद्धसङ्घाः', transliteration: 'arjuna uvāca .\nsthāne hṛṣīkeśa tava prakīrtyā jagatprahṛṣyatyanurajyate ca .\nrakṣāṃsi bhītāni diśo dravanti sarve namasyanti ca siddhasaṅghāḥ', meaning: 'Arjuna said: Rightly, O Hrishikesha, does the world rejoice and delight in Your glory. The demons flee in fear in all directions, and all the hosts of perfected ones bow to You.', inShort: 'The world rightly rejoices in You; demons flee, sages bow.'),
  GitaVerse(chapter: 11, verse: 37, sanskrit: 'कस्माच्च ते न नमेरन्महात्मन्\nगरीयसे ब्रह्मणोऽप्यादिकर्त्रे |\nअनन्त देवेश जगन्निवास\nत्वमक्षरं सदसत्तत्परं यत्', transliteration: 'kasmācca te na nameranmahātman garīyase brahmaṇo.apyādikartre .\nananta deveśa jagannivāsa tvamakṣaraṃ sadasattatparaṃ yat', meaning: 'And why should they not bow to You, O great-souled one, greater even than Brahma, the first creator? O infinite one, Lord of gods, refuge of the universe, You are the Imperishable — being and non-being, and what lies beyond them both.', inShort: 'Why would they not bow? You are beyond being and non-being.'),
  GitaVerse(chapter: 11, verse: 38, sanskrit: 'त्वमादिदेवः पुरुषः पुराणस्-\nत्वमस्य विश्वस्य परं निधानम् |\nवेत्तासि वेद्यं च परं च धाम\nत्वया ततं विश्वमनन्तरूप', transliteration: 'tvamādidevaḥ puruṣaḥ purāṇas- tvamasya viśvasya paraṃ nidhānam .\nvettāsi vedyaṃ ca paraṃ ca dhāma tvayā tataṃ viśvamanantarūpa', meaning: 'You are the primal God, the ancient Person; You are the supreme resting place of this universe. You are the knower and what is to be known, and the supreme abode. By You the universe is pervaded, O You of infinite form.', inShort: 'You are the primal God, knower and known, pervading all.'),
  GitaVerse(chapter: 11, verse: 39, sanskrit: 'वायुर्यमोऽग्निर्वरुणः शशाङ्कः\nप्रजापतिस्त्वं प्रपितामहश्च |\nनमो नमस्तेऽस्तु सहस्रकृत्वः\nपुनश्च भूयोऽपि नमो नमस्ते', transliteration: 'vāyuryamo.agnirvaruṇaḥ śaśāṅkaḥ prajāpatistvaṃ prapitāmahaśca .\nnamo namaste.astu sahasrakṛtvaḥ punaśca bhūyo.api namo namaste', meaning: 'You are Vayu, Yama, Agni, Varuna, the moon, Prajapati, and the great-grandsire of all. Salutations, salutations to You a thousand times, and again and again salutations to You!', inShort: 'You are all the gods — salutations to You a thousand times!'),
  GitaVerse(chapter: 11, verse: 40, sanskrit: 'नमः पुरस्तादथ पृष्ठतस्ते\nनमोऽस्तु ते सर्वत एव सर्व |\nअनन्तवीर्यामितविक्रमस्त्वं\nसर्वं समाप्नोषि ततोऽसि सर्वः', transliteration: 'namaḥ purastādatha pṛṣṭhataste namo.astu te sarvata eva sarva .\nanantavīryāmitavikramastvaṃ sarvaṃ samāpnoṣi tato.asi sarvaḥ', meaning: 'Salutations to You in front and behind; salutations to You on every side, O All! Infinite in power and boundless in might, You pervade everything; therefore You are everything.', inShort: 'I bow to You on every side, for You are everything.'),
  GitaVerse(chapter: 11, verse: 41, sanskrit: 'सखेति मत्वा प्रसभं यदुक्तं\nहे कृष्ण हे यादव हे सखेति |\nअजानता महिमानं तवेदं\nमया प्रमादात्प्रणयेन वापि', transliteration: 'sakheti matvā prasabhaṃ yaduktaṃ he kṛṣṇa he yādava he sakheti .\najānatā mahimānaṃ tavedaṃ mayā pramādātpraṇayena vāpi', meaning: 'Thinking of You as a friend, whatever I said rashly — "O Krishna, O Yadava, O friend" — not knowing this greatness of Yours, out of carelessness or even affection —', inShort: 'Unaware of Your greatness, I treated You as a mere friend —'),
  GitaVerse(chapter: 11, verse: 42, sanskrit: 'यच्चावहासार्थमसत्कृतोऽसि\nविहारशय्यासनभोजनेषु |\nएकोऽथवाप्यच्युत तत्समक्षं\nतत्क्षामये त्वामहमप्रमेयम्', transliteration: 'yaccāvahāsārthamasatkṛto.asi vihāraśayyāsanabhojaneṣu .\neko.athavāpyacyuta tatsamakṣaṃ tatkṣāmaye tvāmahamaprameyam', meaning: '— and whatever disrespect I showed You in jest, while playing, resting, sitting, or eating, alone or before others, O Achyuta — for all that I beg forgiveness of You, the immeasurable one.', inShort: '— forgive me for every careless word, O Achyuta.'),
  GitaVerse(chapter: 11, verse: 43, sanskrit: 'पितासि लोकस्य चराचरस्य\nत्वमस्य पूज्यश्च गुरुर्गरीयान् |\nन त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो\nलोकत्रयेऽप्यप्रतिमप्रभाव', transliteration: 'pitāsi lokasya carācarasya tvamasya pūjyaśca gururgarīyān .\nna tvatsamo.astyabhyadhikaḥ kuto.anyo lokatraye.apyapratimaprabhāva', meaning: 'You are the father of the world, of all that moves and does not move. You are its object of worship and its most venerable teacher. There is none equal to You in the three worlds — how could anyone be greater, O You of incomparable power?', inShort: 'You are the world\'s father and teacher; none is equal to You.'),
  GitaVerse(chapter: 11, verse: 44, sanskrit: 'तस्मात्प्रणम्य प्रणिधाय कायं\nप्रसादये त्वामहमीशमीड्यम् |\nपितेव पुत्रस्य सखेव सख्युः\nप्रियः प्रियायार्हसि देव सोढुम्', transliteration: 'tasmātpraṇamya praṇidhāya kāyaṃ prasādaye tvāmahamīśamīḍyam .\npiteva putrasya sakheva sakhyuḥ priyaḥ priyāyārhasi deva soḍhum', meaning: 'Therefore, bowing down and prostrating my body, I seek Your grace, O adorable Lord. As a father bears with his son, a friend with a friend, a lover with the beloved, please bear with me, O God.', inShort: 'Forgive me as a father, friend, or beloved would.'),
  GitaVerse(chapter: 11, verse: 45, sanskrit: 'अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा\nभयेन च प्रव्यथितं मनो मे |\nतदेव मे दर्शय देव रूपं\nप्रसीद देवेश जगन्निवास', transliteration: 'adṛṣṭapūrvaṃ hṛṣito.asmi dṛṣṭvā bhayena ca pravyathitaṃ mano me .\ntadeva me darśaya deva rūpaṃ prasīda deveśa jagannivāsa', meaning: 'I rejoice at having seen what was never seen before, yet my mind is shaken with fear. Show me that other form of Yours, O God. Be gracious, O Lord of gods, refuge of the universe.', inShort: 'Thrilled yet afraid, Arjuna asks to see the gentle form again.'),
  GitaVerse(chapter: 11, verse: 46, sanskrit: 'किरीटिनं गदिनं चक्रहस्तं\nइच्छामि त्वां द्रष्टुमहं तथैव |\nतेनैव रूपेण चतुर्भुजेन\nसहस्रबाहो भव विश्वमूर्ते', transliteration: 'kirīṭinaṃ gadinaṃ cakrahastaṃ icchāmi tvāṃ draṣṭumahaṃ tathaiva .\ntenaiva rūpeṇa caturbhujena sahasrabāho bhava viśvamūrte', meaning: 'I wish to see You just as before, wearing a crown, with mace and discus in hand. Take on that four-armed form, O thousand-armed one, O universal form.', inShort: 'Please return to Your four-armed form.'),
  GitaVerse(chapter: 11, verse: 47, sanskrit: 'श्रीभगवानुवाच |\nमया प्रसन्नेन तवार्जुनेदं\nरूपं परं दर्शितमात्मयोगात् |\nतेजोमयं विश्वमनन्तमाद्यं\nयन्मे त्वदन्येन न दृष्टपूर्वम्', transliteration: 'śrībhagavānuvāca .\nmayā prasannena tavārjunedaṃ rūpaṃ paraṃ darśitamātmayogāt .\ntejomayaṃ viśvamanantamādyaṃ yanme tvadanyena na dṛṣṭapūrvam', meaning: 'The Blessed Lord said: Out of grace, O Arjuna, by My own power I have shown you this supreme form — radiant, universal, infinite, and primal — which no one but you has ever seen before.', inShort: 'By My grace you have seen what no one has seen before.'),
  GitaVerse(chapter: 11, verse: 48, sanskrit: 'न वेदयज्ञाध्ययनैर्न दानैर्-\nन च क्रियाभिर्न तपोभिरुग्रैः |\nएवंरूपः शक्य अहं नृलोके\nद्रष्टुं त्वदन्येन कुरुप्रवीर', transliteration: 'na vedayajñādhyayanairna dānair- na ca kriyābhirna tapobhirugraiḥ .\nevaṃrūpaḥ śakya ahaṃ nṛloke draṣṭuṃ tvadanyena kurupravīra', meaning: 'Not by the Vedas, sacrifice, or study, not by gifts, not by rituals, nor by severe austerities can I be seen in this form in the world of men by anyone but you, O great hero of the Kurus.', inShort: 'No ritual or austerity can reveal this form.'),
  GitaVerse(chapter: 11, verse: 49, sanskrit: 'मा ते व्यथा मा च विमूढभावो\nदृष्ट्वा रूपं घोरमीदृङ्ममेदम् |\nव्यपेतभीः प्रीतमनाः पुनस्त्वं\nतदेव मे रूपमिदं प्रपश्य', transliteration: 'mā te vyathā mā ca vimūḍhabhāvo dṛṣṭvā rūpaṃ ghoramīdṛṅmamedam .\nvyapetabhīḥ prītamanāḥ punastvaṃ tadeva me rūpamidaṃ prapaśya', meaning: 'Do not be afraid or bewildered at seeing this terrible form of Mine. Free from fear and glad at heart, behold once more My familiar form.', inShort: 'Fear not — see My familiar form once more.'),
  GitaVerse(chapter: 11, verse: 50, sanskrit: 'सञ्जय उवाच |\nइत्यर्जुनं वासुदेवस्तथोक्त्वा\nस्वकं रूपं दर्शयामास भूयः |\nआश्वासयामास च भीतमेनं\nभूत्वा पुनः सौम्यवपुर्महात्मा', transliteration: 'sañjaya uvāca .\nityarjunaṃ vāsudevastathoktvā svakaṃ rūpaṃ darśayāmāsa bhūyaḥ .\nāśvāsayāmāsa ca bhītamenaṃ bhūtvā punaḥ saumyavapurmahātmā', meaning: 'Sanjaya said: Having spoken thus to Arjuna, Vasudeva showed His own form again. Taking once more His gentle form, the great-souled one consoled the frightened Arjuna.', inShort: 'Krishna returns to His gentle form and comforts Arjuna.'),
  GitaVerse(chapter: 11, verse: 51, sanskrit: 'अर्जुन उवाच |\nदृष्ट्वेदं मानुषं रूपं तव सौम्यं जनार्दन |\nइदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः', transliteration: 'arjuna uvāca .\ndṛṣṭvedaṃ mānuṣaṃ rūpaṃ tava saumyaṃ janārdana .\nidānīmasmi saṃvṛttaḥ sacetāḥ prakṛtiṃ gataḥ', meaning: 'Arjuna said: Seeing this gentle human form of Yours, O Janardana, I am now composed and restored to my own nature.', inShort: 'Seeing Krishna\'s human form, Arjuna is calm again.'),
  GitaVerse(chapter: 11, verse: 52, sanskrit: 'श्रीभगवानुवाच |\nसुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम |\nदेवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः', transliteration: 'śrībhagavānuvāca .\nsudurdarśamidaṃ rūpaṃ dṛṣṭavānasi yanmama .\ndevā apyasya rūpasya nityaṃ darśanakāṅkṣiṇaḥ', meaning: 'The Blessed Lord said: This form of Mine that you have seen is very hard to behold. Even the gods ever long to see it.', inShort: 'Even the gods long to see the form you have seen.'),
  GitaVerse(chapter: 11, verse: 53, sanskrit: 'नाहं वेदैर्न तपसा न दानेन न चेज्यया |\nशक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा', transliteration: 'nāhaṃ vedairna tapasā na dānena na cejyayā .\nśakya evaṃvidho draṣṭuṃ dṛṣṭavānasi māṃ yathā', meaning: 'Not by the Vedas, nor by austerity, nor by charity, nor by sacrifice can I be seen as you have seen Me.', inShort: 'No study, austerity, or gift can show Me as you saw Me.'),
  GitaVerse(chapter: 11, verse: 54, sanskrit: 'भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन |\nज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परन्तप', transliteration: 'bhaktyā tvananyayā śakya ahamevaṃvidho.arjuna .\njñātuṃ draṣṭuṃ ca tattvena praveṣṭuṃ ca parantapa', meaning: 'But by single-minded devotion alone, O Arjuna, can I be known in this way, seen in truth, and entered into, O scorcher of foes.', inShort: 'Only through pure devotion can I be known, seen, and reached.'),
  GitaVerse(chapter: 11, verse: 55, sanskrit: 'मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः |\nनिर्वैरः सर्वभूतेषु यः स मामेति पाण्डव', transliteration: 'matkarmakṛnmatparamo madbhaktaḥ saṅgavarjitaḥ .\nnirvairaḥ sarvabhūteṣu yaḥ sa māmeti pāṇḍava', meaning: 'Whoever works for Me, makes Me the supreme goal, is devoted to Me, free from attachment, and without enmity toward any being — that one comes to Me, O Pandava.', inShort: 'Work for Me, love Me, hate no one — and you will come to Me.'),
  GitaVerse(chapter: 12, verse: 1, sanskrit: 'अर्जुन उवाच |\nएवं सततयुक्ता ये भक्तास्त्वां पर्युपासते |\nये चाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः', transliteration: 'arjuna uvāca .\nevaṃ satatayuktā ye bhaktāstvāṃ paryupāsate .\nye cāpyakṣaramavyaktaṃ teṣāṃ ke yogavittamāḥ', meaning: 'Arjuna said: Of the devotees who, ever steadfast, worship You in this way, and those who worship the imperishable, unmanifest — which have the better knowledge of yoga?', inShort: 'Arjuna asks: is it better to worship God with form, or the formless?'),
  GitaVerse(chapter: 12, verse: 2, sanskrit: 'श्रीभगवानुवाच |\nमय्यावेश्य मनो ये मां नित्ययुक्ता उपासते |\nश्रद्धया परयोपेताः ते मे युक्ततमा मताः', transliteration: 'śrībhagavānuvāca .\nmayyāveśya mano ye māṃ nityayuktā upāsate .\nśraddhayā parayopetāḥ te me yuktatamā matāḥ', meaning: 'The Blessed Lord said: Those who fix their minds on Me and worship Me, ever steadfast and endowed with supreme faith — I consider them the most perfect in yoga.', inShort: 'Those who worship Me with faith and focus are the best in yoga.'),
  GitaVerse(chapter: 12, verse: 3, sanskrit: 'ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते |\nसर्वत्रगमचिन्त्यञ्च कूटस्थमचलन्ध्रुवम्', transliteration: 'ye tvakṣaramanirdeśyamavyaktaṃ paryupāsate .\nsarvatragamacintyañca kūṭasthamacalandhruvam', meaning: 'But those who worship the imperishable, the indefinable, the unmanifest, the all-pervading, the unthinkable, the unchanging, the immovable, the eternal —', inShort: 'Those who worship the formless, beyond all description —'),
  GitaVerse(chapter: 12, verse: 4, sanskrit: 'सन्नियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः |\nते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः', transliteration: 'sanniyamyendriyagrāmaṃ sarvatra samabuddhayaḥ .\nte prāpnuvanti māmeva sarvabhūtahite ratāḥ', meaning: '— restraining all their senses, even-minded everywhere, delighting in the welfare of all beings — they too come to Me.', inShort: '— with senses restrained and care for all, also reach Me.'),
  GitaVerse(chapter: 12, verse: 5, sanskrit: 'क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम् |\nअव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते', transliteration: 'kleśo.adhikatarasteṣāmavyaktāsaktacetasām .\navyaktā hi gatirduḥkhaṃ dehavadbhiravāpyate', meaning: 'Greater is the difficulty for those whose minds are set on the unmanifest, for the goal of the unmanifest is hard for embodied beings to reach.', inShort: 'The path of the formless is harder for those in a body.'),
  GitaVerse(chapter: 12, verse: 6, sanskrit: 'ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्परः |\nअनन्येनैव योगेन मां ध्यायन्त उपासते', transliteration: 'ye tu sarvāṇi karmāṇi mayi saṃnyasya matparaḥ .\nananyenaiva yogena māṃ dhyāyanta upāsate', meaning: 'But those who, offering all their actions to Me and regarding Me as the supreme goal, worship Me, meditating on Me with undivided devotion —', inShort: 'Those who offer all actions to Me and meditate on Me —'),
  GitaVerse(chapter: 12, verse: 7, sanskrit: 'तेषामहं समुद्धर्ता मृत्युसंसारसागरात् |\nभवामि नचिरात्पार्थ मय्यावेशितचेतसाम्', transliteration: 'teṣāmahaṃ samuddhartā mṛtyusaṃsārasāgarāt .\nbhavāmi nacirātpārtha mayyāveśitacetasām', meaning: '— for them, whose minds are fixed on Me, I soon become the deliverer from the ocean of death and rebirth, O Partha.', inShort: '— I swiftly lift them out of the ocean of birth and death.'),
  GitaVerse(chapter: 12, verse: 8, sanskrit: 'मय्येव मन आधत्स्व मयि बुद्धिं निवेशय |\nनिवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः', transliteration: 'mayyeva mana ādhatsva mayi buddhiṃ niveśaya .\nnivasiṣyasi mayyeva ata ūrdhvaṃ na saṃśayaḥ', meaning: 'Fix your mind on Me alone; let your intellect dwell in Me. Then you will live in Me alone. Of this there is no doubt.', inShort: 'Fix your mind and intellect on Me, and you will live in Me.'),
  GitaVerse(chapter: 12, verse: 9, sanskrit: 'अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम् |\nअभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय', transliteration: 'atha cittaṃ samādhātuṃ na śaknoṣi mayi sthiram .\nabhyāsayogena tato māmicchāptuṃ dhanañjaya', meaning: 'If you cannot fix your mind steadily on Me, then seek to reach Me through the yoga of practice, O Dhananjaya.', inShort: 'If you cannot focus on Me, reach Me through steady practice.'),
  GitaVerse(chapter: 12, verse: 10, sanskrit: 'अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव |\nमदर्थमपि कर्माणि कुर्वन्सिद्धिमवाप्स्यसि', transliteration: 'abhyāse.apyasamartho.asi matkarmaparamo bhava .\nmadarthamapi karmāṇi kurvansiddhimavāpsyasi', meaning: 'If you are unable even to practice, then make working for Me your supreme aim. Even by doing actions for My sake, you will attain perfection.', inShort: 'If practice is hard, work for My sake and you will succeed.'),
  GitaVerse(chapter: 12, verse: 11, sanskrit: 'अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः |\nसर्वकर्मफलत्यागं ततः कुरु यतात्मवान्', transliteration: 'athaitadapyaśakto.asi kartuṃ madyogamāśritaḥ .\nsarvakarmaphalatyāgaṃ tataḥ kuru yatātmavān', meaning: 'If you are unable to do even this, then, taking refuge in My yoga and with self-control, give up the fruits of all actions.', inShort: 'If even that is hard, let go of the fruits of your actions.'),
  GitaVerse(chapter: 12, verse: 12, sanskrit: 'श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते |\nध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्', transliteration: 'śreyo hi jñānamabhyāsājjñānāddhyānaṃ viśiṣyate .\ndhyānātkarmaphalatyāgastyāgācchāntiranantaram', meaning: 'Knowledge is better than practice; meditation is better than knowledge; renouncing the fruits of action is better than meditation, for peace immediately follows renunciation.', inShort: 'Letting go of results brings peace at once.'),
  GitaVerse(chapter: 12, verse: 13, sanskrit: 'अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च |\nनिर्ममो निरहङ्कारः समदुःखसुखः क्षमी', transliteration: 'adveṣṭā sarvabhūtānāṃ maitraḥ karuṇa eva ca .\nnirmamo nirahaṅkāraḥ samaduḥkhasukhaḥ kṣamī', meaning: 'One who hates no being, who is friendly and compassionate, free from possessiveness and ego, even-minded in pain and pleasure, and forgiving —', inShort: 'Free of hatred, kind, humble, and forgiving —'),
  GitaVerse(chapter: 12, verse: 14, sanskrit: 'सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः |\nमय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः', transliteration: 'santuṣṭaḥ satataṃ yogī yatātmā dṛḍhaniścayaḥ .\nmayyarpitamanobuddhiryo madbhaktaḥ sa me priyaḥ', meaning: '— ever content, a yogi, self-controlled, firm in resolve, with mind and intellect offered to Me — such a devotee is dear to Me.', inShort: '— content, steady, and devoted: such a one is dear to Me.'),
  GitaVerse(chapter: 12, verse: 15, sanskrit: 'यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः |\nहर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः', transliteration: 'yasmānnodvijate loko lokānnodvijate ca yaḥ .\nharṣāmarṣabhayodvegairmukto yaḥ sa ca me priyaḥ', meaning: 'One by whom the world is not disturbed and who is not disturbed by the world, who is free from elation, envy, fear, and anxiety — such a one is dear to Me.', inShort: 'Neither troubling the world nor troubled by it — dear to Me.'),
  GitaVerse(chapter: 12, verse: 16, sanskrit: 'अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः |\nसर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः', transliteration: 'anapekṣaḥ śucirdakṣa udāsīno gatavyathaḥ .\nsarvārambhaparityāgī yo madbhaktaḥ sa me priyaḥ', meaning: 'One who expects nothing, who is pure, skillful, unconcerned, and free from distress, who has given up all selfish undertakings — such a devotee is dear to Me.', inShort: 'Pure, capable, and free of selfish striving — dear to Me.'),
  GitaVerse(chapter: 12, verse: 17, sanskrit: 'यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति |\nशुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः', transliteration: 'yo na hṛṣyati na dveṣṭi na śocati na kāṅkṣati .\nśubhāśubhaparityāgī bhaktimānyaḥ sa me priyaḥ', meaning: 'One who neither rejoices nor hates, neither grieves nor craves, who has renounced both good and evil, and is full of devotion — such a one is dear to Me.', inShort: 'Beyond craving and aversion, full of devotion — dear to Me.'),
  GitaVerse(chapter: 12, verse: 18, sanskrit: 'समः शत्रौ च मित्रे च तथा मानापमानयोः |\nशीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः', transliteration: 'samaḥ śatrau ca mitre ca tathā mānāpamānayoḥ .\nśītoṣṇasukhaduḥkheṣu samaḥ saṅgavivarjitaḥ', meaning: 'One who is the same to friend and foe, in honor and dishonor, in cold and heat, in pleasure and pain, and free from attachment —', inShort: 'Equal toward friend and foe, honor and insult —'),
  GitaVerse(chapter: 12, verse: 19, sanskrit: 'तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येन केनचित् |\nअनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः', transliteration: 'tulyanindāstutirmaunī santuṣṭo yena kenacit .\naniketaḥ sthiramatirbhaktimānme priyo naraḥ', meaning: '— who is the same in blame and praise, silent, content with whatever comes, without a fixed home, steady in mind, and full of devotion — that person is dear to Me.', inShort: '— content, steady, and devoted: that person is dear to Me.'),
  GitaVerse(chapter: 12, verse: 20, sanskrit: 'ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते |\nश्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः', transliteration: 'ye tu dharmyāmṛtamidaṃ yathoktaṃ paryupāsate .\nśraddadhānā matparamā bhaktāste.atīva me priyāḥ', meaning: 'But those who, with faith and holding Me as the supreme goal, follow this immortal dharma as I have taught it — such devotees are exceedingly dear to Me.', inShort: 'Those who live this teaching with faith are dearest to Me.'),
  GitaVerse(chapter: 13, verse: 1, sanskrit: 'अर्जुन उवाच |\nप्रकृतिं पुरुषं चैव क्षेत्रं क्षेत्रज्ञमेव च |\nएतद्वेदितुमिच्छामि ज्ञानं ज्ञेयं च केशव', transliteration: 'arjuna uvāca .\nprakṛtiṃ puruṣaṃ caiva kṣetraṃ kṣetrajñameva ca .\netadveditumicchāmi jñānaṃ jñeyaṃ ca keśava', meaning: 'Arjuna said: Nature and spirit, the field and the knower of the field, knowledge and what is to be known — these I wish to understand, O Keshava.', inShort: 'Arjuna asks about nature, spirit, the field, and its knower.'),
  GitaVerse(chapter: 13, verse: 2, sanskrit: 'श्रीभगवानुवाच |\nइदं शरीरं कौन्तेय क्षेत्रमित्यभिधीयते |\nएतद्यो वेत्ति तं प्राहुः क्षेत्रज्ञ इति तद्विदः', transliteration: 'śrībhagavānuvāca .\nidaṃ śarīraṃ kaunteya kṣetramityabhidhīyate .\netadyo vetti taṃ prāhuḥ kṣetrajña iti tadvidaḥ', meaning: 'The Blessed Lord said: This body, O son of Kunti, is called the field. The one who knows it is called the knower of the field by those who know the truth of these things.', inShort: 'The body is the field; the one who knows it is its knower.'),
  GitaVerse(chapter: 13, verse: 3, sanskrit: 'क्षेत्रज्ञं चापि मां विद्धि सर्वक्षेत्रेषु भारत |\nक्षेत्रक्षेत्रज्ञयोर्ज्ञानं यत्तज्ज्ञानं मतं मम', transliteration: 'kṣetrajñaṃ cāpi māṃ viddhi sarvakṣetreṣu bhārata .\nkṣetrakṣetrajñayorjñānaṃ yattajjñānaṃ mataṃ mama', meaning: 'Know Me also as the knower of the field in all fields, O Bharata. Knowledge of the field and its knower — that, in My view, is true knowledge.', inShort: 'I am the knower in every field; knowing both is true knowledge.'),
  GitaVerse(chapter: 13, verse: 4, sanskrit: 'तत्क्षेत्रं यच्च यादृक्च यद्विकारि यतश्च यत् |\nस च यो यत्प्रभावश्च तत्समासेन मे शृणु', transliteration: 'tatkṣetraṃ yacca yādṛkca yadvikāri yataśca yat .\nsa ca yo yatprabhāvaśca tatsamāsena me śṛṇu', meaning: 'Hear from Me in brief what the field is, what it is like, what its changes are, and where it comes from; and who its knower is, and what his powers are.', inShort: 'Krishna will briefly describe the field and its knower.'),
  GitaVerse(chapter: 13, verse: 5, sanskrit: 'ऋषिभिर्बहुधा गीतं छन्दोभिर्विविधैः पृथक् |\nब्रह्मसूत्रपदैश्चैव हेतुमद्भिर्विनिश्चितैः', transliteration: 'ṛṣibhirbahudhā gītaṃ chandobhirvividhaiḥ pṛthak .\nbrahmasūtrapadaiścaiva hetumadbhirviniścitaiḥ', meaning: 'This has been sung by the sages in many ways, in various distinct hymns, and in the well-reasoned, conclusive verses of the Brahma Sutras.', inShort: 'The sages and scriptures have taught this in many ways.'),
  GitaVerse(chapter: 13, verse: 6, sanskrit: 'महाभूतान्यहंकारो बुद्धिरव्यक्तमेव च |\nइन्द्रियाणि दशैकं च पञ्च चेन्द्रियगोचराः', transliteration: 'mahābhūtānyahaṃkāro buddhiravyaktameva ca .\nindriyāṇi daśaikaṃ ca pañca cendriyagocarāḥ', meaning: 'The great elements, ego, intellect, and the unmanifest; the ten senses and the mind; and the five objects of the senses —', inShort: 'The elements, ego, intellect, senses, and their objects —'),
  GitaVerse(chapter: 13, verse: 7, sanskrit: 'इच्छा द्वेषः सुखं दुःखं संघातश्चेतना धृतिः |\nएतत्क्षेत्रं समासेन सविकारमुदाहृतम्', transliteration: 'icchā dveṣaḥ sukhaṃ duḥkhaṃ saṃghātaścetanā dhṛtiḥ .\netatkṣetraṃ samāsena savikāramudāhṛtam', meaning: '— desire and aversion, pleasure and pain, the body as a whole, consciousness, and steadfastness: this, in brief, is the field with its changes.', inShort: '— with desire, aversion, pleasure, and pain, make up the field.'),
  GitaVerse(chapter: 13, verse: 8, sanskrit: 'अमानित्वमदम्भित्वमहिंसा क्षान्तिरार्जवम् |\nआचार्योपासनं शौचं स्थैर्यमात्मविनिग्रहः', transliteration: 'amānitvamadambhitvamahiṃsā kṣāntirārjavam .\nācāryopāsanaṃ śaucaṃ sthairyamātmavinigrahaḥ', meaning: 'Humility, freedom from pretense, non-violence, patience, uprightness, service to the teacher, purity, steadiness, self-control —', inShort: 'Humility, sincerity, non-violence, patience, purity —'),
  GitaVerse(chapter: 13, verse: 9, sanskrit: 'इन्द्रियार्थेषु वैराग्यमनहंकार एव च |\nजन्ममृत्युजराव्याधिदुःखदोषानुदर्शनम्', transliteration: 'indriyārtheṣu vairāgyamanahaṃkāra eva ca .\njanmamṛtyujarāvyādhiduḥkhadoṣānudarśanam', meaning: '— detachment from the objects of the senses, absence of ego, and seeing clearly the pain and evil of birth, death, old age, and disease —', inShort: '— detachment, humility, and insight into life\'s suffering —'),
  GitaVerse(chapter: 13, verse: 10, sanskrit: 'असक्तिरनभिष्वङ्गः पुत्रदारगृहादिषु |\nनित्यं च समचित्तत्वमिष्टानिष्टोपपत्तिषु', transliteration: 'asaktiranabhiṣvaṅgaḥ putradāragṛhādiṣu .\nnityaṃ ca samacittatvamiṣṭāniṣṭopapattiṣu', meaning: '— non-attachment, freedom from clinging to children, spouse, home, and the like, and constant even-mindedness amid the desired and the undesired —', inShort: '— non-clinging, and calm in good times and bad —'),
  GitaVerse(chapter: 13, verse: 11, sanskrit: 'मयि चानन्ययोगेन भक्तिरव्यभिचारिणी |\nविविक्तदेशसेवित्वमरतिर्जनसंसदि', transliteration: 'mayi cānanyayogena bhaktiravyabhicāriṇī .\nviviktadeśasevitvamaratirjanasaṃsadi', meaning: '— unwavering devotion to Me through undivided yoga, a love of solitary places, and no taste for crowds —', inShort: '— steady devotion to Me and a love of solitude —'),
  GitaVerse(chapter: 13, verse: 12, sanskrit: 'अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम् |\nएतज्ज्ञानमिति प्रोक्तमज्ञानं यदतोऽन्यथा', transliteration: 'adhyātmajñānanityatvaṃ tattvajñānārthadarśanam .\netajjñānamiti proktamajñānaṃ yadato.anyathā', meaning: '— constancy in knowledge of the Self, and insight into the goal of the knowledge of truth: this is declared to be knowledge, and whatever is contrary to it is ignorance.', inShort: '— this is true knowledge; all else is ignorance.'),
  GitaVerse(chapter: 13, verse: 13, sanskrit: 'ज्ञेयं यत्तत्प्रवक्ष्यामि यज्ज्ञात्वामृतमश्नुते |\nअनादिमत्परं ब्रह्म न सत्तन्नासदुच्यते', transliteration: 'jñeyaṃ yattatpravakṣyāmi yajjñātvāmṛtamaśnute .\nanādi matparaṃ brahma na sattannāsaducyate', meaning: 'I shall now describe what is to be known, knowing which one attains immortality: the beginningless supreme Brahman, which is said to be neither being nor non-being.', inShort: 'The Supreme to be known is beyond being and non-being.'),
  GitaVerse(chapter: 13, verse: 14, sanskrit: 'सर्वतः पाणिपादं तत्सर्वतोऽक्षिशिरोमुखम् |\nसर्वतः श्रुतिमल्लोके सर्वमावृत्य तिष्ठति', transliteration: 'sarvataḥ pāṇipādaṃ tatsarvato.akṣiśiromukham .\nsarvataḥ śrutimalloke sarvamāvṛtya tiṣṭhati', meaning: 'With hands and feet everywhere, with eyes, heads, and faces everywhere, with ears everywhere, It dwells in the world, enveloping all.', inShort: 'It has hands, eyes, and ears everywhere, enveloping all.'),
  GitaVerse(chapter: 13, verse: 15, sanskrit: 'सर्वेन्द्रियगुणाभासं सर्वेन्द्रियविवर्जितम् |\nअसक्तं सर्वभृच्चैव निर्गुणं गुणभोक्तृ च', transliteration: 'sarvendriyaguṇābhāsaṃ sarvendriyavivarjitam .\nasaktaṃ sarvabhṛccaiva nirguṇaṃ guṇabhoktṛ ca', meaning: 'It shines through the workings of all the senses, yet is free of all the senses; unattached, yet sustaining all; beyond the qualities, yet the enjoyer of the qualities.', inShort: 'It works through the senses, yet is beyond them all.'),
  GitaVerse(chapter: 13, verse: 16, sanskrit: 'बहिरन्तश्च भूतानामचरं चरमेव च |\nसूक्ष्मत्वात्तदविज्ञेयं दूरस्थं चान्तिके च तत्', transliteration: 'bahirantaśca bhūtānāmacaraṃ carameva ca .\nsūkṣmatvāttadavijñeyaṃ dūrasthaṃ cāntike ca tat', meaning: 'It is outside and inside all beings, unmoving and moving. Because It is subtle, It cannot be grasped. It is far away, and yet It is near.', inShort: 'It is within and beyond all, far away yet near.'),
  GitaVerse(chapter: 13, verse: 17, sanskrit: 'अविभक्तं च भूतेषु विभक्तमिव च स्थितम् |\nभूतभर्तृ च तज्ज्ञेयं ग्रसिष्णु प्रभविष्णु च', transliteration: 'avibhaktaṃ ca bhūteṣu vibhaktamiva ca sthitam .\nbhūtabhartṛ ca tajjñeyaṃ grasiṣṇu prabhaviṣṇu ca', meaning: 'Undivided, It seems divided among beings. It is to be known as the sustainer of beings; It devours them, and It brings them forth.', inShort: 'Undivided, It seems divided; It sustains, creates, and dissolves all.'),
  GitaVerse(chapter: 13, verse: 18, sanskrit: 'ज्योतिषामपि तज्ज्योतिस्तमसः परमुच्यते |\nज्ञानं ज्ञेयं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम्', transliteration: 'jyotiṣāmapi tajjyotistamasaḥ paramucyate .\njñānaṃ jñeyaṃ jñānagamyaṃ hṛdi sarvasya viṣṭhitam', meaning: 'It is the light of all lights and is said to be beyond darkness. It is knowledge, the object of knowledge, and the goal of knowledge, seated in the heart of all.', inShort: 'The light of all lights dwells in every heart.'),
  GitaVerse(chapter: 13, verse: 19, sanskrit: 'इति क्षेत्रं तथा ज्ञानं ज्ञेयं चोक्तं समासतः |\nमद्भक्त एतद्विज्ञाय मद्भावायोपपद्यते', transliteration: 'iti kṣetraṃ tathā jñānaṃ jñeyaṃ coktaṃ samāsataḥ .\nmadbhakta etadvijñāya madbhāvāyopapadyate', meaning: 'Thus the field, knowledge, and the object of knowledge have been briefly described. My devotee, understanding this, comes to My state of being.', inShort: 'My devotee who understands this comes to Me.'),
  GitaVerse(chapter: 13, verse: 20, sanskrit: 'प्रकृतिं पुरुषं चैव विद्ध्यनादी उभावपि |\nविकारांश्च गुणांश्चैव विद्धि प्रकृतिसम्भवान्', transliteration: 'prakṛtiṃ puruṣaṃ caiva viddhyanādi ubhāvapi .\nvikārāṃśca guṇāṃścaiva viddhi prakṛtisambhavān', meaning: 'Know that nature and spirit are both without beginning, and know that all changes and all qualities arise from nature.', inShort: 'Nature and spirit are beginningless; all change comes from nature.'),
  GitaVerse(chapter: 13, verse: 21, sanskrit: 'कार्यकारणकर्तृत्वे हेतुः प्रकृतिरुच्यते |\nपुरुषः सुखदुःखानां भोक्तृत्वे हेतुरुच्यते', transliteration: 'kāryakāraṇakartṛtve hetuḥ prakṛtirucyate .\npuruṣaḥ sukhaduḥkhānāṃ bhoktṛtve heturucyate', meaning: 'Nature is said to be the cause of the body, its instruments, and all action; spirit is said to be the cause of the experience of pleasure and pain.', inShort: 'Nature acts; the spirit experiences pleasure and pain.'),
  GitaVerse(chapter: 13, verse: 22, sanskrit: 'पुरुषः प्रकृतिस्थो हि भुङ्क्ते प्रकृतिजान्गुणान् |\nकारणं गुणसङ्गोऽस्य सदसद्योनिजन्मसु', transliteration: 'puruṣaḥ prakṛtistho hi bhuṅkte prakṛtijānguṇān .\nkāraṇaṃ guṇasaṅgo.asya sadasadyonijanmasu', meaning: 'The spirit, seated in nature, experiences the qualities born of nature. Attachment to these qualities is the cause of its births in good and evil wombs.', inShort: 'Attachment to nature\'s qualities causes rebirth.'),
  GitaVerse(chapter: 13, verse: 23, sanskrit: 'उपद्रष्टानुमन्ता च भर्ता भोक्ता महेश्वरः |\nपरमात्मेति चाप्युक्तो देहेऽस्मिन्पुरुषः परः', transliteration: 'upadraṣṭānumantā ca bhartā bhoktā maheśvaraḥ .\nparamātmeti cāpyukto dehe.asminpuruṣaḥ paraḥ', meaning: 'The Supreme Spirit in this body is also called the witness, the one who consents, the sustainer, the experiencer, the great Lord, and the Supreme Self.', inShort: 'Within the body dwells the Supreme Self, the witness of all.'),
  GitaVerse(chapter: 13, verse: 24, sanskrit: 'य एवं वेत्ति पुरुषं प्रकृतिं च गुणैः सह |\nसर्वथा वर्तमानोऽपि न स भूयोऽभिजायते', transliteration: 'ya evaṃ vetti puruṣaṃ prakṛtiṃ ca guṇaiḥ saha .\nsarvathā vartamāno.api na sa bhūyo.abhijāyate', meaning: 'One who thus knows spirit, and nature with its qualities, is not born again, whatever their way of life.', inShort: 'One who knows spirit and nature is not born again.'),
  GitaVerse(chapter: 13, verse: 25, sanskrit: 'ध्यानेनात्मनि पश्यन्ति केचिदात्मानमात्मना |\nअन्ये साङ्ख्येन योगेन कर्मयोगेन चापरे', transliteration: 'dhyānenātmani paśyanti kecidātmānamātmanā .\nanye sāṅkhyena yogena karmayogena cāpare', meaning: 'Some see the Self within themselves through meditation; others through the yoga of knowledge; and still others through the yoga of action.', inShort: 'Some see the Self through meditation, others by knowledge or action.'),
  GitaVerse(chapter: 13, verse: 26, sanskrit: 'अन्ये त्वेवमजानन्तः श्रुत्वान्येभ्य उपासते |\nतेऽपि चातितरन्त्येव मृत्युं श्रुतिपरायणाः', transliteration: 'anye tvevamajānantaḥ śrutvānyebhya upāsate .\nte.api cātitarantyeva mṛtyuṃ śrutiparāyaṇāḥ', meaning: 'Still others, not knowing this, worship as they have heard from others. They too, devoted to what they have heard, cross beyond death.', inShort: 'Even those who simply follow what they hear cross beyond death.'),
  GitaVerse(chapter: 13, verse: 27, sanskrit: 'यावत्सञ्जायते किञ्चित्सत्त्वं स्थावरजङ्गमम् |\nक्षेत्रक्षेत्रज्ञसंयोगात्तद्विद्धि भरतर्षभ', transliteration: 'yāvatsañjāyate kiñcitsattvaṃ sthāvarajaṅgamam .\nkṣetrakṣetrajñasaṃyogāttadviddhi bharatarṣabha', meaning: 'Whatever is born, moving or unmoving, know that it arises from the union of the field and the knower of the field, O best of the Bharatas.', inShort: 'All life arises from the union of the field and its knower.'),
  GitaVerse(chapter: 13, verse: 28, sanskrit: 'समं सर्वेषु भूतेषु तिष्ठन्तं परमेश्वरम् |\nविनश्यत्स्वविनश्यन्तं यः पश्यति स पश्यति', transliteration: 'samaṃ sarveṣu bhūteṣu tiṣṭhantaṃ parameśvaram .\nvinaśyatsvavinaśyantaṃ yaḥ paśyati sa paśyati', meaning: 'One who sees the Supreme Lord dwelling equally in all beings, the imperishable within the perishing — that one truly sees.', inShort: 'Who sees the Lord equally in all, truly sees.'),
  GitaVerse(chapter: 13, verse: 29, sanskrit: 'समं पश्यन्हि सर्वत्र समवस्थितमीश्वरम् |\nन हिनस्त्यात्मनात्मानं ततो याति परां गतिम्', transliteration: 'samaṃ paśyanhi sarvatra samavasthitamīśvaram .\nna hinastyātmanātmānaṃ tato yāti parāṃ gatim', meaning: 'Seeing the Lord present equally everywhere, one does not harm the Self by the self, and so reaches the supreme goal.', inShort: 'Seeing God everywhere, one does not harm oneself and reaches the highest.'),
  GitaVerse(chapter: 13, verse: 30, sanskrit: 'प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः |\nयः पश्यति तथात्मानमकर्तारं स पश्यति', transliteration: 'prakṛtyaiva ca karmāṇi kriyamāṇāni sarvaśaḥ .\nyaḥ paśyati tathātmānamakartāraṃ sa paśyati', meaning: 'One who sees that all actions are performed by nature alone, and that the Self is not the doer — that one truly sees.', inShort: 'Who sees that nature acts and the Self does not, truly sees.'),
  GitaVerse(chapter: 13, verse: 31, sanskrit: 'यदा भूतपृथग्भावमेकस्थमनुपश्यति |\nतत एव च विस्तारं ब्रह्म सम्पद्यते तदा', transliteration: 'yadā bhūtapṛthagbhāvamekasthamanupaśyati .\ntata eva ca vistāraṃ brahma sampadyate tadā', meaning: 'When one sees the separate existence of beings as resting in the One, and their unfolding from That alone, then one attains Brahman.', inShort: 'Seeing all beings rooted in the One, one attains Brahman.'),
  GitaVerse(chapter: 13, verse: 32, sanskrit: 'अनादित्वान्निर्गुणत्वात्परमात्मायमव्ययः |\nशरीरस्थोऽपि कौन्तेय न करोति न लिप्यते', transliteration: 'anāditvānnirguṇatvātparamātmāyamavyayaḥ .\nśarīrastho.api kaunteya na karoti na lipyate', meaning: 'Being without beginning and beyond the qualities, this imperishable Supreme Self, though dwelling in the body, O son of Kunti, neither acts nor is touched by action.', inShort: 'The Supreme Self in the body neither acts nor is stained.'),
  GitaVerse(chapter: 13, verse: 33, sanskrit: 'यथा सर्वगतं सौक्ष्म्यादाकाशं नोपलिप्यते |\nसर्वत्रावस्थितो देहे तथात्मा नोपलिप्यते', transliteration: 'yathā sarvagataṃ saukṣmyādākāśaṃ nopalipyate .\nsarvatrāvasthito dehe tathātmā nopalipyate', meaning: 'As all-pervading space, being subtle, is never tainted, so the Self, present everywhere in the body, is never tainted.', inShort: 'Like space, the Self is everywhere and untouched.'),
  GitaVerse(chapter: 13, verse: 34, sanskrit: 'यथा प्रकाशयत्येकः कृत्स्नं लोकमिमं रविः |\nक्षेत्रं क्षेत्री तथा कृत्स्नं प्रकाशयति भारत', transliteration: 'yathā prakāśayatyekaḥ kṛtsnaṃ lokamimaṃ raviḥ .\nkṣetraṃ kṣetrī tathā kṛtsnaṃ prakāśayati bhārata', meaning: 'As the one sun illumines this whole world, so the Lord of the field illumines the whole field, O Bharata.', inShort: 'As the sun lights the world, the Self lights the body.'),
  GitaVerse(chapter: 13, verse: 35, sanskrit: 'क्षेत्रक्षेत्रज्ञयोरेवमन्तरं ज्ञानचक्षुषा |\nभूतप्रकृतिमोक्षं च ये विदुर्यान्ति ते परम्', transliteration: 'kṣetrakṣetrajñayorevamantaraṃ jñānacakṣuṣā .\nbhūtaprakṛtimokṣaṃ ca ye viduryānti te param', meaning: 'Those who, with the eye of knowledge, see the difference between the field and its knower, and the way beings are freed from nature, reach the Supreme.', inShort: 'Those who see the field and its knower clearly reach the Supreme.'),
  GitaVerse(chapter: 14, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nपरं भूयः प्रवक्ष्यामि ज्ञानानां ज्ञानमुत्तमम् |\nयज्ज्ञात्वा मुनयः सर्वे परां सिद्धिमितो गताः', transliteration: 'śrībhagavānuvāca .\nparaṃ bhūyaḥ pravakṣyāmi jñānānāṃ jñānamuttamam .\nyajjñātvā munayaḥ sarve parāṃ siddhimito gatāḥ', meaning: 'The Blessed Lord said: Once more I shall declare the supreme knowledge, the highest of all knowledge, knowing which all the sages have passed from this world to supreme perfection.', inShort: 'Krishna offers the highest knowledge, which led sages to perfection.'),
  GitaVerse(chapter: 14, verse: 2, sanskrit: 'इदं ज्ञानमुपाश्रित्य मम साधर्म्यमागताः |\nसर्गेऽपि नोपजायन्ते प्रलये न व्यथन्ति च', transliteration: 'idaṃ jñānamupāśritya mama sādharmyamāgatāḥ .\nsarge.api nopajāyante pralaye na vyathanti ca', meaning: 'Taking refuge in this knowledge, they have come to share My nature. They are not born at the time of creation, nor are they shaken at the time of dissolution.', inShort: 'Those who live by it share My nature, beyond creation and dissolution.'),
  GitaVerse(chapter: 14, verse: 3, sanskrit: 'मम योनिर्महद् ब्रह्म तस्मिन्गर्भं दधाम्यहम् |\nसम्भवः सर्वभूतानां ततो भवति भारत', transliteration: 'mama yonirmahad brahma tasmingarbhaṃ dadhāmyaham .\nsambhavaḥ sarvabhūtānāṃ tato bhavati bhārata', meaning: 'Great nature is My womb, and in it I place the seed. From that, O Bharata, all beings are born.', inShort: 'Nature is My womb; I place the seed of all life in it.'),
  GitaVerse(chapter: 14, verse: 4, sanskrit: 'सर्वयोनिषु कौन्तेय मूर्तयः सम्भवन्ति याः |\nतासां ब्रह्म महद्योनिरहं बीजप्रदः पिता', transliteration: 'sarvayoniṣu kaunteya mūrtayaḥ sambhavanti yāḥ .\ntāsāṃ brahma mahadyonirahaṃ bījapradaḥ pitā', meaning: 'Whatever forms are born in any womb, O son of Kunti, great nature is their womb, and I am the father who gives the seed.', inShort: 'Nature is the mother of all forms, and I am their father.'),
  GitaVerse(chapter: 14, verse: 5, sanskrit: 'सत्त्वं रजस्तम इति गुणाः प्रकृतिसम्भवाः |\nनिबध्नन्ति महाबाहो देहे देहिनमव्ययम्', transliteration: 'sattvaṃ rajastama iti guṇāḥ prakṛtisambhavāḥ .\nnibadhnanti mahābāho dehe dehinamavyayam', meaning: 'Sattva, rajas, and tamas — goodness, passion, and darkness — are the qualities born of nature. They bind the imperishable soul to the body, O mighty-armed.', inShort: 'Goodness, passion, and darkness bind the soul to the body.'),
  GitaVerse(chapter: 14, verse: 6, sanskrit: 'तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम् |\nसुखसङ्गेन बध्नाति ज्ञानसङ्गेन चानघ', transliteration: 'tatra sattvaṃ nirmalatvātprakāśakamanāmayam .\nsukhasaṅgena badhnāti jñānasaṅgena cānagha', meaning: 'Of these, sattva, being pure, is illuminating and free from affliction. It binds, O sinless one, through attachment to happiness and attachment to knowledge.', inShort: 'Sattva is pure and bright, but binds through love of joy and knowledge.'),
  GitaVerse(chapter: 14, verse: 7, sanskrit: 'रजो रागात्मकं विद्धि तृष्णासङ्गसमुद्भवम् |\nतन्निबध्नाति कौन्तेय कर्मसङ्गेन देहिनम्', transliteration: 'rajo rāgātmakaṃ viddhi tṛṣṇāsaṅgasamudbhavam .\ntannibadhnāti kaunteya karmasaṅgena dehinam', meaning: 'Know that rajas is of the nature of passion, born of craving and attachment. It binds the embodied soul, O son of Kunti, through attachment to action.', inShort: 'Rajas is passion; it binds through attachment to action.'),
  GitaVerse(chapter: 14, verse: 8, sanskrit: 'तमस्त्वज्ञानजं विद्धि मोहनं सर्वदेहिनाम् |\nप्रमादालस्यनिद्राभिस्तन्निबध्नाति भारत', transliteration: 'tamastvajñānajaṃ viddhi mohanaṃ sarvadehinām .\npramādālasyanidrābhistannibadhnāti bhārata', meaning: 'But know that tamas is born of ignorance and deludes all embodied beings. It binds, O Bharata, through heedlessness, laziness, and sleep.', inShort: 'Tamas is born of ignorance; it binds through sloth and sleep.'),
  GitaVerse(chapter: 14, verse: 9, sanskrit: 'सत्त्वं सुखे सञ्जयति रजः कर्मणि भारत |\nज्ञानमावृत्य तु तमः प्रमादे सञ्जयत्युत', transliteration: 'sattvaṃ sukhe sañjayati rajaḥ karmaṇi bhārata .\njñānamāvṛtya tu tamaḥ pramāde sañjayatyuta', meaning: 'Sattva attaches one to happiness and rajas to action, O Bharata, while tamas, veiling knowledge, attaches one to heedlessness.', inShort: 'Sattva ties us to joy, rajas to action, tamas to carelessness.'),
  GitaVerse(chapter: 14, verse: 10, sanskrit: 'रजस्तमश्चाभिभूय सत्त्वं भवति भारत |\nरजः सत्त्वं तमश्चैव तमः सत्त्वं रजस्तथा', transliteration: 'rajastamaścābhibhūya sattvaṃ bhavati bhārata .\nrajaḥ sattvaṃ tamaścaiva tamaḥ sattvaṃ rajastathā', meaning: 'Sattva prevails by overpowering rajas and tamas, O Bharata; rajas, by overpowering sattva and tamas; and tamas, by overpowering sattva and rajas.', inShort: 'The three qualities constantly compete to dominate.'),
  GitaVerse(chapter: 14, verse: 11, sanskrit: 'सर्वद्वारेषु देहेऽस्मिन्प्रकाश उपजायते |\nज्ञानं यदा तदा विद्याद्विवृद्धं सत्त्वमित्युत', transliteration: 'sarvadvāreṣu dehe.asminprakāśa upajāyate .\njñānaṃ yadā tadā vidyādvivṛddhaṃ sattvamityuta', meaning: 'When the light of knowledge shines through all the gates of this body, know that sattva has grown strong.', inShort: 'When knowledge shines through the senses, sattva is rising.'),
  GitaVerse(chapter: 14, verse: 12, sanskrit: 'लोभः प्रवृत्तिरारम्भः कर्मणामशमः स्पृहा |\nरजस्येतानि जायन्ते विवृद्धे भरतर्षभ', transliteration: 'lobhaḥ pravṛttirārambhaḥ karmaṇāmaśamaḥ spṛhā .\nrajasyetāni jāyante vivṛddhe bharatarṣabha', meaning: 'Greed, activity, the undertaking of actions, restlessness, and longing arise when rajas grows strong, O best of the Bharatas.', inShort: 'Greed, restlessness, and craving show that rajas is rising.'),
  GitaVerse(chapter: 14, verse: 13, sanskrit: 'अप्रकाशोऽप्रवृत्तिश्च प्रमादो मोह एव च |\nतमस्येतानि जायन्ते विवृद्धे कुरुनन्दन', transliteration: 'aprakāśo.apravṛttiśca pramādo moha eva ca .\ntamasyetāni jāyante vivṛddhe kurunandana', meaning: 'Darkness, inertia, heedlessness, and delusion arise when tamas grows strong, O joy of the Kurus.', inShort: 'Dullness, inertia, and delusion show that tamas is rising.'),
  GitaVerse(chapter: 14, verse: 14, sanskrit: 'यदा सत्त्वे प्रवृद्धे तु प्रलयं याति देहभृत् |\nतदोत्तमविदां लोकानमलान्प्रतिपद्यते', transliteration: 'yadā sattve pravṛddhe tu pralayaṃ yāti dehabhṛt .\ntadottamavidāṃ lokānamalānpratipadyate', meaning: 'If the embodied soul meets death when sattva prevails, it reaches the pure worlds of those who know the highest.', inShort: 'Dying in sattva leads to the pure worlds of the wise.'),
  GitaVerse(chapter: 14, verse: 15, sanskrit: 'रजसि प्रलयं गत्वा कर्मसङ्गिषु जायते |\nतथा प्रलीनस्तमसि मूढयोनिषु जायते', transliteration: 'rajasi pralayaṃ gatvā karmasaṅgiṣu jāyate .\ntathā pralīnastamasi mūḍhayoniṣu jāyate', meaning: 'Meeting death in rajas, one is born among those attached to action; dying in tamas, one is born in the wombs of the deluded.', inShort: 'Dying in rajas or tamas leads to births of restless action or dullness.'),
  GitaVerse(chapter: 14, verse: 16, sanskrit: 'कर्मणः सुकृतस्याहुः सात्त्विकं निर्मलं फलम् |\nरजसस्तु फलं दुःखमज्ञानं तमसः फलम्', transliteration: 'karmaṇaḥ sukṛtasyāhuḥ sāttvikaṃ nirmalaṃ phalam .\nrajasastu phalaṃ duḥkhamajñānaṃ tamasaḥ phalam', meaning: 'The fruit of good action is said to be pure and of the nature of sattva; the fruit of rajas is pain; and the fruit of tamas is ignorance.', inShort: 'Sattva bears purity, rajas pain, and tamas ignorance.'),
  GitaVerse(chapter: 14, verse: 17, sanskrit: 'सत्त्वात्सञ्जायते ज्ञानं रजसो लोभ एव च |\nप्रमादमोहौ तमसो भवतोऽज्ञानमेव च', transliteration: 'sattvātsañjāyate jñānaṃ rajaso lobha eva ca .\npramādamohau tamaso bhavato.ajñānameva ca', meaning: 'From sattva arises knowledge; from rajas, greed; and from tamas arise heedlessness, delusion, and ignorance.', inShort: 'Sattva brings knowledge, rajas greed, tamas delusion.'),
  GitaVerse(chapter: 14, verse: 18, sanskrit: 'ऊर्ध्वं गच्छन्ति सत्त्वस्था मध्ये तिष्ठन्ति राजसाः |\nजघन्यगुणवृत्तिस्था अधो गच्छन्ति तामसाः', transliteration: 'ūrdhvaṃ gacchanti sattvasthā madhye tiṣṭhanti rājasāḥ .\njaghanyaguṇavṛttisthā adho gacchanti tāmasāḥ', meaning: 'Those established in sattva rise upward; those in rajas stay in the middle; and those in tamas, abiding in the lowest quality, sink downward.', inShort: 'Sattva lifts us up, rajas holds us in the middle, tamas pulls us down.'),
  GitaVerse(chapter: 14, verse: 19, sanskrit: 'नान्यं गुणेभ्यः कर्तारं यदा द्रष्टानुपश्यति |\nगुणेभ्यश्च परं वेत्ति मद्भावं सोऽधिगच्छति', transliteration: 'nānyaṃ guṇebhyaḥ kartāraṃ yadā draṣṭānupaśyati .\nguṇebhyaśca paraṃ vetti madbhāvaṃ so.adhigacchati', meaning: 'When the seer perceives no doer other than the qualities, and knows That which is beyond the qualities, the seer attains My being.', inShort: 'Seeing that only the qualities act, one comes to Me.'),
  GitaVerse(chapter: 14, verse: 20, sanskrit: 'गुणानेतानतीत्य त्रीन्देही देहसमुद्भवान् |\nजन्ममृत्युजरादुःखैर्विमुक्तोऽमृतमश्नुते', transliteration: 'guṇānetānatītya trīndehī dehasamudbhavān .\njanmamṛtyujarāduḥkhairvimukto.amṛtamaśnute', meaning: 'Rising above these three qualities, from which the body arises, the embodied soul is freed from birth, death, old age, and sorrow, and attains immortality.', inShort: 'Rising above the three qualities, the soul becomes immortal.'),
  GitaVerse(chapter: 14, verse: 21, sanskrit: 'अर्जुन उवाच |\nकैर्लिङ्गैस्त्रीन्गुणानेतानतीतो भवति प्रभो |\nकिमाचारः कथं चैतांस्त्रीन्गुणानतिवर्तते', transliteration: 'arjuna uvāca .\nkairliṅgaistrīnguṇānetānatīto bhavati prabho .\nkimācāraḥ kathaṃ caitāṃstrīnguṇānativartate', meaning: 'Arjuna said: By what signs, O Lord, is one known who has gone beyond these three qualities? How does such a person live, and how does one go beyond the three qualities?', inShort: 'Arjuna asks how to recognize one who has risen above the qualities.'),
  GitaVerse(chapter: 14, verse: 22, sanskrit: 'श्रीभगवानुवाच |\nप्रकाशं च प्रवृत्तिं च मोहमेव च पाण्डव |\nन द्वेष्टि सम्प्रवृत्तानि न निवृत्तानि काङ्क्षति', transliteration: 'śrībhagavānuvāca .\nprakāśaṃ ca pravṛttiṃ ca mohameva ca pāṇḍava .\nna dveṣṭi sampravṛttāni na nivṛttāni kāṅkṣati', meaning: 'The Blessed Lord said: One who does not resent light, activity, or delusion when they arise, O Pandava, nor long for them when they cease —', inShort: 'One who neither resents nor craves the play of the qualities —'),
  GitaVerse(chapter: 14, verse: 23, sanskrit: 'उदासीनवदासीनो गुणैर्यो न विचाल्यते |\nगुणा वर्तन्त इत्येवं योऽवतिष्ठति नेङ्गते', transliteration: 'udāsīnavadāsīno guṇairyo na vicālyate .\nguṇā vartanta ityevaṃ yo.avatiṣṭhati neṅgate', meaning: '— who sits as if indifferent, unshaken by the qualities, who stays firm and does not waver, knowing that only the qualities are at work —', inShort: '— unshaken, knowing it is only the qualities at work —'),
  GitaVerse(chapter: 14, verse: 24, sanskrit: 'समदुःखसुखः स्वस्थः समलोष्टाश्मकाञ्चनः |\nतुल्यप्रियाप्रियो धीरस्तुल्यनिन्दात्मसंस्तुतिः', transliteration: 'samaduḥkhasukhaḥ svasthaḥ samaloṣṭāśmakāñcanaḥ .\ntulyapriyāpriyo dhīrastulyanindātmasaṃstutiḥ', meaning: '— who is the same in pain and pleasure, self-possessed, who regards a clod of earth, a stone, and gold alike, who is the same toward the pleasant and the unpleasant, steady, and the same in blame and praise —', inShort: '— equal in pain and pleasure, praise and blame —'),
  GitaVerse(chapter: 14, verse: 25, sanskrit: 'मानापमानयोस्तुल्यस्तुल्यो मित्रारिपक्षयोः |\nसर्वारम्भपरित्यागी गुणातीतः स उच्यते', transliteration: 'mānāpamānayostulyastulyo mitrāripakṣayoḥ .\nsarvārambhaparityāgī guṇātītaḥ sa ucyate', meaning: '— the same in honor and dishonor, the same toward friend and foe, and who has given up all selfish undertakings — such a one is said to have gone beyond the qualities.', inShort: '— such a one has risen above the three qualities.'),
  GitaVerse(chapter: 14, verse: 26, sanskrit: 'मां च योऽव्यभिचारेण भक्तियोगेन सेवते |\nस गुणान्समतीत्यैतान्ब्रह्मभूयाय कल्पते', transliteration: 'māṃ ca yo.avyabhicāreṇa bhaktiyogena sevate .\nsa guṇānsamatītyaitānbrahmabhūyāya kalpate', meaning: 'And one who serves Me with the yoga of unwavering devotion goes beyond these qualities and becomes fit to become one with Brahman.', inShort: 'Unwavering devotion lifts one beyond the qualities to Brahman.'),
  GitaVerse(chapter: 14, verse: 27, sanskrit: 'ब्रह्मणो हि प्रतिष्ठाहममृतस्याव्ययस्य च |\nशाश्वतस्य च धर्मस्य सुखस्यैकान्तिकस्य च', transliteration: 'brahmaṇo hi pratiṣṭhāhamamṛtasyāvyayasya ca .\nśāśvatasya ca dharmasya sukhasyaikāntikasya ca', meaning: 'For I am the foundation of Brahman — of the immortal and the imperishable, of eternal dharma, and of absolute bliss.', inShort: 'I am the ground of Brahman, eternal dharma, and lasting bliss.'),
  GitaVerse(chapter: 15, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम् |\nछन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित्', transliteration: 'śrībhagavānuvāca .\nūrdhvamūlamadhaḥśākhamaśvatthaṃ prāhuravyayam .\nchandāṃsi yasya parṇāni yastaṃ veda sa vedavit', meaning: 'The Blessed Lord said: They speak of an eternal ashvattha tree with its roots above and its branches below, whose leaves are the Vedic hymns. One who knows it knows the Vedas.', inShort: 'The world is a sacred fig tree rooted above; who knows it knows the Vedas.'),
  GitaVerse(chapter: 15, verse: 2, sanskrit: 'अधश्चोर्ध्वं प्रसृतास्तस्य शाखा\nगुणप्रवृद्धा विषयप्रवालाः |\nअधश्च मूलान्यनुसन्ततानि\nकर्मानुबन्धीनि मनुष्यलोके', transliteration: 'adhaścordhvaṃ prasṛtāstasya śākhā guṇapravṛddhā viṣayapravālāḥ .\nadhaśca mūlānyanusantatāni karmānubandhīni manuṣyaloke', meaning: 'Its branches spread below and above, nourished by the qualities, with the objects of the senses as their buds. And below, in the world of men, its roots stretch down, binding through action.', inShort: 'Its branches feed on the senses; its roots bind us through action.'),
  GitaVerse(chapter: 15, verse: 3, sanskrit: 'न रूपमस्येह तथोपलभ्यते\nनान्तो न चादिर्न च सम्प्रतिष्ठा |\nअश्वत्थमेनं सुविरूढमूलं\nअसङ्गशस्त्रेण दृढेन छित्त्वा', transliteration: 'na rūpamasyeha tathopalabhyate nānto na cādirna ca sampratiṣṭhā .\naśvatthamenaṃ suvirūḍhamūlaṃ asaṅgaśastreṇa dṛḍhena chittvā', meaning: 'Its true form is not perceived here, nor its end, nor its beginning, nor its foundation. Having cut down this firmly rooted ashvattha tree with the strong axe of non-attachment —', inShort: 'Cut down this deep-rooted tree with the axe of detachment —'),
  GitaVerse(chapter: 15, verse: 4, sanskrit: 'ततः पदं तत्परिमार्गितव्यं\nयस्मिन्गता न निवर्तन्ति भूयः |\nतमेव चाद्यं पुरुषं प्रपद्ये |\nयतः प्रवृत्तिः प्रसृता पुराणी', transliteration: 'tataḥ padaṃ tatparimārgitavyaṃ yasmingatā na nivartanti bhūyaḥ .\ntameva cādyaṃ puruṣaṃ prapadye .\nyataḥ pravṛttiḥ prasṛtā purāṇī', meaning: '— one should then seek that goal from which, once reached, none return, thinking: I take refuge in that Primal Person from whom this ancient stream of creation has flowed forth.', inShort: '— and seek refuge in the Primal Person, the source of all.'),
  GitaVerse(chapter: 15, verse: 5, sanskrit: 'निर्मानमोहा जितसङ्गदोषा\nअध्यात्मनित्या विनिवृत्तकामाः |\nद्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञैर्-\nगच्छन्त्यमूढाः पदमव्ययं तत्', transliteration: 'nirmānamohā jitasaṅgadoṣā adhyātmanityā vinivṛttakāmāḥ .\ndvandvairvimuktāḥ sukhaduḥkhasaṃjñair- gacchantyamūḍhāḥ padamavyayaṃ tat', meaning: 'Free from pride and delusion, having conquered the evil of attachment, ever dwelling in the Self, with desires turned away, and freed from the pairs of opposites known as pleasure and pain, the undeluded reach that eternal goal.', inShort: 'Free of pride, attachment, and craving, the wise reach the eternal goal.'),
  GitaVerse(chapter: 15, verse: 6, sanskrit: 'न तद्भासयते सूर्यो न शशाङ्को न पावकः |\nयद्गत्वा न निवर्तन्ते तद्धाम परमं मम', transliteration: 'na tadbhāsayate sūryo na śaśāṅko na pāvakaḥ .\nyadgatvā na nivartante taddhāma paramaṃ mama', meaning: 'Neither the sun, nor the moon, nor fire illumines it. Having gone there, none return. That is My supreme abode.', inShort: 'My supreme abode needs no sun or moon, and none return from it.'),
  GitaVerse(chapter: 15, verse: 7, sanskrit: 'ममैवांशो जीवलोके जीवभूतः सनातनः |\nमनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति', transliteration: 'mamaivāṃśo jīvaloke jīvabhūtaḥ sanātanaḥ .\nmanaḥṣaṣṭhānīndriyāṇi prakṛtisthāni karṣati', meaning: 'An eternal fragment of Myself, becoming a living soul in the world of the living, draws to itself the senses, with the mind as the sixth, that rest in nature.', inShort: 'Each living soul is an eternal part of Me.'),
  GitaVerse(chapter: 15, verse: 8, sanskrit: 'शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः |\nगृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात्', transliteration: 'śarīraṃ yadavāpnoti yaccāpyutkrāmatīśvaraḥ .\ngṛhītvaitāni saṃyāti vāyurgandhānivāśayāt', meaning: 'When the lord of the body takes on a body, and when it leaves one, it carries these along, as the wind carries scents from their source.', inShort: 'The soul carries mind and senses from body to body, as wind carries scent.'),
  GitaVerse(chapter: 15, verse: 9, sanskrit: 'श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च |\nअधिष्ठाय मनश्चायं विषयानुपसेवते', transliteration: 'śrotraṃ cakṣuḥ sparśanaṃ ca rasanaṃ ghrāṇameva ca .\nadhiṣṭhāya manaścāyaṃ viṣayānupasevate', meaning: 'Presiding over the ears, eyes, touch, taste, and smell, and the mind as well, it enjoys the objects of the senses.', inShort: 'Through the senses and mind, the soul experiences the world.'),
  GitaVerse(chapter: 15, verse: 10, sanskrit: 'उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम् |\nविमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः', transliteration: 'utkrāmantaṃ sthitaṃ vāpi bhuñjānaṃ vā guṇānvitam .\nvimūḍhā nānupaśyanti paśyanti jñānacakṣuṣaḥ', meaning: 'Whether it is departing, staying, or enjoying, joined with the qualities, the deluded do not perceive it; those with the eye of knowledge see it.', inShort: 'The deluded cannot see the soul; the wise see it with the eye of knowledge.'),
  GitaVerse(chapter: 15, verse: 11, sanskrit: 'यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम् |\nयतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः', transliteration: 'yatanto yoginaścainaṃ paśyantyātmanyavasthitam .\nyatanto.apyakṛtātmāno nainaṃ paśyantyacetasaḥ', meaning: 'Striving yogis see it dwelling within themselves, but the unrefined and thoughtless do not see it, even when they strive.', inShort: 'Striving yogis see the Self within; the careless do not.'),
  GitaVerse(chapter: 15, verse: 12, sanskrit: 'यदादित्यगतं तेजो जगद्भासयतेऽखिलम् |\nयच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम्', transliteration: 'yadādityagataṃ tejo jagadbhāsayate.akhilam .\nyaccandramasi yaccāgnau tattejo viddhi māmakam', meaning: 'The light in the sun that illumines the whole world, the light in the moon, and the light in fire — know that light to be Mine.', inShort: 'The light of the sun, moon, and fire is My light.'),
  GitaVerse(chapter: 15, verse: 13, sanskrit: 'गामाविश्य च भूतानि धारयाम्यहमोजसा |\nपुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः', transliteration: 'gāmāviśya ca bhūtāni dhārayāmyahamojasā .\npuṣṇāmi cauṣadhīḥ sarvāḥ somo bhūtvā rasātmakaḥ', meaning: 'Entering the earth, I sustain all beings with My energy; and becoming the moon, the essence of all sap, I nourish all plants.', inShort: 'I uphold all beings and nourish every plant.'),
  GitaVerse(chapter: 15, verse: 14, sanskrit: 'अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः |\nप्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम्', transliteration: 'ahaṃ vaiśvānaro bhūtvā prāṇināṃ dehamāśritaḥ .\nprāṇāpānasamāyuktaḥ pacāmyannaṃ caturvidham', meaning: 'Becoming the fire of digestion, I dwell in the bodies of living beings and, joined with the incoming and outgoing breath, digest the four kinds of food.', inShort: 'As the digestive fire within, I nourish every body.'),
  GitaVerse(chapter: 15, verse: 15, sanskrit: 'सर्वस्य चाहं हृदि सन्निविष्टो\nमत्तः स्मृतिर्ज्ञानमपोहनञ्च |\nवेदैश्च सर्वैरहमेव वेद्यो\nवेदान्तकृद्वेदविदेव चाहम्', transliteration: 'sarvasya cāhaṃ hṛdi sanniviṣṭo mattaḥ smṛtirjñānamapohanañca .\nvedaiśca sarvairahameva vedyo vedāntakṛdvedavideva cāham', meaning: 'And I am seated in the hearts of all. From Me come memory, knowledge, and their loss. I am what is to be known through all the Vedas; I am the author of the Vedanta, and the knower of the Vedas.', inShort: 'I dwell in every heart and am the goal of all the Vedas.'),
  GitaVerse(chapter: 15, verse: 16, sanskrit: 'द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च |\nक्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते', transliteration: 'dvāvimau puruṣau loke kṣaraścākṣara eva ca .\nkṣaraḥ sarvāṇi bhūtāni kūṭastho.akṣara ucyate', meaning: 'There are two persons in this world, the perishable and the imperishable. All beings are perishable; the unchanging is called the imperishable.', inShort: 'There are two orders of being: the perishable and the imperishable.'),
  GitaVerse(chapter: 15, verse: 17, sanskrit: 'उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः |\nयो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः', transliteration: 'uttamaḥ puruṣastvanyaḥ paramātmetyudāhṛtaḥ .\nyo lokatrayamāviśya bibhartyavyaya īśvaraḥ', meaning: 'But there is another, the Supreme Person, called the Supreme Self, the eternal Lord who enters the three worlds and sustains them.', inShort: 'Beyond both is the Supreme Self, who sustains the three worlds.'),
  GitaVerse(chapter: 15, verse: 18, sanskrit: 'यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः |\nअतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः', transliteration: 'yasmātkṣaramatīto.ahamakṣarādapi cottamaḥ .\nato.asmi loke vede ca prathitaḥ puruṣottamaḥ', meaning: 'Because I am beyond the perishable and higher even than the imperishable, I am celebrated in the world and in the Vedas as the Supreme Person.', inShort: 'Beyond both, I am known as the Supreme Person.'),
  GitaVerse(chapter: 15, verse: 19, sanskrit: 'यो मामेवमसम्मूढो जानाति पुरुषोत्तमम् |\nस सर्वविद्भजति मां सर्वभावेन भारत', transliteration: 'yo māmevamasammūḍho jānāti puruṣottamam .\nsa sarvavidbhajati māṃ sarvabhāvena bhārata', meaning: 'Whoever, free from delusion, knows Me thus as the Supreme Person knows all, and worships Me with their whole being, O Bharata.', inShort: 'Who knows Me as the Supreme Person knows all and loves Me fully.'),
  GitaVerse(chapter: 15, verse: 20, sanskrit: 'इति गुह्यतमं शास्त्रमिदमुक्तं मयानघ |\nएतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत', transliteration: 'iti guhyatamaṃ śāstramidamuktaṃ mayānagha .\netadbuddhvā buddhimānsyātkṛtakṛtyaśca bhārata', meaning: 'Thus I have taught this most secret teaching, O sinless one. Understanding it, a person becomes wise and fulfills all their duties, O Bharata.', inShort: 'Knowing this deepest teaching, one becomes wise and fulfilled.'),
  GitaVerse(chapter: 16, verse: 1, sanskrit: 'श्रीभगवानुवाच |\nअभयं सत्त्वसंशुद्धिर्ज्ञानयोगव्यवस्थितिः |\nदानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम्', transliteration: 'śrībhagavānuvāca .\nabhayaṃ sattvasaṃśuddhirjñānayogavyavasthitiḥ .\ndānaṃ damaśca yajñaśca svādhyāyastapa ārjavam', meaning: 'The Blessed Lord said: Fearlessness, purity of heart, steadfastness in knowledge and yoga, charity, self-restraint, sacrifice, study of the scriptures, austerity, uprightness —', inShort: 'Fearlessness, purity, generosity, self-control —'),
  GitaVerse(chapter: 16, verse: 2, sanskrit: 'अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम् |\nदया भूतेष्वलोलुप्त्वं मार्दवं ह्रीरचापलम्', transliteration: 'ahiṃsā satyamakrodhastyāgaḥ śāntirapaiśunam .\ndayā bhūteṣvaloluptvaṃ mārdavaṃ hrīracāpalam', meaning: '— non-violence, truthfulness, freedom from anger, renunciation, peace, refraining from slander, compassion for all beings, freedom from greed, gentleness, modesty, steadiness —', inShort: '— non-violence, truth, peace, compassion, gentleness —'),
  GitaVerse(chapter: 16, verse: 3, sanskrit: 'तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता |\nभवन्ति सम्पदं दैवीमभिजातस्य भारत', transliteration: 'tejaḥ kṣamā dhṛtiḥ śaucamadroho nātimānitā .\nbhavanti sampadaṃ daivīmabhijātasya bhārata', meaning: '— vigor, forgiveness, fortitude, purity, freedom from malice and from excessive pride: these belong to one born with the divine nature, O Bharata.', inShort: '— forgiveness and humility: these mark the divine nature.'),
  GitaVerse(chapter: 16, verse: 4, sanskrit: 'दम्भो दर्पोऽभिमानश्च क्रोधः पारुष्यमेव च |\nअज्ञानं चाभिजातस्य पार्थ सम्पदमासुरीम्', transliteration: 'dambho darpo.abhimānaśca krodhaḥ pāruṣyameva ca .\najñānaṃ cābhijātasya pārtha sampadamāsurīm', meaning: 'Hypocrisy, arrogance, conceit, anger, harshness, and ignorance belong to one born with the demonic nature, O Partha.', inShort: 'Hypocrisy, arrogance, anger, and harshness mark the demonic nature.'),
  GitaVerse(chapter: 16, verse: 5, sanskrit: 'दैवी सम्पद्विमोक्षाय निबन्धायासुरी मता |\nमा शुचः सम्पदं दैवीमभिजातोऽसि पाण्डव', transliteration: 'daivī sampadvimokṣāya nibandhāyāsurī matā .\nmā śucaḥ sampadaṃ daivīmabhijāto.asi pāṇḍava', meaning: 'The divine nature leads to liberation, the demonic to bondage. Do not grieve, O Pandava; you are born with the divine nature.', inShort: 'The divine nature frees; the demonic binds. Yours is divine.'),
  GitaVerse(chapter: 16, verse: 6, sanskrit: 'द्वौ भूतसर्गौ लोकेऽस्मिन्दैव आसुर एव च |\nदैवो विस्तरशः प्रोक्त आसुरं पार्थ मे शृणु', transliteration: 'dvau bhūtasargau loke.asmindaiva āsura eva ca .\ndaivo vistaraśaḥ prokta āsuraṃ pārtha me śṛṇu', meaning: 'There are two kinds of beings in this world, the divine and the demonic. The divine has been described at length; now hear from Me about the demonic, O Partha.', inShort: 'Krishna now describes the demonic nature.'),
  GitaVerse(chapter: 16, verse: 7, sanskrit: 'प्रवृत्तिं च निवृत्तिं च जना न विदुरासुराः |\nन शौचं नापि चाचारो न सत्यं तेषु विद्यते', transliteration: 'pravṛttiṃ ca nivṛttiṃ ca janā na vidurāsurāḥ .\nna śaucaṃ nāpi cācāro na satyaṃ teṣu vidyate', meaning: 'The demonic do not know what to do and what to refrain from. Neither purity, nor good conduct, nor truth is found in them.', inShort: 'The demonic know neither right action nor restraint.'),
  GitaVerse(chapter: 16, verse: 8, sanskrit: 'असत्यमप्रतिष्ठं ते जगदाहुरनीश्वरम् |\nअपरस्परसम्भूतं किमन्यत्कामहैतुकम्', transliteration: 'asatyamapratiṣṭhaṃ te jagadāhuranīśvaram .\naparasparasambhūtaṃ kimanyatkāmahaitukam', meaning: 'They say the world is unreal, without foundation, and without God; that it arises from mere union, caused by desire and nothing else.', inShort: 'They see the world as godless, driven only by desire.'),
  GitaVerse(chapter: 16, verse: 9, sanskrit: 'एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः |\nप्रभवन्त्युग्रकर्माणः क्षयाय जगतोऽहिताः', transliteration: 'etāṃ dṛṣṭimavaṣṭabhya naṣṭātmāno.alpabuddhayaḥ .\nprabhavantyugrakarmāṇaḥ kṣayāya jagato.ahitāḥ', meaning: 'Holding this view, these lost souls of little understanding, given to cruel deeds, rise up as enemies of the world, bent on its destruction.', inShort: 'Holding such views, they become cruel enemies of the world.'),
  GitaVerse(chapter: 16, verse: 10, sanskrit: 'काममाश्रित्य दुष्पूरं दम्भमानमदान्विताः |\nमोहाद्गृहीत्वासद्ग्राहान्प्रवर्तन्तेऽशुचिव्रताः', transliteration: 'kāmamāśritya duṣpūraṃ dambhamānamadānvitāḥ .\nmohādgṛhītvāsadgrāhānpravartante.aśucivratāḥ', meaning: 'Clinging to insatiable desire, full of hypocrisy, pride, and arrogance, holding false ideas through delusion, they act with impure resolves.', inShort: 'Driven by endless desire and pride, they act with impure motives.'),
  GitaVerse(chapter: 16, verse: 11, sanskrit: 'चिन्तामपरिमेयां च प्रलयान्तामुपाश्रिताः |\nकामोपभोगपरमा एतावदिति निश्चिताः', transliteration: 'cintāmaparimeyāṃ ca pralayāntāmupāśritāḥ .\nkāmopabhogaparamā etāvaditi niścitāḥ', meaning: 'Beset by countless cares that end only with death, holding the enjoyment of desires as the highest goal, convinced that this is all there is —', inShort: 'Consumed by worry, they live only for pleasure —'),
  GitaVerse(chapter: 16, verse: 12, sanskrit: 'आशापाशशतैर्बद्धाः कामक्रोधपरायणाः |\nईहन्ते कामभोगार्थमन्यायेनार्थसञ्चयान्', transliteration: 'āśāpāśaśatairbaddhāḥ kāmakrodhaparāyaṇāḥ .\nīhante kāmabhogārthamanyāyenārthasañcayān', meaning: '— bound by hundreds of ties of hope, given over to desire and anger, they strive by unjust means to amass wealth for the enjoyment of their desires.', inShort: '— and chase wealth by any means to feed their desires.'),
  GitaVerse(chapter: 16, verse: 13, sanskrit: 'इदमद्य मया लब्धमिमं प्राप्स्ये मनोरथम् |\nइदमस्तीदमपि मे भविष्यति पुनर्धनम्', transliteration: 'idamadya mayā labdhamimaṃ prāpsye manoratham .\nidamastīdamapi me bhaviṣyati punardhanam', meaning: '"This I have gained today; this desire I shall fulfill. This wealth is mine, and more shall be mine as well."', inShort: '"This is mine, and more will be mine," they think.'),
  GitaVerse(chapter: 16, verse: 14, sanskrit: 'असौ मया हतः शत्रुर्हनिष्ये चापरानपि |\nईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान्सुखी', transliteration: 'asau mayā hataḥ śatrurhaniṣye cāparānapi .\nīśvaro.ahamahaṃ bhogī siddho.ahaṃ balavānsukhī', meaning: '"That enemy has been slain by me, and I shall slay others too. I am the lord, I am the enjoyer; I am successful, powerful, and happy."', inShort: '"I have conquered; I am powerful and happy," they boast.'),
  GitaVerse(chapter: 16, verse: 15, sanskrit: 'आढ्योऽभिजनवानस्मि कोऽन्योऽस्ति सदृशो मया |\nयक्ष्ये दास्यामि मोदिष्य इत्यज्ञानविमोहिताः', transliteration: 'āḍhyo.abhijanavānasmi ko.anyo.asti sadṛśo mayā .\nyakṣye dāsyāmi modiṣya ityajñānavimohitāḥ', meaning: '"I am wealthy and of noble birth; who else is equal to me? I will perform sacrifices, I will give, I will rejoice" — so they speak, deluded by ignorance.', inShort: 'Proud of wealth and birth, they are deluded by ignorance.'),
  GitaVerse(chapter: 16, verse: 16, sanskrit: 'अनेकचित्तविभ्रान्ता मोहजालसमावृताः |\nप्रसक्ताः कामभोगेषु पतन्ति नरकेऽशुचौ', transliteration: 'anekacittavibhrāntā mohajālasamāvṛtāḥ .\nprasaktāḥ kāmabhogeṣu patanti narake.aśucau', meaning: 'Bewildered by many thoughts, entangled in the net of delusion, addicted to the enjoyment of desires, they fall into a foul hell.', inShort: 'Caught in delusion and craving, they fall into misery.'),
  GitaVerse(chapter: 16, verse: 17, sanskrit: 'आत्मसम्भाविताः स्तब्धा धनमानमदान्विताः |\nयजन्ते नामयज्ञैस्ते दम्भेनाविधिपूर्वकम्', transliteration: 'ātmasambhāvitāḥ stabdhā dhanamānamadānvitāḥ .\nyajante nāmayajñaiste dambhenāvidhipūrvakam', meaning: 'Self-conceited, stubborn, filled with the pride and intoxication of wealth, they perform sacrifices in name only, with hypocrisy, disregarding the scriptural rules.', inShort: 'Vain and proud, they make empty, showy offerings.'),
  GitaVerse(chapter: 16, verse: 18, sanskrit: 'अहंकारं बलं दर्पं कामं क्रोधं च संश्रिताः |\nमामात्मपरदेहेषु प्रद्विषन्तोऽभ्यसूयकाः', transliteration: 'ahaṃkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ ca saṃśritāḥ .\nmāmātmaparadeheṣu pradviṣanto.abhyasūyakāḥ', meaning: 'Given over to ego, power, arrogance, desire, and anger, these envious people hate Me, who dwell in their own bodies and in the bodies of others.', inShort: 'Full of ego and anger, they hate Me, who lives in every body.'),
  GitaVerse(chapter: 16, verse: 19, sanskrit: 'तानहं द्विषतः क्रूरान्संसारेषु नराधमान् |\nक्षिपाम्यजस्रमशुभानासुरीष्वेव योनिषु', transliteration: 'tānahaṃ dviṣataḥ krūrānsaṃsāreṣu narādhamān .\nkṣipāmyajasramaśubhānāsurīṣveva yoniṣu', meaning: 'These cruel haters, the lowest of men, impure — I cast them again and again into demonic wombs in the cycles of rebirth.', inShort: 'The cruel and hateful are born again and again into demonic lives.'),
  GitaVerse(chapter: 16, verse: 20, sanskrit: 'आसुरीं योनिमापन्ना मूढा जन्मनि जन्मनि |\nमामप्राप्यैव कौन्तेय ततो यान्त्यधमां गतिम्', transliteration: 'āsurīṃ yonimāpannā mūḍhā janmani janmani .\nmāmaprāpyaiva kaunteya tato yāntyadhamāṃ gatim', meaning: 'Falling into demonic wombs birth after birth, the deluded, never reaching Me, O son of Kunti, sink to the lowest state.', inShort: 'Never reaching Me, they sink lower and lower.'),
  GitaVerse(chapter: 16, verse: 21, sanskrit: 'त्रिविधं नरकस्येदं द्वारं नाशनमात्मनः |\nकामः क्रोधस्तथा लोभस्तस्मादेतत्त्रयं त्यजेत्', transliteration: 'trividhaṃ narakasyedaṃ dvāraṃ nāśanamātmanaḥ .\nkāmaḥ krodhastathā lobhastasmādetattrayaṃ tyajet', meaning: 'Desire, anger, and greed — these are the three gates of hell that destroy the self. Therefore one should abandon these three.', inShort: 'Desire, anger, and greed are the three gates of hell — give them up.'),
  GitaVerse(chapter: 16, verse: 22, sanskrit: 'एतैर्विमुक्तः कौन्तेय तमोद्वारैस्त्रिभिर्नरः |\nआचरत्यात्मनः श्रेयस्ततो याति परां गतिम्', transliteration: 'etairvimuktaḥ kaunteya tamodvāraistribhirnaraḥ .\nācaratyātmanaḥ śreyastato yāti parāṃ gatim', meaning: 'Freed from these three gates of darkness, O son of Kunti, a person does what is good for the soul and then reaches the supreme goal.', inShort: 'Free of these three, one does good and reaches the highest.'),
  GitaVerse(chapter: 16, verse: 23, sanskrit: 'यः शास्त्रविधिमुत्सृज्य वर्तते कामकारतः |\nन स सिद्धिमवाप्नोति न सुखं न परां गतिम्', transliteration: 'yaḥ śāstravidhimutsṛjya vartate kāmakārataḥ .\nna sa siddhimavāpnoti na sukhaṃ na parāṃ gatim', meaning: 'One who casts aside the guidance of the scriptures and acts on the impulse of desire attains neither perfection, nor happiness, nor the supreme goal.', inShort: 'Ignoring scripture for desire brings neither joy nor perfection.'),
  GitaVerse(chapter: 16, verse: 24, sanskrit: 'तस्माच्छास्त्रं प्रमाणं ते कार्याकार्यव्यवस्थितौ |\nज्ञात्वा शास्त्रविधानोक्तं कर्म कर्तुमिहार्हसि', transliteration: 'tasmācchāstraṃ pramāṇaṃ te kāryākāryavyavasthitau .\njñātvā śāstravidhānoktaṃ karma kartumihārhasi', meaning: 'Therefore let the scriptures be your authority in deciding what should and should not be done. Knowing what the scriptures teach, you should act accordingly here.', inShort: 'Let scripture guide what you do and do not do.'),
  GitaVerse(chapter: 17, verse: 1, sanskrit: 'अर्जुन उवाच |\nये शास्त्रविधिमुत्सृज्य यजन्ते श्रद्धयान्विताः |\nतेषां निष्ठा तु का कृष्ण सत्त्वमाहो रजस्तमः', transliteration: 'arjuna uvāca .\nye śāstravidhimutsṛjya yajante śraddhayānvitāḥ .\nteṣāṃ niṣṭhā tu kā kṛṣṇa sattvamāho rajastamaḥ', meaning: 'Arjuna said: Those who set aside the rules of scripture but worship with faith — what is their standing, O Krishna? Is it sattva, rajas, or tamas?', inShort: 'Arjuna asks about those who worship with faith but ignore scripture.'),
  GitaVerse(chapter: 17, verse: 2, sanskrit: 'श्रीभगवानुवाच |\nत्रिविधा भवति श्रद्धा देहिनां सा स्वभावजा |\nसात्त्विकी राजसी चैव तामसी चेति तां शृणु', transliteration: 'śrībhagavānuvāca .\ntrividhā bhavati śraddhā dehināṃ sā svabhāvajā .\nsāttvikī rājasī caiva tāmasī ceti tāṃ śṛṇu', meaning: 'The Blessed Lord said: The faith of embodied beings is of three kinds, born of their own nature — sattvic, rajasic, and tamasic. Hear about it.', inShort: 'Faith takes three forms, shaped by one\'s nature.'),
  GitaVerse(chapter: 17, verse: 3, sanskrit: 'सत्त्वानुरूपा सर्वस्य श्रद्धा भवति भारत |\nश्रद्धामयोऽयं पुरुषो यो यच्छ्रद्धः स एव सः', transliteration: 'sattvānurūpā sarvasya śraddhā bhavati bhārata .\nśraddhāmayo.ayaṃ puruṣo yo yacchraddhaḥ sa eva saḥ', meaning: 'The faith of each person accords with their nature, O Bharata. A person is made of their faith: as one\'s faith is, so one is.', inShort: 'We become what we have faith in.'),
  GitaVerse(chapter: 17, verse: 4, sanskrit: 'यजन्ते सात्त्विका देवान्यक्षरक्षांसि राजसाः |\nप्रेतान्भूतगणांश्चान्ये यजन्ते तामसा जनाः', transliteration: 'yajante sāttvikā devānyakṣarakṣāṃsi rājasāḥ .\npretānbhūtagaṇāṃścānye yajante tāmasā janāḥ', meaning: 'Sattvic people worship the gods; rajasic people worship the Yakshas and Rakshasas; and others, the tamasic, worship ghosts and spirits.', inShort: 'What one worships reveals one\'s nature.'),
  GitaVerse(chapter: 17, verse: 5, sanskrit: 'अशास्त्रविहितं घोरं तप्यन्ते ये तपो जनाः |\nदम्भाहंकारसंयुक्ताः कामरागबलान्विताः', transliteration: 'aśāstravihitaṃ ghoraṃ tapyante ye tapo janāḥ .\ndambhāhaṃkārasaṃyuktāḥ kāmarāgabalānvitāḥ', meaning: 'Those who practice severe austerities not ordained by scripture, full of hypocrisy and ego, driven by the force of desire and attachment —', inShort: 'Those who practice harsh, self-willed austerities —'),
  GitaVerse(chapter: 17, verse: 6, sanskrit: 'कर्षयन्तः शरीरस्थं भूतग्राममचेतसः |\nमां चैवान्तःशरीरस्थं तान्विद्ध्यासुरनिश्चयान्', transliteration: 'karṣayantaḥ śarīrasthaṃ bhūtagrāmamacetasaḥ .\nmāṃ caivāntaḥśarīrasthaṃ tānviddhyāsuraniścayān', meaning: '— senselessly tormenting the elements of the body, and Me who dwells within the body — know them to be of demonic resolve.', inShort: '— torment the body and Me within it; their resolve is demonic.'),
  GitaVerse(chapter: 17, verse: 7, sanskrit: 'आहारस्त्वपि सर्वस्य त्रिविधो भवति प्रियः |\nयज्ञस्तपस्तथा दानं तेषां भेदमिमं शृणु', transliteration: 'āhārastvapi sarvasya trividho bhavati priyaḥ .\nyajñastapastathā dānaṃ teṣāṃ bhedamimaṃ śṛṇu', meaning: 'Even the food that each person prefers is of three kinds, as are sacrifice, austerity, and charity. Hear how they differ.', inShort: 'Food, sacrifice, austerity, and charity also come in three kinds.'),
  GitaVerse(chapter: 17, verse: 8, sanskrit: 'आयुःसत्त्वबलारोग्यसुखप्रीतिविवर्धनाः |\nरस्याः स्निग्धाः स्थिरा हृद्या आहाराः सात्त्विकप्रियाः', transliteration: 'āyuḥsattvabalārogyasukhaprītivivardhanāḥ .\nrasyāḥ snigdhāḥ sthirā hṛdyā āhārāḥ sāttvikapriyāḥ', meaning: 'Foods that increase life, purity, strength, health, happiness, and cheerfulness, that are savory, rich, nourishing, and pleasing to the heart, are dear to the sattvic.', inShort: 'Sattvic people favor wholesome, nourishing food.'),
  GitaVerse(chapter: 17, verse: 9, sanskrit: 'कट्वम्ललवणात्युष्णतीक्ष्णरूक्षविदाहिनः |\nआहारा राजसस्येष्टा दुःखशोकामयप्रदाः', transliteration: 'kaṭvamlalavaṇātyuṣṇatīkṣṇarūkṣavidāhinaḥ .\nāhārā rājasasyeṣṭā duḥkhaśokāmayapradāḥ', meaning: 'Foods that are bitter, sour, salty, very hot, pungent, dry, and burning are liked by the rajasic; they bring pain, grief, and disease.', inShort: 'Rajasic people crave harsh, spicy food that brings pain.'),
  GitaVerse(chapter: 17, verse: 10, sanskrit: 'यातयामं गतरसं पूति पर्युषितं च यत् |\nउच्छिष्टमपि चामेध्यं भोजनं तामसप्रियम्', transliteration: 'yātayāmaṃ gatarasaṃ pūti paryuṣitaṃ ca yat .\nucchiṣṭamapi cāmedhyaṃ bhojanaṃ tāmasapriyam', meaning: 'Food that is stale, tasteless, putrid, spoiled, left over, and impure is dear to the tamasic.', inShort: 'Tamasic people favor stale and impure food.'),
  GitaVerse(chapter: 17, verse: 11, sanskrit: 'अफलाकाङ्क्षिभिर्यज्ञो विधिदृष्टो य इज्यते |\nयष्टव्यमेवेति मनः समाधाय स सात्त्विकः', transliteration: 'aphalākāṅkṣibhiryajño vidhidṛṣṭo ya ijyate .\nyaṣṭavyameveti manaḥ samādhāya sa sāttvikaḥ', meaning: 'Sacrifice offered according to scripture by those who seek no reward, with the mind firmly set on the thought that it is simply one\'s duty to offer it, is sattvic.', inShort: 'Sacrifice offered as duty, without seeking reward, is sattvic.'),
  GitaVerse(chapter: 17, verse: 12, sanskrit: 'अभिसन्धाय तु फलं दम्भार्थमपि चैव यत् |\nइज्यते भरतश्रेष्ठ तं यज्ञं विद्धि राजसम्', transliteration: 'abhisandhāya tu phalaṃ dambhārthamapi caiva yat .\nijyate bharataśreṣṭha taṃ yajñaṃ viddhi rājasam', meaning: 'But sacrifice offered with an eye to its reward, or for the sake of show, O best of the Bharatas — know that to be rajasic.', inShort: 'Sacrifice made for reward or show is rajasic.'),
  GitaVerse(chapter: 17, verse: 13, sanskrit: 'विधिहीनमसृष्टान्नं मन्त्रहीनमदक्षिणम् |\nश्रद्धाविरहितं यज्ञं तामसं परिचक्षते', transliteration: 'vidhihīnamasṛṣṭānnaṃ mantrahīnamadakṣiṇam .\nśraddhāvirahitaṃ yajñaṃ tāmasaṃ paricakṣate', meaning: 'Sacrifice performed without regard to scripture, without distributing food, without mantras, without gifts to the priests, and without faith, is called tamasic.', inShort: 'Sacrifice without scripture, generosity, or faith is tamasic.'),
  GitaVerse(chapter: 17, verse: 14, sanskrit: 'देवद्विजगुरुप्राज्ञपूजनं शौचमार्जवम् |\nब्रह्मचर्यमहिंसा च शारीरं तप उच्यते', transliteration: 'devadvijaguruprājñapūjanaṃ śaucamārjavam .\nbrahmacaryamahiṃsā ca śārīraṃ tapa ucyate', meaning: 'Worship of the gods, the twice-born, teachers, and the wise; purity, uprightness, celibacy, and non-violence — these are called austerity of the body.', inShort: 'Reverence, purity, restraint, and non-violence are austerity of the body.'),
  GitaVerse(chapter: 17, verse: 15, sanskrit: 'अनुद्वेगकरं वाक्यं सत्यं प्रियहितं च यत् |\nस्वाध्यायाभ्यसनं चैव वाङ्मयं तप उच्यते', transliteration: 'anudvegakaraṃ vākyaṃ satyaṃ priyahitaṃ ca yat .\nsvādhyāyābhyasanaṃ caiva vāṅmayaṃ tapa ucyate', meaning: 'Speech that causes no distress, that is truthful, pleasant, and beneficial, together with the regular study of scripture — this is called austerity of speech.', inShort: 'Truthful, kind, helpful speech is austerity of speech.'),
  GitaVerse(chapter: 17, verse: 16, sanskrit: 'मनः प्रसादः सौम्यत्वं मौनमात्मविनिग्रहः |\nभावसंशुद्धिरित्येतत्तपो मानसमुच्यते', transliteration: 'manaḥ prasādaḥ saumyatvaṃ maunamātmavinigrahaḥ .\nbhāvasaṃśuddhirityetattapo mānasamucyate', meaning: 'Serenity of mind, gentleness, silence, self-control, and purity of heart — these are called austerity of the mind.', inShort: 'Calm, gentleness, silence, and a pure heart are austerity of mind.'),
  GitaVerse(chapter: 17, verse: 17, sanskrit: 'श्रद्धया परया तप्तं तपस्तत्त्रिविधं नरैः |\nअफलाकाङ्क्षिभिर्युक्तैः सात्त्विकं परिचक्षते', transliteration: 'śraddhayā parayā taptaṃ tapastattrividhaṃ naraiḥ .\naphalākāṅkṣibhiryuktaiḥ sāttvikaṃ paricakṣate', meaning: 'This threefold austerity, practiced with supreme faith by people steadfast in yoga who seek no reward, is called sattvic.', inShort: 'Austerity practiced with faith and no desire for reward is sattvic.'),
  GitaVerse(chapter: 17, verse: 18, sanskrit: 'सत्कारमानपूजार्थं तपो दम्भेन चैव यत् |\nक्रियते तदिह प्रोक्तं राजसं चलमध्रुवम्', transliteration: 'satkāramānapūjārthaṃ tapo dambhena caiva yat .\nkriyate tadiha proktaṃ rājasaṃ calamadhruvam', meaning: 'Austerity performed to gain respect, honor, and reverence, and with hypocrisy, is called rajasic here; it is unstable and fleeting.', inShort: 'Austerity for praise and status is rajasic and short-lived.'),
  GitaVerse(chapter: 17, verse: 19, sanskrit: 'मूढग्राहेणात्मनो यत्पीडया क्रियते तपः |\nपरस्योत्सादनार्थं वा तत्तामसमुदाहृतम्', transliteration: 'mūḍhagrāheṇātmano yatpīḍayā kriyate tapaḥ .\nparasyotsādanārthaṃ vā tattāmasamudāhṛtam', meaning: 'Austerity performed out of foolish stubbornness, through self-torture, or in order to harm another is called tamasic.', inShort: 'Austerity that harms oneself or others is tamasic.'),
  GitaVerse(chapter: 17, verse: 20, sanskrit: 'दातव्यमिति यद्दानं दीयतेऽनुपकारिणे |\nदेशे काले च पात्रे च तद्दानं सात्त्विकं स्मृतम्', transliteration: 'dātavyamiti yaddānaṃ dīyate.anupakāriṇe .\ndeśe kāle ca pātre ca taddānaṃ sāttvikaṃ smṛtam', meaning: 'A gift given because it is right to give, to one who can make no return, at the proper place and time, and to a worthy person — that gift is held to be sattvic.', inShort: 'Giving freely, at the right time, to the right person, is sattvic.'),
  GitaVerse(chapter: 17, verse: 21, sanskrit: 'यत्तु प्रत्युपकारार्थं फलमुद्दिश्य वा पुनः |\nदीयते च परिक्लिष्टं तद्दानं राजसं स्मृतम्', transliteration: 'yattu pratyupakārārthaṃ phalamuddiśya vā punaḥ .\ndīyate ca parikliṣṭaṃ taddānaṃ rājasaṃ smṛtam', meaning: 'But a gift given in the hope of a return, or with an eye to reward, or given grudgingly — that gift is held to be rajasic.', inShort: 'Giving for return or reward, or grudgingly, is rajasic.'),
  GitaVerse(chapter: 17, verse: 22, sanskrit: 'अदेशकाले यद्दानमपात्रेभ्यश्च दीयते |\nअसत्कृतमवज्ञातं तत्तामसमुदाहृतम्', transliteration: 'adeśakāle yaddānamapātrebhyaśca dīyate .\nasatkṛtamavajñātaṃ tattāmasamudāhṛtam', meaning: 'A gift given at the wrong place and time, to unworthy people, without respect, or with contempt — that is called tamasic.', inShort: 'Giving carelessly or with contempt is tamasic.'),
  GitaVerse(chapter: 17, verse: 23, sanskrit: 'ॐतत्सदिति निर्देशो ब्रह्मणस्त्रिविधः स्मृतः |\nब्राह्मणास्तेन वेदाश्च यज्ञाश्च विहिताः पुरा', transliteration: 'oṃ tatsaditi nirdeśo brahmaṇastrividhaḥ smṛtaḥ .\nbrāhmaṇāstena vedāśca yajñāśca vihitāḥ purā', meaning: '"Om Tat Sat" — this is declared to be the threefold name of Brahman. By it the Brahmins, the Vedas, and the sacrifices were ordained of old.', inShort: '"Om Tat Sat" is the threefold name of the Supreme.'),
  GitaVerse(chapter: 17, verse: 24, sanskrit: 'तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः |\nप्रवर्तन्ते विधानोक्ताः सततं ब्रह्मवादिनाम्', transliteration: 'tasmādomityudāhṛtya yajñadānatapaḥkriyāḥ .\npravartante vidhānoktāḥ satataṃ brahmavādinām', meaning: 'Therefore the followers of the Vedas always begin the acts of sacrifice, charity, and austerity enjoined by scripture by uttering "Om."', inShort: 'Sacred acts always begin with "Om."'),
  GitaVerse(chapter: 17, verse: 25, sanskrit: 'तदित्यनभिसन्धाय फलं यज्ञतपःक्रियाः |\nदानक्रियाश्च विविधाः क्रियन्ते मोक्षकाङ्क्षिभिः', transliteration: 'tadityanabhisandhāya phalaṃ yajñatapaḥkriyāḥ .\ndānakriyāśca vividhāḥ kriyante mokṣakāṅkṣibhiḥ', meaning: 'Uttering "Tat," those who seek liberation perform the various acts of sacrifice, austerity, and charity without aiming at their fruits.', inShort: 'With "Tat," seekers act without desire for reward.'),
  GitaVerse(chapter: 17, verse: 26, sanskrit: 'सद्भावे साधुभावे च सदित्येतत्प्रयुज्यते |\nप्रशस्ते कर्मणि तथा सच्छब्दः पार्थ युज्यते', transliteration: 'sadbhāve sādhubhāve ca sadityetatprayujyate .\npraśaste karmaṇi tathā sacchabdaḥ pārtha yujyate', meaning: 'The word "Sat" is used to mean reality and goodness; and so too, O Partha, the word "Sat" is used for a praiseworthy act.', inShort: '"Sat" means what is real, good, and worthy.'),
  GitaVerse(chapter: 17, verse: 27, sanskrit: 'यज्ञे तपसि दाने च स्थितिः सदिति चोच्यते |\nकर्म चैव तदर्थीयं सदित्येवाभिधीयते', transliteration: 'yajñe tapasi dāne ca sthitiḥ saditi cocyate .\nkarma caiva tadarthīyaṃ sadityevābhidhīyate', meaning: 'Steadfastness in sacrifice, austerity, and charity is also called "Sat," and any action done for that purpose is likewise called "Sat."', inShort: 'Steadfast sacred action, and work done for it, is "Sat."'),
  GitaVerse(chapter: 17, verse: 28, sanskrit: 'अश्रद्धया हुतं दत्तं तपस्तप्तं कृतं च यत् |\nअसदित्युच्यते पार्थ न च तत्प्रेत्य नो इह', transliteration: 'aśraddhayā hutaṃ dattaṃ tapastaptaṃ kṛtaṃ ca yat .\nasadityucyate pārtha na ca tatpretya no iha', meaning: 'Whatever is offered, given, or performed as austerity without faith is called "asat," O Partha. It is of no value here or hereafter.', inShort: 'Anything done without faith bears no fruit, here or hereafter.'),
  GitaVerse(chapter: 18, verse: 1, sanskrit: 'अर्जुन उवाच |\nसंन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम् |\nत्यागस्य च हृषीकेश पृथक्केशिनिषूदन', transliteration: 'arjuna uvāca .\nsaṃnyāsasya mahābāho tattvamicchāmi veditum .\ntyāgasya ca hṛṣīkeśa pṛthakkeśiniṣūdana', meaning: 'Arjuna said: O mighty-armed one, I wish to know the true nature of renunciation, and of relinquishment, each distinctly, O Hrishikesha, slayer of Keshi.', inShort: 'Arjuna asks the difference between renunciation and relinquishment.'),
  GitaVerse(chapter: 18, verse: 2, sanskrit: 'श्रीभगवानुवाच |\nकाम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः |\nसर्वकर्मफलत्यागं प्राहुस्त्यागं विचक्षणाः', transliteration: 'śrībhagavānuvāca .\nkāmyānāṃ karmaṇāṃ nyāsaṃ saṃnyāsaṃ kavayo viduḥ .\nsarvakarmaphalatyāgaṃ prāhustyāgaṃ vicakṣaṇāḥ', meaning: 'The Blessed Lord said: The wise understand renunciation as giving up actions driven by desire; the discerning call giving up the fruits of all actions relinquishment.', inShort: 'Renunciation drops selfish acts; relinquishment lets go of results.'),
  GitaVerse(chapter: 18, verse: 3, sanskrit: 'त्याज्यं दोषवदित्येके कर्म प्राहुर्मनीषिणः |\nयज्ञदानतपःकर्म न त्याज्यमिति चापरे', transliteration: 'tyājyaṃ doṣavadityeke karma prāhurmanīṣiṇaḥ .\nyajñadānatapaḥkarma na tyājyamiti cāpare', meaning: 'Some thinkers say that action should be given up as an evil; others, that acts of sacrifice, charity, and austerity should not be given up.', inShort: 'Thinkers disagree on whether action should be abandoned.'),
  GitaVerse(chapter: 18, verse: 4, sanskrit: 'निश्चयं शृणु मे तत्र त्यागे भरतसत्तम |\nत्यागो हि पुरुषव्याघ्र त्रिविधः सम्प्रकीर्तितः', transliteration: 'niścayaṃ śṛṇu me tatra tyāge bharatasattama .\ntyāgo hi puruṣavyāghra trividhaḥ samprakīrtitaḥ', meaning: 'Hear My conclusion about relinquishment, O best of the Bharatas. Relinquishment, O tiger among men, is declared to be of three kinds.', inShort: 'Relinquishment, too, is of three kinds.'),
  GitaVerse(chapter: 18, verse: 5, sanskrit: 'यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत् |\nयज्ञो दानं तपश्चैव पावनानि मनीषिणाम्', transliteration: 'yajñadānatapaḥkarma na tyājyaṃ kāryameva tat .\nyajño dānaṃ tapaścaiva pāvanāni manīṣiṇām', meaning: 'Acts of sacrifice, charity, and austerity should not be given up; they should indeed be performed. Sacrifice, charity, and austerity purify even the wise.', inShort: 'Sacrifice, charity, and austerity purify — never give them up.'),
  GitaVerse(chapter: 18, verse: 6, sanskrit: 'एतान्यपि तु कर्माणि सङ्गं त्यक्त्वा फलानि च |\nकर्तव्यानीति मे पार्थ निश्चितं मतमुत्तमम्', transliteration: 'etānyapi tu karmāṇi saṅgaṃ tyaktvā phalāni ca .\nkartavyānīti me pārtha niścitaṃ matamuttamam', meaning: 'But even these actions should be done giving up attachment and the desire for their fruits. This, O Partha, is My firm and highest view.', inShort: 'Do even good works without attachment to results.'),
  GitaVerse(chapter: 18, verse: 7, sanskrit: 'नियतस्य तु संन्यासः कर्मणो नोपपद्यते |\nमोहात्तस्य परित्यागस्तामसः परिकीर्तितः', transliteration: 'niyatasya tu saṃnyāsaḥ karmaṇo nopapadyate .\nmohāttasya parityāgastāmasaḥ parikīrtitaḥ', meaning: 'Renouncing one\'s prescribed duty is not right. Giving it up out of delusion is declared to be tamasic.', inShort: 'Abandoning duty out of delusion is tamasic.'),
  GitaVerse(chapter: 18, verse: 8, sanskrit: 'दुःखमित्येव यत्कर्म कायक्लेशभयात्त्यजेत् |\nस कृत्वा राजसं त्यागं नैव त्यागफलं लभेत्', transliteration: 'duḥkhamityeva yatkarma kāyakleśabhayāttyajet .\nsa kṛtvā rājasaṃ tyāgaṃ naiva tyāgaphalaṃ labhet', meaning: 'One who gives up an action because it is painful, out of fear of bodily hardship, performs rajasic relinquishment and does not gain its fruit.', inShort: 'Abandoning duty to avoid hardship is rajasic.'),
  GitaVerse(chapter: 18, verse: 9, sanskrit: 'कार्यमित्येव यत्कर्म नियतं क्रियतेऽर्जुन |\nसङ्गं त्यक्त्वा फलं चैव स त्यागः सात्त्विको मतः', transliteration: 'kāryamityeva yatkarma niyataṃ kriyate.arjuna .\nsaṅgaṃ tyaktvā phalaṃ caiva sa tyāgaḥ sāttviko mataḥ', meaning: 'When a prescribed duty is done simply because it ought to be done, O Arjuna, giving up attachment and its fruit, that relinquishment is regarded as sattvic.', inShort: 'Doing one\'s duty without attachment is sattvic relinquishment.'),
  GitaVerse(chapter: 18, verse: 10, sanskrit: 'न द्वेष्ट्यकुशलं कर्म कुशले नानुषज्जते |\nत्यागी सत्त्वसमाविष्टो मेधावी छिन्नसंशयः', transliteration: 'na dveṣṭyakuśalaṃ karma kuśale nānuṣajjate .\ntyāgī sattvasamāviṣṭo medhāvī chinnasaṃśayaḥ', meaning: 'The wise relinquisher, filled with sattva and free of doubt, neither hates disagreeable work nor clings to agreeable work.', inShort: 'The wise neither avoid unpleasant work nor cling to pleasant work.'),
  GitaVerse(chapter: 18, verse: 11, sanskrit: 'न हि देहभृता शक्यं त्यक्तुं कर्माण्यशेषतः |\nयस्तु कर्मफलत्यागी स त्यागीत्यभिधीयते', transliteration: 'na hi dehabhṛtā śakyaṃ tyaktuṃ karmāṇyaśeṣataḥ .\nyastu karmaphalatyāgī sa tyāgītyabhidhīyate', meaning: 'It is impossible for an embodied being to give up actions entirely; but one who gives up the fruits of action is called a true relinquisher.', inShort: 'No one can stop acting; true renunciation is letting go of results.'),
  GitaVerse(chapter: 18, verse: 12, sanskrit: 'अनिष्टमिष्टं मिश्रं च त्रिविधं कर्मणः फलम् |\nभवत्यत्यागिनां प्रेत्य न तु संन्यासिनां क्वचित्', transliteration: 'aniṣṭamiṣṭaṃ miśraṃ ca trividhaṃ karmaṇaḥ phalam .\nbhavatyatyāgināṃ pretya na tu saṃnyāsināṃ kvacit', meaning: 'The threefold fruit of action — unpleasant, pleasant, and mixed — comes after death to those who have not relinquished, but never to those who have renounced.', inShort: 'Results bind those who cling to them, not those who let go.'),
  GitaVerse(chapter: 18, verse: 13, sanskrit: 'पञ्चैतानि महाबाहो कारणानि निबोध मे |\nसाङ्ख्ये कृतान्ते प्रोक्तानि सिद्धये सर्वकर्मणाम्', transliteration: 'pañcaitāni mahābāho kāraṇāni nibodha me .\nsāṅkhye kṛtānte proktāni siddhaye sarvakarmaṇām', meaning: 'Learn from Me, O mighty-armed, these five causes for the accomplishment of all actions, as declared in the Sankhya teaching.', inShort: 'Krishna names the five factors behind every action.'),
  GitaVerse(chapter: 18, verse: 14, sanskrit: 'अधिष्ठानं तथा कर्ता करणं च पृथग्विधम् |\nविविधाश्च पृथक्चेष्टा दैवं चैवात्र पञ्चमम्', transliteration: 'adhiṣṭhānaṃ tathā kartā karaṇaṃ ca pṛthagvidham .\nvividhāśca pṛthakceṣṭā daivaṃ caivātra pañcamam', meaning: 'The body, the doer, the various instruments, the many different kinds of effort, and fifth, the divine —', inShort: 'The body, the doer, the senses, effort, and the divine —'),
  GitaVerse(chapter: 18, verse: 15, sanskrit: 'शरीरवाङ्मनोभिर्यत्कर्म प्रारभते नरः |\nन्याय्यं वा विपरीतं वा पञ्चैते तस्य हेतवः', transliteration: 'śarīravāṅmanobhiryatkarma prārabhate naraḥ .\nnyāyyaṃ vā viparītaṃ vā pañcaite tasya hetavaḥ', meaning: '— whatever action a person undertakes with body, speech, or mind, whether right or wrong, these five are its causes.', inShort: '— these five lie behind every act of body, speech, or mind.'),
  GitaVerse(chapter: 18, verse: 16, sanskrit: 'तत्रैवं सति कर्तारमात्मानं केवलं तु यः |\nपश्यत्यकृतबुद्धित्वान्न स पश्यति दुर्मतिः', transliteration: 'tatraivaṃ sati kartāramātmānaṃ kevalaṃ tu yaḥ .\npaśyatyakṛtabuddhitvānna sa paśyati durmatiḥ', meaning: 'That being so, whoever sees the Self alone as the doer, through lack of understanding, does not truly see; such a mind is clouded.', inShort: 'Thinking the Self is the only doer is a clouded view.'),
  GitaVerse(chapter: 18, verse: 17, sanskrit: 'यस्य नाहंकृतो भावो बुद्धिर्यस्य न लिप्यते |\nहत्वाऽपि स इमाँल्लोकान्न हन्ति न निबध्यते', transliteration: 'yasya nāhaṃkṛto bhāvo buddhiryasya na lipyate .\nhatvā.api sa imāṃllokānna hanti na nibadhyate', meaning: 'One who is free of the sense of "I am the doer," whose understanding is untainted — even if they slay these people, they do not slay and are not bound.', inShort: 'Free of ego and attachment, one\'s actions do not bind.'),
  GitaVerse(chapter: 18, verse: 18, sanskrit: 'ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्मचोदना |\nकरणं कर्म कर्तेति त्रिविधः कर्मसंग्रहः', transliteration: 'jñānaṃ jñeyaṃ parijñātā trividhā karmacodanā .\nkaraṇaṃ karma karteti trividhaḥ karmasaṃgrahaḥ', meaning: 'Knowledge, the object of knowledge, and the knower form the threefold impulse to action; the instrument, the action, and the doer form the threefold basis of action.', inShort: 'Knower, known, and knowing drive action; doer, deed, and means carry it out.'),
  GitaVerse(chapter: 18, verse: 19, sanskrit: 'ज्ञानं कर्म च कर्ता च त्रिधैव गुणभेदतः |\nप्रोच्यते गुणसङ्ख्याने यथावच्छृणु तान्यपि', transliteration: 'jñānaṃ karma ca kartā ca tridhaiva guṇabhedataḥ .\nprocyate guṇasaṅkhyāne yathāvacchṛṇu tānyapi', meaning: 'Knowledge, action, and the doer are also of three kinds, according to the qualities, as taught in the science of the qualities. Hear about them as they are.', inShort: 'Knowledge, action, and the doer each take three forms.'),
  GitaVerse(chapter: 18, verse: 20, sanskrit: 'सर्वभूतेषु येनैकं भावमव्ययमीक्षते |\nअविभक्तं विभक्तेषु तज्ज्ञानं विद्धि सात्त्विकम्', transliteration: 'sarvabhūteṣu yenaikaṃ bhāvamavyayamīkṣate .\navibhaktaṃ vibhakteṣu tajjñānaṃ viddhi sāttvikam', meaning: 'The knowledge by which one sees one imperishable reality in all beings, undivided in the divided — know that knowledge to be sattvic.', inShort: 'Seeing the one reality in all beings is sattvic knowledge.'),
  GitaVerse(chapter: 18, verse: 21, sanskrit: 'पृथक्त्वेन तु यज्ज्ञानं नानाभावान्पृथग्विधान् |\nवेत्ति सर्वेषु भूतेषु तज्ज्ञानं विद्धि राजसम्', transliteration: 'pṛthaktvena tu yajjñānaṃ nānābhāvānpṛthagvidhān .\nvetti sarveṣu bhūteṣu tajjñānaṃ viddhi rājasam', meaning: 'The knowledge that sees in all beings many different entities, each separate from the others — know that knowledge to be rajasic.', inShort: 'Seeing only separateness is rajasic knowledge.'),
  GitaVerse(chapter: 18, verse: 22, sanskrit: 'यत्तु कृत्स्नवदेकस्मिन्कार्ये सक्तमहैतुकम् |\nअतत्त्वार्थवदल्पं च तत्तामसमुदाहृतम्', transliteration: 'yattu kṛtsnavadekasminkārye saktamahaitukam .\natattvārthavadalpaṃ ca tattāmasamudāhṛtam', meaning: 'The knowledge that clings to a single thing as if it were the whole, without reason, without grasping the truth, and narrow — that is called tamasic.', inShort: 'Narrow, unreasoning knowledge is tamasic.'),
  GitaVerse(chapter: 18, verse: 23, sanskrit: 'नियतं सङ्गरहितमरागद्वेषतः कृतम् |\nअफलप्रेप्सुना कर्म यत्तत्सात्त्विकमुच्यते', transliteration: 'niyataṃ saṅgarahitamarāgadveṣataḥ kṛtam .\naphalaprepsunā karma yattatsāttvikamucyate', meaning: 'Action that is prescribed, done without attachment, without love or hatred, by one who seeks no reward — that is called sattvic.', inShort: 'Duty done without attachment or desire for reward is sattvic.'),
  GitaVerse(chapter: 18, verse: 24, sanskrit: 'यत्तु कामेप्सुना कर्म साहंकारेण वा पुनः |\nक्रियते बहुलायासं तद्राजसमुदाहृतम्', transliteration: 'yattu kāmepsunā karma sāhaṃkāreṇa vā punaḥ .\nkriyate bahulāyāsaṃ tadrājasamudāhṛtam', meaning: 'But action done with great strain by one who craves desires, or out of ego — that is called rajasic.', inShort: 'Strained action driven by desire or ego is rajasic.'),
  GitaVerse(chapter: 18, verse: 25, sanskrit: 'अनुबन्धं क्षयं हिंसामनपेक्ष्य च पौरुषम् |\nमोहादारभ्यते कर्म यत्तत्तामसमुच्यते', transliteration: 'anubandhaṃ kṣayaṃ hiṃsāmanapekṣya ca pauruṣam .\nmohādārabhyate karma yattattāmasamucyate', meaning: 'Action undertaken out of delusion, without regard to consequences, loss, harm to others, or one\'s own ability — that is called tamasic.', inShort: 'Reckless action that ignores the consequences is tamasic.'),
  GitaVerse(chapter: 18, verse: 26, sanskrit: 'मुक्तसङ्गोऽनहंवादी धृत्युत्साहसमन्वितः |\nसिद्ध्यसिद्ध्योर्निर्विकारः कर्ता सात्त्विक उच्यते', transliteration: 'muktasaṅgo.anahaṃvādī dhṛtyutsāhasamanvitaḥ .\nsiddhyasiddhyornirvikāraḥ kartā sāttvika ucyate', meaning: 'A doer who is free from attachment, without boastfulness, full of resolve and enthusiasm, and unmoved by success or failure, is called sattvic.', inShort: 'The sattvic doer is humble, resolute, and steady in success or failure.'),
  GitaVerse(chapter: 18, verse: 27, sanskrit: 'रागी कर्मफलप्रेप्सुर्लुब्धो हिंसात्मकोऽशुचिः |\nहर्षशोकान्वितः कर्ता राजसः परिकीर्तितः', transliteration: 'rāgī karmaphalaprepsurlubdho hiṃsātmako.aśuciḥ .\nharṣaśokānvitaḥ kartā rājasaḥ parikīrtitaḥ', meaning: 'A doer who is passionate, eager for the fruits of action, greedy, violent, impure, and swept by joy and sorrow, is declared rajasic.', inShort: 'The rajasic doer is greedy and swings between joy and sorrow.'),
  GitaVerse(chapter: 18, verse: 28, sanskrit: 'अयुक्तः प्राकृतः स्तब्धः शठो नैष्कृतिकोऽलसः |\nविषादी दीर्घसूत्री च कर्ता तामस उच्यते', transliteration: 'ayuktaḥ prākṛtaḥ stabdhaḥ śaṭho naiṣkṛtiko.alasaḥ .\nviṣādī dīrghasūtrī ca kartā tāmasa ucyate', meaning: 'A doer who is undisciplined, vulgar, stubborn, deceitful, malicious, lazy, despondent, and procrastinating, is called tamasic.', inShort: 'The tamasic doer is careless, stubborn, lazy, and despondent.'),
  GitaVerse(chapter: 18, verse: 29, sanskrit: 'बुद्धेर्भेदं धृतेश्चैव गुणतस्त्रिविधं शृणु |\nप्रोच्यमानमशेषेण पृथक्त्वेन धनञ्जय', transliteration: 'buddherbhedaṃ dhṛteścaiva guṇatastrividhaṃ śṛṇu .\nprocyamānamaśeṣeṇa pṛthaktvena dhanañjaya', meaning: 'Now hear the threefold distinction of understanding and of resolve, according to the qualities, explained fully and separately, O Dhananjaya.', inShort: 'Krishna now describes three kinds of understanding and resolve.'),
  GitaVerse(chapter: 18, verse: 30, sanskrit: 'प्रवृत्तिं च निवृत्तिं च कार्याकार्ये भयाभये |\nबन्धं मोक्षं च या वेत्ति बुद्धिः सा पार्थ सात्त्विकी', transliteration: 'pravṛttiṃ ca nivṛttiṃ ca kāryākārye bhayābhaye .\nbandhaṃ mokṣaṃ ca yā vetti buddhiḥ sā pārtha sāttvikī', meaning: 'The understanding that knows when to act and when to refrain, what should and should not be done, what to fear and what not to fear, what binds and what liberates — that understanding, O Partha, is sattvic.', inShort: 'Understanding that knows right from wrong, bondage from freedom, is sattvic.'),
  GitaVerse(chapter: 18, verse: 31, sanskrit: 'यया धर्ममधर्मं च कार्यं चाकार्यमेव च |\nअयथावत्प्रजानाति बुद्धिः सा पार्थ राजसी', transliteration: 'yayā dharmamadharmaṃ ca kāryaṃ cākāryameva ca .\nayathāvatprajānāti buddhiḥ sā pārtha rājasī', meaning: 'The understanding by which one wrongly distinguishes dharma from adharma, and what should be done from what should not — that understanding, O Partha, is rajasic.', inShort: 'Understanding that confuses right and wrong is rajasic.'),
  GitaVerse(chapter: 18, verse: 32, sanskrit: 'अधर्मं धर्ममिति या मन्यते तमसावृता |\nसर्वार्थान्विपरीतांश्च बुद्धिः सा पार्थ तामसी', transliteration: 'adharmaṃ dharmamiti yā manyate tamasāvṛtā .\nsarvārthānviparītāṃśca buddhiḥ sā pārtha tāmasī', meaning: 'The understanding that, wrapped in darkness, takes adharma for dharma and sees everything in reverse — that understanding, O Partha, is tamasic.', inShort: 'Understanding that sees everything upside down is tamasic.'),
  GitaVerse(chapter: 18, verse: 33, sanskrit: 'धृत्या यया धारयते मनःप्राणेन्द्रियक्रियाः |\nयोगेनाव्यभिचारिण्या धृतिः सा पार्थ सात्त्विकी', transliteration: 'dhṛtyā yayā dhārayate manaḥprāṇendriyakriyāḥ .\nyogenāvyabhicāriṇyā dhṛtiḥ sā pārtha sāttvikī', meaning: 'The unwavering resolve by which, through yoga, one governs the workings of the mind, the breath, and the senses — that resolve, O Partha, is sattvic.', inShort: 'Resolve that steadies mind, breath, and senses is sattvic.'),
  GitaVerse(chapter: 18, verse: 34, sanskrit: 'यया तु धर्मकामार्थान्धृत्या धारयतेऽर्जुन |\nप्रसङ्गेन फलाकाङ्क्षी धृतिः सा पार्थ राजसी', transliteration: 'yayā tu dharmakāmārthāndhṛtyā dhārayate.arjuna .\nprasaṅgena phalākāṅkṣī dhṛtiḥ sā pārtha rājasī', meaning: 'But the resolve by which one holds fast to duty, pleasure, and wealth, craving their fruits out of attachment, O Arjuna — that resolve, O Partha, is rajasic.', inShort: 'Resolve that clings to duty, pleasure, and wealth for their rewards is rajasic.'),
  GitaVerse(chapter: 18, verse: 35, sanskrit: 'यया स्वप्नं भयं शोकं विषादं मदमेव च |\nन विमुञ्चति दुर्मेधा धृतिः सा पार्थ तामसी', transliteration: 'yayā svapnaṃ bhayaṃ śokaṃ viṣādaṃ madameva ca .\nna vimuñcati durmedhā dhṛtiḥ sā pārtha tāmasī', meaning: 'The resolve by which a foolish person does not let go of sleep, fear, grief, despondency, and arrogance — that resolve, O Partha, is tamasic.', inShort: 'Stubbornly clinging to fear, grief, and sloth is tamasic resolve.'),
  GitaVerse(chapter: 18, verse: 36, sanskrit: 'सुखं त्विदानीं त्रिविधं शृणु मे भरतर्षभ |\nअभ्यासाद्रमते यत्र दुःखान्तं च निगच्छति', transliteration: 'sukhaṃ tvidānīṃ trividhaṃ śṛṇu me bharatarṣabha .\nabhyāsādramate yatra duḥkhāntaṃ ca nigacchati', meaning: 'Now hear from Me, O best of the Bharatas, about the three kinds of happiness. That in which one comes to rejoice through practice, and which brings an end to sorrow —', inShort: 'Krishna now describes three kinds of happiness —'),
  GitaVerse(chapter: 18, verse: 37, sanskrit: 'यत्तदग्रे विषमिव परिणामेऽमृतोपमम् |\nतत्सुखं सात्त्विकं प्रोक्तमात्मबुद्धिप्रसादजम्', transliteration: 'yattadagre viṣamiva pariṇāme.amṛtopamam .\ntatsukhaṃ sāttvikaṃ proktamātmabuddhiprasādajam', meaning: '— which is like poison at first but like nectar in the end, born of the clarity of one\'s own mind — that happiness is called sattvic.', inShort: '— happiness bitter at first but sweet in the end is sattvic.'),
  GitaVerse(chapter: 18, verse: 38, sanskrit: 'विषयेन्द्रियसंयोगाद्यत्तदग्रेऽमृतोपमम् |\nपरिणामे विषमिव तत्सुखं राजसं स्मृतम्', transliteration: 'viṣayendriyasaṃyogādyattadagre.amṛtopamam .\npariṇāme viṣamiva tatsukhaṃ rājasaṃ smṛtam', meaning: 'The happiness that arises from the contact of the senses with their objects, like nectar at first but like poison in the end — that is held to be rajasic.', inShort: 'Pleasure sweet at first but bitter in the end is rajasic.'),
  GitaVerse(chapter: 18, verse: 39, sanskrit: 'यदग्रे चानुबन्धे च सुखं मोहनमात्मनः |\nनिद्रालस्यप्रमादोत्थं तत्तामसमुदाहृतम्', transliteration: 'yadagre cānubandhe ca sukhaṃ mohanamātmanaḥ .\nnidrālasyapramādotthaṃ tattāmasamudāhṛtam', meaning: 'The happiness that deludes the self from beginning to end, arising from sleep, laziness, and heedlessness — that is called tamasic.', inShort: 'Pleasure from sloth and carelessness is tamasic.'),
  GitaVerse(chapter: 18, verse: 40, sanskrit: 'न तदस्ति पृथिव्यां वा दिवि देवेषु वा पुनः |\nसत्त्वं प्रकृतिजैर्मुक्तं यदेभिः स्यात्त्रिभिर्गुणैः', transliteration: 'na tadasti pṛthivyāṃ vā divi deveṣu vā punaḥ .\nsattvaṃ prakṛtijairmuktaṃ yadebhiḥ syāttribhirguṇaiḥ', meaning: 'There is no being on earth, or even among the gods in heaven, that is free from these three qualities born of nature.', inShort: 'No being, on earth or in heaven, is free of the three qualities.'),
  GitaVerse(chapter: 18, verse: 41, sanskrit: 'ब्राह्मणक्षत्रियविशां शूद्राणां च परन्तप |\nकर्माणि प्रविभक्तानि स्वभावप्रभवैर्गुणैः', transliteration: 'brāhmaṇakṣatriyaviśāṃ śūdrāṇāṃ ca parantapa .\nkarmāṇi pravibhaktāni svabhāvaprabhavairguṇaiḥ', meaning: 'The duties of Brahmins, Kshatriyas, Vaishyas, and Shudras, O scorcher of foes, are divided according to the qualities arising from their own nature.', inShort: 'People\'s duties differ according to their natures.'),
  GitaVerse(chapter: 18, verse: 42, sanskrit: 'शमो दमस्तपः शौचं क्षान्तिरार्जवमेव च |\nज्ञानं विज्ञानमास्तिक्यं ब्रह्मकर्म स्वभावजम्', transliteration: 'śamo damastapaḥ śaucaṃ kṣāntirārjavameva ca .\njñānaṃ vijñānamāstikyaṃ brahmakarma svabhāvajam', meaning: 'Serenity, self-control, austerity, purity, patience, uprightness, knowledge, wisdom, and faith in God are the duties of a Brahmin, born of their nature.', inShort: 'The priestly nature is calm, pure, wise, and devout.'),
  GitaVerse(chapter: 18, verse: 43, sanskrit: 'शौर्यं तेजो धृतिर्दाक्ष्यं युद्धे चाप्यपलायनम् |\nदानमीश्वरभावश्च क्षात्रं कर्म स्वभावजम्', transliteration: 'śauryaṃ tejo dhṛtirdākṣyaṃ yuddhe cāpyapalāyanam .\ndānamīśvarabhāvaśca kṣātraṃ karma svabhāvajam', meaning: 'Heroism, vigor, firmness, skill, not fleeing in battle, generosity, and leadership are the duties of a Kshatriya, born of their nature.', inShort: 'The warrior nature is brave, steady, generous, and leads others.'),
  GitaVerse(chapter: 18, verse: 44, sanskrit: 'कृषिगौरक्ष्यवाणिज्यं वैश्यकर्म स्वभावजम् |\nपरिचर्यात्मकं कर्म शूद्रस्यापि स्वभावजम्', transliteration: 'kṛṣigaurakṣyavāṇijyaṃ vaiśyakarma svabhāvajam .\nparicaryātmakaṃ karma śūdrasyāpi svabhāvajam', meaning: 'Farming, tending cattle, and trade are the duties of a Vaishya, born of their nature; and work of service is the duty of a Shudra, born of their nature.', inShort: 'Farmers, traders, and those who serve each follow their own nature.'),
  GitaVerse(chapter: 18, verse: 45, sanskrit: 'स्वे स्वे कर्मण्यभिरतः संसिद्धिं लभते नरः |\nस्वकर्मनिरतः सिद्धिं यथा विन्दति तच्छृणु', transliteration: 'sve sve karmaṇyabhirataḥ saṃsiddhiṃ labhate naraḥ .\nsvakarmanirataḥ siddhiṃ yathā vindati tacchṛṇu', meaning: 'Devoted to their own duty, each person attains perfection. Hear how one devoted to their own duty finds perfection.', inShort: 'Each person reaches perfection by following their own duty.'),
  GitaVerse(chapter: 18, verse: 46, sanskrit: 'यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम् |\nस्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः', transliteration: 'yataḥ pravṛttirbhūtānāṃ yena sarvamidaṃ tatam .\nsvakarmaṇā tamabhyarcya siddhiṃ vindati mānavaḥ', meaning: 'By worshipping, through their own work, Him from whom all beings arise and by whom all this is pervaded, a person attains perfection.', inShort: 'Doing one\'s work as worship of the Divine leads to perfection.'),
  GitaVerse(chapter: 18, verse: 47, sanskrit: 'श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् |\nस्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम्', transliteration: 'śreyānsvadharmo viguṇaḥ paradharmātsvanuṣṭhitāt .\nsvabhāvaniyataṃ karma kurvannāpnoti kilbiṣam', meaning: 'Better is one\'s own dharma, though imperfect, than the dharma of another well performed. Doing the duty ordained by one\'s own nature, one incurs no sin.', inShort: 'Better your own path done imperfectly than another\'s done well.'),
  GitaVerse(chapter: 18, verse: 48, sanskrit: 'सहजं कर्म कौन्तेय सदोषमपि न त्यजेत् |\nसर्वारम्भा हि दोषेण धूमेनाग्निरिवावृताः', transliteration: 'sahajaṃ karma kaunteya sadoṣamapi na tyajet .\nsarvārambhā hi doṣeṇa dhūmenāgnirivāvṛtāḥ', meaning: 'One should not give up the work one is born to, O son of Kunti, even if it has faults; for all undertakings are clouded by faults, as fire is by smoke.', inShort: 'Every task has flaws, as fire has smoke — keep to your own.'),
  GitaVerse(chapter: 18, verse: 49, sanskrit: 'असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः |\nनैष्कर्म्यसिद्धिं परमां संन्यासेनाधिगच्छति', transliteration: 'asaktabuddhiḥ sarvatra jitātmā vigataspṛhaḥ .\nnaiṣkarmyasiddhiṃ paramāṃ saṃnyāsenādhigacchati', meaning: 'One whose understanding is unattached everywhere, who has mastered the self and is free from craving, attains through renunciation the supreme perfection of freedom from action.', inShort: 'Detached and self-mastered, one attains freedom from karma.'),
  GitaVerse(chapter: 18, verse: 50, sanskrit: 'सिद्धिं प्राप्तो यथा ब्रह्म तथाप्नोति निबोध मे |\nसमासेनैव कौन्तेय निष्ठा ज्ञानस्य या परा', transliteration: 'siddhiṃ prāpto yathā brahma tathāpnoti nibodha me .\nsamāsenaiva kaunteya niṣṭhā jñānasya yā parā', meaning: 'Learn from Me in brief, O son of Kunti, how one who has attained perfection attains Brahman, the supreme culmination of knowledge.', inShort: 'Krishna describes how the perfected soul reaches Brahman.'),
  GitaVerse(chapter: 18, verse: 51, sanskrit: 'बुद्ध्या विशुद्धया युक्तो धृत्यात्मानं नियम्य च |\nशब्दादीन्विषयांस्त्यक्त्वा रागद्वेषौ व्युदस्य च', transliteration: 'buddhyā viśuddhayā yukto dhṛtyātmānaṃ niyamya ca .\nśabdādīnviṣayāṃstyaktvā rāgadveṣau vyudasya ca', meaning: 'Endowed with a purified understanding, controlling the self with firmness, turning away from sound and the other objects of the senses, casting aside attraction and aversion —', inShort: 'With a pure mind, steady control, and no likes or dislikes —'),
  GitaVerse(chapter: 18, verse: 52, sanskrit: 'विविक्तसेवी लघ्वाशी यतवाक्कायमानसः |\nध्यानयोगपरो नित्यं वैराग्यं समुपाश्रितः', transliteration: 'viviktasevī laghvāśī yatavākkāyamānasaḥ .\ndhyānayogaparo nityaṃ vairāgyaṃ samupāśritaḥ', meaning: '— living in solitude, eating lightly, controlling speech, body, and mind, always devoted to the yoga of meditation, taking refuge in dispassion —', inShort: '— living simply, in meditation and detachment —'),
  GitaVerse(chapter: 18, verse: 53, sanskrit: 'अहंकारं बलं दर्पं कामं क्रोधं परिग्रहम् |\nविमुच्य निर्ममः शान्तो ब्रह्मभूयाय कल्पते', transliteration: 'ahaṃkāraṃ balaṃ darpaṃ kāmaṃ krodhaṃ parigraham .\nvimucya nirmamaḥ śānto brahmabhūyāya kalpate', meaning: '— and giving up ego, force, arrogance, desire, anger, and possessiveness, free from the sense of "mine" and at peace, one becomes fit to be one with Brahman.', inShort: '— free of ego and possessiveness, one becomes one with Brahman.'),
  GitaVerse(chapter: 18, verse: 54, sanskrit: 'ब्रह्मभूतः प्रसन्नात्मा न शोचति न काङ्क्षति |\nसमः सर्वेषु भूतेषु मद्भक्तिं लभते पराम्', transliteration: 'brahmabhūtaḥ prasannātmā na śocati na kāṅkṣati .\nsamaḥ sarveṣu bhūteṣu madbhaktiṃ labhate parām', meaning: 'Having become one with Brahman, serene in the Self, one neither grieves nor craves. The same toward all beings, one attains supreme devotion to Me.', inShort: 'One with Brahman and equal to all, one finds supreme devotion to Me.'),
  GitaVerse(chapter: 18, verse: 55, sanskrit: 'भक्त्या मामभिजानाति यावान्यश्चास्मि तत्त्वतः |\nततो मां तत्त्वतो ज्ञात्वा विशते तदनन्तरम्', transliteration: 'bhaktyā māmabhijānāti yāvānyaścāsmi tattvataḥ .\ntato māṃ tattvato jñātvā viśate tadanantaram', meaning: 'Through devotion one comes to know Me truly — what I am and who I am. Then, knowing Me in truth, one enters into Me at once.', inShort: 'Through devotion one knows Me truly and enters into Me.'),
  GitaVerse(chapter: 18, verse: 56, sanskrit: 'सर्वकर्माण्यपि सदा कुर्वाणो मद्व्यपाश्रयः |\nमत्प्रसादादवाप्नोति शाश्वतं पदमव्ययम्', transliteration: 'sarvakarmāṇyapi sadā kurvāṇo madvyapāśrayaḥ .\nmatprasādādavāpnoti śāśvataṃ padamavyayam', meaning: 'Though always performing all actions, one who takes refuge in Me reaches, by My grace, the eternal, imperishable abode.', inShort: 'Taking refuge in Me, even while working, one reaches My eternal abode.'),
  GitaVerse(chapter: 18, verse: 57, sanskrit: 'चेतसा सर्वकर्माणि मयि संन्यस्य मत्परः |\nबुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव', transliteration: 'cetasā sarvakarmāṇi mayi saṃnyasya matparaḥ .\nbuddhiyogamupāśritya maccittaḥ satataṃ bhava', meaning: 'Mentally offering all actions to Me, holding Me as the supreme goal, relying on the yoga of understanding, keep your mind always fixed on Me.', inShort: 'Offer all actions to Me and keep your mind on Me always.'),
  GitaVerse(chapter: 18, verse: 58, sanskrit: 'मच्चित्तः सर्वदुर्गाणि मत्प्रसादात्तरिष्यसि |\nअथ चेत्त्वमहंकारान्न श्रोष्यसि विनङ्क्ष्यसि', transliteration: 'maccittaḥ sarvadurgāṇi matprasādāttariṣyasi .\natha cettvamahaṃkārānna śroṣyasi vinaṅkṣyasi', meaning: 'With your mind fixed on Me, you will overcome all obstacles by My grace. But if, out of ego, you will not listen, you will perish.', inShort: 'Fixed on Me, you will overcome every obstacle by My grace.'),
  GitaVerse(chapter: 18, verse: 59, sanskrit: 'यदहंकारमाश्रित्य न योत्स्य इति मन्यसे |\nमिथ्यैष व्यवसायस्ते प्रकृतिस्त्वां नियोक्ष्यति', transliteration: 'yadahaṃkāramāśritya na yotsya iti manyase .\nmithyaiṣa vyavasāyaste prakṛtistvāṃ niyokṣyati', meaning: 'If, relying on ego, you think, "I will not fight," your resolve is in vain; your own nature will compel you.', inShort: 'Refusing out of ego is futile; your nature will make you act.'),
  GitaVerse(chapter: 18, verse: 60, sanskrit: 'स्वभावजेन कौन्तेय निबद्धः स्वेन कर्मणा |\nकर्तुं नेच्छसि यन्मोहात्करिष्यस्यवशोऽपि तत्', transliteration: 'svabhāvajena kaunteya nibaddhaḥ svena karmaṇā .\nkartuṃ necchasi yanmohātkariṣyasyavaśo.api tat', meaning: 'Bound by your own work, born of your nature, O son of Kunti, what you do not wish to do out of delusion, you will do even against your will.', inShort: 'Your nature will lead you to do what delusion makes you resist.'),
  GitaVerse(chapter: 18, verse: 61, sanskrit: 'ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति |\nभ्रामयन्सर्वभूतानि यन्त्रारूढानि मायया', transliteration: 'īśvaraḥ sarvabhūtānāṃ hṛddeśe.arjuna tiṣṭhati .\nbhrāmayansarvabhūtāni yantrārūḍhāni māyayā', meaning: 'The Lord dwells in the hearts of all beings, O Arjuna, causing all beings to revolve by His power, as if mounted on a machine.', inShort: 'The Lord dwells in every heart, moving all beings by His power.'),
  GitaVerse(chapter: 18, verse: 62, sanskrit: 'तमेव शरणं गच्छ सर्वभावेन भारत |\nतत्प्रसादात्परां शान्तिं स्थानं प्राप्स्यसि शाश्वतम्', transliteration: 'tameva śaraṇaṃ gaccha sarvabhāvena bhārata .\ntatprasādātparāṃ śāntiṃ sthānaṃ prāpsyasi śāśvatam', meaning: 'Take refuge in Him alone with your whole being, O Bharata. By His grace you will attain supreme peace and the eternal abode.', inShort: 'Surrender to Him fully and find supreme, lasting peace.'),
  GitaVerse(chapter: 18, verse: 63, sanskrit: 'इति ते ज्ञानमाख्यातं गुह्याद्गुह्यतरं मया |\nविमृश्यैतदशेषेण यथेच्छसि तथा कुरु', transliteration: 'iti te jñānamākhyātaṃ guhyādguhyataraṃ mayā .\nvimṛśyaitadaśeṣeṇa yathecchasi tathā kuru', meaning: 'Thus I have revealed to you wisdom more secret than all secrets. Reflect on it fully, and then do as you wish.', inShort: 'Krishna has shared the deepest wisdom; now Arjuna must choose.'),
  GitaVerse(chapter: 18, verse: 64, sanskrit: 'सर्वगुह्यतमं भूयः शृणु मे परमं वचः |\nइष्टोऽसि मे दृढमिति ततो वक्ष्यामि ते हितम्', transliteration: 'sarvaguhyatamaṃ bhūyaḥ śṛṇu me paramaṃ vacaḥ .\niṣṭo.asi me dṛḍhamiti tato vakṣyāmi te hitam', meaning: 'Hear again My supreme word, the most secret of all. You are dearly loved by Me, so I will tell you what is for your good.', inShort: 'Because Arjuna is dearly loved, Krishna shares His final word.'),
  GitaVerse(chapter: 18, verse: 65, sanskrit: 'मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु |\nमामेवैष्यसि सत्यं ते प्रतिजाने प्रियोऽसि मे', transliteration: 'manmanā bhava madbhakto madyājī māṃ namaskuru .\nmāmevaiṣyasi satyaṃ te pratijāne priyo.asi me', meaning: 'Fix your mind on Me, be devoted to Me, worship Me, bow down to Me. You will surely come to Me; I promise you truly, for you are dear to Me.', inShort: 'Love Me, worship Me, and you will come to Me — I promise.'),
  GitaVerse(chapter: 18, verse: 66, sanskrit: 'सर्वधर्मान्परित्यज्य मामेकं शरणं व्रज |\nअहं त्वां सर्वपापेभ्यो मोक्षयिष्यामि मा शुचः', transliteration: 'sarvadharmānparityajya māmekaṃ śaraṇaṃ vraja .\nahaṃ tvāṃ sarvapāpebhyo mokṣayiṣyāmi mā śucaḥ', meaning: 'Abandoning all dharmas, take refuge in Me alone. I will free you from all sins; do not grieve.', inShort: 'Surrender to Me alone; I will free you from all sin. Do not grieve.'),
  GitaVerse(chapter: 18, verse: 67, sanskrit: 'इदं ते नातपस्काय नाभक्ताय कदाचन |\nन चाशुश्रूषवे वाच्यं न च मां योऽभ्यसूयति', transliteration: 'idaṃ te nātapaskāya nābhaktāya kadācana .\nna cāśuśrūṣave vācyaṃ na ca māṃ yo.abhyasūyati', meaning: 'This should never be spoken to one who lacks austerity or devotion, nor to one who does not wish to listen, nor to one who scorns Me.', inShort: 'Share this teaching only with those who are open and devoted.'),
  GitaVerse(chapter: 18, verse: 68, sanskrit: 'य इदं परमं गुह्यं मद्भक्तेष्वभिधास्यति |\nभक्तिं मयि परां कृत्वा मामेवैष्यत्यसंशयः', transliteration: 'ya idaṃ paramaṃ guhyaṃ madbhakteṣvabhidhāsyati .\nbhaktiṃ mayi parāṃ kṛtvā māmevaiṣyatyasaṃśayaḥ', meaning: 'Whoever teaches this supreme secret to My devotees, with the highest devotion to Me, will come to Me without doubt.', inShort: 'Whoever shares this with devotees will surely come to Me.'),
  GitaVerse(chapter: 18, verse: 69, sanskrit: 'न च तस्मान्मनुष्येषु कश्चिन्मे प्रियकृत्तमः |\nभविता न च मे तस्मादन्यः प्रियतरो भुवि', transliteration: 'na ca tasmānmanuṣyeṣu kaścinme priyakṛttamaḥ .\nbhavitā na ca me tasmādanyaḥ priyataro bhuvi', meaning: 'No one among people does Me dearer service than such a person, and no one on earth will be dearer to Me.', inShort: 'No one is dearer to Me than one who shares this teaching.'),
  GitaVerse(chapter: 18, verse: 70, sanskrit: 'अध्येष्यते च य इमं धर्म्यं संवादमावयोः |\nज्ञानयज्ञेन तेनाहमिष्टः स्यामिति मे मतिः', transliteration: 'adhyeṣyate ca ya imaṃ dharmyaṃ saṃvādamāvayoḥ .\njñānayajñena tenāhamiṣṭaḥ syāmiti me matiḥ', meaning: 'And whoever studies this sacred dialogue of ours will have worshipped Me through the sacrifice of knowledge — such is My view.', inShort: 'Studying this dialogue is itself worship of Me.'),
  GitaVerse(chapter: 18, verse: 71, sanskrit: 'श्रद्धावाननसूयश्च शृणुयादपि यो नरः |\nसोऽपि मुक्तः शुभाँल्लोकान्प्राप्नुयात्पुण्यकर्मणाम्', transliteration: 'śraddhāvānanasūyaśca śṛṇuyādapi yo naraḥ .\nso.api muktaḥ śubhāṃllokānprāpnuyātpuṇyakarmaṇām', meaning: 'And even one who simply listens to it with faith and without scorn will be freed and reach the auspicious worlds of the righteous.', inShort: 'Even listening with faith brings freedom and blessing.'),
  GitaVerse(chapter: 18, verse: 72, sanskrit: 'कच्चिदेतच्छ्रुतं पार्थ त्वयैकाग्रेण चेतसा |\nकच्चिदज्ञानसम्मोहः प्रनष्टस्ते धनञ्जय', transliteration: 'kaccidetacchrutaṃ pārtha tvayaikāgreṇa cetasā .\nkaccidajñānasammohaḥ pranaṣṭaste dhanañjaya', meaning: 'Have you heard this with a focused mind, O Partha? Has your confusion born of ignorance been destroyed, O Dhananjaya?', inShort: 'Krishna asks if Arjuna\'s confusion is gone.'),
  GitaVerse(chapter: 18, verse: 73, sanskrit: 'अर्जुन उवाच |\nनष्टो मोहः स्मृतिर्लब्धा त्वत्प्रसादान्मयाच्युत |\nस्थितोऽस्मि गतसन्देहः करिष्ये वचनं तव', transliteration: 'arjuna uvāca .\nnaṣṭo mohaḥ smṛtirlabdhā tvatprasādānmayācyuta .\nsthito.asmi gatasandehaḥ kariṣye vacanaṃ tava', meaning: 'Arjuna said: My delusion is destroyed, and I have regained my memory through Your grace, O Achyuta. I stand firm, free of doubt. I will do as You say.', inShort: 'Arjuna\'s doubts are gone; he will act as Krishna says.'),
  GitaVerse(chapter: 18, verse: 74, sanskrit: 'सञ्जय उवाच |\nइत्यहं वासुदेवस्य पार्थस्य च महात्मनः |\nसंवादमिममश्रौषमद्भुतं रोमहर्षणम्', transliteration: 'sañjaya uvāca .\nityahaṃ vāsudevasya pārthasya ca mahātmanaḥ .\nsaṃvādamimamaśrauṣamadbhutaṃ romaharṣaṇam', meaning: 'Sanjaya said: Thus I have heard this wondrous dialogue between Vasudeva and the great-souled Partha, which makes my hair stand on end.', inShort: 'Sanjaya marvels at the dialogue he has witnessed.'),
  GitaVerse(chapter: 18, verse: 75, sanskrit: 'व्यासप्रसादाच्छ्रुतवानेतद्गुह्यमहं परम् |\nयोगं योगेश्वरात्कृष्णात्साक्षात्कथयतः स्वयम्', transliteration: 'vyāsaprasādācchrutavānetadguhyamahaṃ param .\nyogaṃ yogeśvarātkṛṣṇātsākṣātkathayataḥ svayam', meaning: 'By the grace of Vyasa, I have heard this supreme and secret yoga directly from Krishna, the Lord of yoga, as He Himself spoke it.', inShort: 'By Vyasa\'s grace, Sanjaya heard Krishna\'s words directly.'),
  GitaVerse(chapter: 18, verse: 76, sanskrit: 'राजन्संस्मृत्य संस्मृत्य संवादमिममद्भुतम् |\nकेशवार्जुनयोः पुण्यं हृष्यामि च मुहुर्मुहुः', transliteration: 'rājansaṃsmṛtya saṃsmṛtya saṃvādamimamadbhutam .\nkeśavārjunayoḥ puṇyaṃ hṛṣyāmi ca muhurmuhuḥ', meaning: 'O king, as I recall again and again this wondrous and sacred dialogue between Keshava and Arjuna, I rejoice again and again.', inShort: 'Remembering the dialogue, Sanjaya rejoices again and again.'),
  GitaVerse(chapter: 18, verse: 77, sanskrit: 'तच्च संस्मृत्य संस्मृत्य रूपमत्यद्भुतं हरेः |\nविस्मयो मे महान् राजन्हृष्यामि च पुनः पुनः', transliteration: 'tacca saṃsmṛtya saṃsmṛtya rūpamatyadbhutaṃ hareḥ .\nvismayo me mahān rājanhṛṣyāmi ca punaḥ punaḥ', meaning: 'And as I recall again and again that most wondrous form of Hari, great is my amazement, O king, and I rejoice again and again.', inShort: 'Recalling Krishna\'s cosmic form fills Sanjaya with wonder.'),
  GitaVerse(chapter: 18, verse: 78, sanskrit: 'यत्र योगेश्वरः कृष्णो यत्र पार्थो धनुर्धरः |\nतत्र श्रीर्विजयो भूतिर्ध्रुवा नीतिर्मतिर्मम', transliteration: 'yatra yogeśvaraḥ kṛṣṇo yatra pārtho dhanurdharaḥ .\ntatra śrīrvijayo bhūtirdhruvā nītirmatirmama', meaning: 'Wherever there is Krishna, the Lord of yoga, and wherever there is Partha, the archer, there will surely be fortune, victory, prosperity, and righteousness. This is my conviction.', inShort: 'Where Krishna and Arjuna are, there is victory and goodness.'),
];
